window.POEM_DB=window.POEM_DB||{};POEM_DB["ming_026"]={"n":"刘基","dyn":"明","poems":[{"t":"秋日即事 其二","f":"七言绝句","c":["杨柳新栽半出篱，夜深鸟鹊自鹭枝。","露凉月淡空烟暝，啼到金鸡报晓时。"]},{"t":"秋日即事 其三","f":"七言绝句","c":["九月东风露不寒，蟪蛄相庆语檐端。","野人便拟开荒径，剩种忘忧与合欢。"]},{"t":"秋日即事 其四","f":"七言绝句","c":["摇落江皋草满烟，秋光何处不堪怜。","夜凉银汉低城阙，卧听蛩声似筦弦。"]},{"t":"秋日即事 其十二","f":"七言绝句","c":["满天星月一庭烟，坐掩衡门思悄然。","漫想明珠成薏苡，却嫌黄菊似金钱。"]},{"t":"秋日即事 其十三","f":"七言绝句","c":["疏雨鸣檐月在云，马蹄初歇夜将分。","雁行却向城头过，何处砧声隐隐闻。"]},{"t":"秋日即事 其十四","f":"七言绝句","c":["江上秋高暑未归，照书犹有数萤飞。","东风可是怜游子，不遣看天忆授衣。"]},{"t":"锦堂春","f":"古风","c":["墙角含霜树静，楼头作雪云垂。","钩帘鹊噪空庭晚，坐看月来时。","异域书迷雁足，幽闺镜掩虫丝。","一宵两地肠千转，惟有梦魂知。"]},{"t":"五月十九日大雨","f":"七言绝句","c":["风驱急雨洒高城，云压轻雷殷地声。","雨过不知龙去处，一池草色万蛙鸣。"]},{"t":"过闽关九首 其一","f":"七言绝句","c":["关头雾露白濛濛，关下斜阳照树红。","过了秋风浑未觉，满山粳稻八闽中。"]},{"t":"题沙溪驿","f":"七言绝句","c":["阔水弯弯绕郡城，老蝉鸣入车轮声。","西风吹客上马去，夕阳满川红叶明。"]},{"t":"古戍","f":"五言律诗","c":["古戍连山火，新城殷地笳。","九州犹虎豹，四海未桑麻。","天迥云垂草，江空雪覆沙。","野梅烧不尽，时见两三花。"]},{"t":"春兴七首 其四","f":"七言律诗","c":["会稽南镇夏王封，蔽日腾空紫翠重。","阴洞烟霞辉草木，古祠风雨出蛟龙。","玄夷此日归何处，玉简他年岂再逢。","安得普夫休战伐，不令竹箭困输供。"]},{"t":"北风行","f":"七言绝句","c":["城外萧萧北风起，城上健儿吹落耳。","将军玉帐貂鼠衣，手持酒杯看雪飞。"]},{"t":"田家","f":"五言古诗","c":["田家无所求，所求在衣食；","丈夫事耕稼，妇女攻纺绩，侵晨荷锄出，暮夜不遑息。","饱暖匪天降，赖尔筋与力。","租税所从来，官府宜爱惜。","如何恣刻剥，渗漉尽涓滴。","怪当休明时，狼藉多盗贼。","岂无仁义矛，可以弭锋镝。","安得廉循吏，与国共欣戚，清心罢苞苴，养民瘳国脉。"]},{"t":"旅兴 其四十一","f":"五言古诗","c":["寒灯耿幽幕，虫鸣清夜阑。","起行望清天，明月在云端。","美人隔千里，山河杳漫漫。","玄云翳崇冈，白露凋芳兰。","愿以绿绮琴，写作行路难。","忧来无和声，弦绝空长叹。"]},{"t":"旅兴 其二十三","f":"五言古诗","c":["倦鸟冀安巢，风林无静柯。","路长羽翼短，日暮当如何。","登高望四方，但见山与河。","宁知天上雨，去为沧海波。","慷慨对长风，坐感玄发皤。","弱水不可航，曾城岌嵯峨。","凄凉华表鹤，太息成悲歌。"]},{"t":"畦桑词","f":"古风","c":["编竹为篱更栽剌，高门大写畦桑字。","县官要备六事忙，村村巷巷催畦桑。","桑畦有增不可减，准备上司来计点。","新官下马旧官行，牌上却改新官名。","君不见古人树桑在墙下，五十衣帛无冻者。","今日路傍桑满畦，茅屋苦寒中夜啼。"]},{"t":"感怀三十一首 其二十八","f":"五言古诗","c":["槁叶寒搣搣，罗帐秋风生。","凄凄候虫鸣，唳唳宾鸿惊。","美人抱瑶瑟，仰视河汉明。","丝桐岂殊音，古调非今声。","沉思空幽寂，岁月巳徂征。"]},{"t":"感怀三十一首 其二十","f":"五言古诗","c":["结发事远游，逍遥观四方。","天地一何阔，山川杳茫茫。","众鸟各自飞，乔木空苍凉。","登高见万里，怀古使心伤。","伫立望浮云，安得凌风翔？"]},{"t":"感怀三十一首 其二","f":"五言古诗","c":["驱车出门去，四顾不见人。","回风卷落叶，飒飒带沙尘。","平原旷千里，莽莽尽荆榛。","繁华能几何，憔悴及兹辰。","所以芳桂枝，不争桃李春。","云林耿幽独，霜雪空相亲。"]},{"t":"水龙吟","f":"古风","c":["鸡鸣风雨潇潇，侧身天地无刘表。","啼鹃迸泪，落花飘恨，断魂飞绕。","月暗云霄，星沉烟水，角声清袅。","问登楼王粲，镜中白发，今宵又添多少？","极目乡关何处，渺青山、髻螺低小。","几回好梦，随风归去，被渠遮了。","宝瑟弦僵，玉笙簧冷，冥鸿天杪。","但侵阶莎草、满庭绿树，不知昏晓。"]},{"t":"沁园春 和郑德章暮春感怀呈石末元帅","f":"古风","c":["万里封侯，八珍鼎食，何如故乡。","柰狐狸夜啸，腥风满地，蛟螭昼舞，平陆成江。","中泽号鸿，苞荆集鸨，软尽平生铁石肠。","凭阑看，但云霓明灭，烟草苍茫。","不须踽踽凉凉，盖世功名百战场。","笑杨雄寂寞，刘伶沈湎，嵇生纵诞，贺老清狂。","江左夷吾，关中宰相，济弱扶倾计甚长。","桑榆外，有轻阴乍起，未是斜阳。"]},{"t":"九叹九首 其一","f":"楚辞体","c":["秋风起兮夕露漙。","浮云沉阴兮白日昼寒。","木叶落兮水泉乾。","孤雁鸣兮悽以酸。","揽余辔兮怅盘桓。","野萧条兮行路难。","豺狼骄兮狐兔顽。","兰蕙死兮荆棘蕃。","我欲奋飞兮无羽翰。","援雅琴兮发哀弹。","弦断绝兮涕汎澜。"]},{"t":"次韵和刘彦箕忆山中篇","f":"七言古诗","c":["句曲峰高倚太阳，不风岩谷自清凉。","四时岚彩霏夔雪，百道泉流湛玉霜。","雅称采芝追绮季，尤宜散发学嵇康。","龙鳞璀错松当径，凤尾䙰褷竹过墙。","月上海门蟾早觉，露寒瑞草鹤先尝。","仙人卓剑降魑魅，道士书符禁獝狂。","宝气丹光生夜寂，黄精白朮引年长。","茅君虎卧瑶坛上，萧史鸾栖碧殿旁。","桂树寒山违谢客，桃花流水忆刘郎。","猿猱任占青萝帐，薜荔从生绿石床。","世难有身空自累，诗成无雁倩谁将。","欲凭锦瑟传幽思，才理朱弦意巳忘。"]},{"t":"汉宫曲","f":"七言绝句","c":["小雨如烟昼掩扉，捲帘忽见燕双飞。","不知春色能多少，总向昭阳柳上归。"]},{"t":"江上曲八首 其四","f":"七言绝句","c":["紫桂香销五夜霜，碧云收尽玉蟾光。","琅玕不是人间树，何处朝阳有凤凰。"]},{"t":"江上曲八首 其五","f":"七言绝句","c":["月出前山青黛寒，雁声遥下碧云端。","草根错认骊珠吐，自是西风白露团。"]},{"t":"江上曲八首 其六","f":"七言绝句","c":["宾雁来时月满洲，于今雁去月如钩。","雁来雁去何时了，月照离人又白头。"]},{"t":"江上曲八首 其八","f":"七言绝句","c":["红蓼丹枫一色秋，楚云吴水共悠悠。","人间万事西风过，惟有沧江日夜流。"]},{"t":"寒夜谣 其一","f":"古风","c":["良夜悠悠，星河满天。","风吹窗棂，声如管弦。","无酒可饮，寒不能眠。","枯肠饥鸣，百虑交煎。","人生一世，不满百年。","寤寐怀思，曷维其然。","内省不疚，有愧圣贤。"]},{"t":"寒夜谣 其二","f":"古风","c":["今夕何夕，岁聿其徂。","草木凋落，山川萦纡。","瞻彼鸿雁，拂翼天衢。","雍雍和鸣，载悠载徐。","虽无羽翰，心与之俱。","华月出云，青镫在隅。","歌以写怀，云何其旴。"]},{"t":"长歌续短歌","f":"七言古诗","c":["短歌调促情苦悲，长歌引愁无绝期。","短声欲尽长声续，似是荆山人泣玉。","悲哉荆山泣玉人，但知贵玉不贵身。","纵令哭尽歌堪听，何异春花委路尘。","古称悲歌可当哭，伤心如中金石镞。","更不必听蔡琰笳，又不必听渐离筑。","长歌飘扬彻九天，短歌呜咽入九泉。","徒言歌哭两情异，谁知歌声尤可怜。"]},{"t":"望行人","f":"古风","c":["朝听乾鹊鸣，暮见灯花结。","鹊鸣灯结无定期，镜里青云看成雪。","人生百岁难长保，天上孤鸾海中老。","滔滔逝水不回西，灼灼秋花几时好。","一朝复一朝，一夕复一夕，只恐君心念妾时，妾身巳作山头石。"]},{"t":"旅兴 其一","f":"五言古诗","c":["初秋积雨过，众绿光如濡。","莎鸡啼高树，蟋蟀鸣阶除。","时物巳改故，芳年从此徂。","荣名非我愿，守分敢求馀。","登楼眺远郊，肆目望天衢。","明月出云中，照我华发疏。","还归掩关卧，梦到园田居。"]},{"t":"旅兴 其二","f":"五言古诗","c":["忆年二三十，笑人不能勤。","诵书歘万言，落笔飞烟云。","有朋自远来，讲论穷朝曛。","一艺耻不知，高蹈躐前闻。","宁知有衰老，耳聋目如熏。","身世且未保，况敢言功勋。"]},{"t":"旅兴 其三","f":"五言古诗","c":["老不与懒期，身老懒自至。","懒不与傲期，力惫难强事。","茫茫视天宇，忽忽心如醉。","劳生谅何庸，顾为形所累。","弱水隔蓬莱，安得生两翅。"]},{"t":"旅兴 其四","f":"五言古诗","c":["秋风肃万物，百虫竞号鸣。","蟪蛄最可怜，切切悲其生。","屣履步庭除，素月圆且明。","玩之不可掇，渺焉忽西倾。","回身掩房闼，怆恍烦虑盈。","太息以终宵，展转难为情。"]},{"t":"旅兴 其五","f":"五言古诗","c":["侥福非所希，避祸敢不慎。","富贵实祸枢，寡欲自鲜吝。","疏食可以饱，肥甘乃锋刃。","探珠入龙堂，生死在一瞬。","何如坐蓬荜，默默观大运。"]},{"t":"旅兴 其六","f":"五言古诗","c":["紫燕来我檐，营巢养其雏。","拾虫扑我衣，衔泥污我书。","雏成复生子，风雨同安居。","一旦舍我去，瞻之起长吁。","死别不可追，生别那可思。","悼往恨节促，待来恚时迟。"]},{"t":"旅兴 其八","f":"五言古诗","c":["秋气虽可悲，秋色亦可悦。","寥寥天宇旷，皎皎县象晢。","雁来山叶红，龙卧江潭洁。","彼美黄金花，含英耀穷节。","佳人不可期，明月圆复缺。","空庭夕阴尽，露草白如雪。","伫立望四方，弥使忧念结。"]},{"t":"旅兴 其九","f":"五言古诗","c":["穷巷屏人迹，开门见青山。","青山似故乡，客子何当还。","蟪蛄日夜鸣，绿树亦巳殷。","白日驶西征，浮云不可攀。","安得生羽翼，奋飞出玄间。"]},{"t":"旅兴 其十","f":"五言古诗","c":["雨来群山暗，雨过群山明。","山明猿鸟喜，山暗猿鸟惊。","岁暮阴风起，白日西南倾。","寒蝉枝上号，阜螽草閒鸣。","人生非草木，能无感中情。"]},{"t":"旅兴 其十一","f":"五言古诗","c":["赤霞变玄云，风起烟雾塞。","飕飕木叶响，曀曀原野黑。","青泥没委巷，关塞生咫尺。","水深蛟龙恣，山湿鸟兽寂。","留滞荷戈人，艰难去乡客。","翘首望太阳，忧思萃朝夕。"]},{"t":"旅兴 其十二","f":"五言古诗","c":["望舒乘罕车，潜蜦跃重渊。","二仪烟雾交，九泽风云连。","丘陵冒潢潦，沟浍成通川。","鹳鹤失其巢，穷猿鸣可怜。","蛙黾一何乐，喧呼聒宵眠。"]},{"t":"旅兴 其十四","f":"五言古诗","c":["昃景无还晖，霜露凄巳繁。","松柏坐椔翳，桃李更何言。","旦夕悲风起，黄沙蔽平原。","万物尽凋落，芳华谁独存。","我愿化为鹤，不愿化为猿。","鹤鸣声闻天，猿鸣烟雨昏。","空林夜寥寂，踯躅伤精魂。"]},{"t":"旅兴 其十五","f":"五言律诗","c":["西风吹硕果，草茅思索绹。","搣搣卉木零，唧唧寒虫号。","百川日夜流，泰山何其高。","沉浮自有定，汲汲无乃劳。"]},{"t":"旅兴 其十六","f":"五言古诗","c":["久雨得晚霁，豁然如醉醒。","幽花衒馀红，远峰出孤青。","独坐无与娱，蜻蛚吟空庭。","良辰能几何，逝者忽如倾。","啸歌欲自慰，歌竟还伤情。"]},{"t":"旅兴 其十七","f":"五言古诗","c":["微风振檐铎，玱如环佩响。","登高看秋色，俯见明月上。","木落天地宽，云散川原广。","来者不可期，逝者日巳往。","离居岂无怀，恻怆萦远想。"]},{"t":"旅兴 其十八","f":"五言律诗","c":["日暮登高台，流目盼云间。","云间有明月，窈窕芙蓉颜。","光辉被四表，万古一往还。","惜无腾化术，仰之不能攀。"]},{"t":"旅兴 其十九","f":"五言古诗","c":["江上秋风急，天寒雁南归。","客子眷长途，中心一何悲。","顾瞻望四方，有怀当告谁。","霜露日夜零，百卉厌其枝。","衰谢不待期，荣盛安可追。","太息复太息，怆悢涕沾衣。"]},{"t":"旅兴 其二十","f":"五言古诗","c":["薄云敛微雨，返照涵空烟。","黄葵閒红蓼，烂若濯锦鲜。","老病苦无欢，坐为忧所缠。","自恨非松乔，不能还少年。","援琴写此曲，曲尽心茫然。"]},{"t":"旅兴 其二十二","f":"五言古诗","c":["翔鹍抟扶摇，九万一奋翅。","骅骝骤康庄，瞬息千里至。","谷鲋穴坎窞，鹪鹩集蓬蔚。","偪仄岂不怜，饮啄亦何忌。","夸父空有勇，精卫良无智。","翼折海未枯，身偾杖徒弃。","何如抱区区，保巳遗世事。"]},{"t":"旅兴 其二十四","f":"五言古诗","c":["病身如朽木，螬蚁群萃之。","生意巳无多，雨露空其滋。","晨兴步庭除，足弱几不持。","论年未应尔，胡为遽如斯。","大块播万形，一躯非我私。","暂假终必还，但有速与迟。","居易以俟命，圣言岂吾欺。"]},{"t":"旅兴 其二十五","f":"五言古诗","c":["上古人一心，生荣死同哀。","永世自为心，骨肉多嫌猜。","沉沉十日雨，漫漫百亩苔。","苔深车轮没，平路生蒿莱。","呜呼张仲蔚，衡门何由开。"]},{"t":"旅兴 其二十六","f":"五言古诗","c":["疏庸厌人事，疲病畏交游。","得闲愿巳惬，敢有分外求。","开门对钟山，山翠盈我眸。","日中市声远，草绿空庭幽。","登临观万象，玄理足可搜。","谁能走逐逐，自使生悔尤。"]},{"t":"旅兴 其二十七","f":"五言古诗","c":["别离多苦怀，三年当百载。","来者非所知，往者今安在。","浮云旦夕起，白日埋光彩。","天地亦有形，岂能长不改。","去去东园公，紫芝犹可采。"]},{"t":"旅兴 其二十八","f":"五言古诗","c":["晨兴梳短发，庭树生秋风。","万物有容色，与故各不同。","硕实属老成，天柔怨童蒙。","英英黄金花，旎旎清露丛。","岁暮等沦落，何异蒿与蓬。"]},{"t":"旅兴 其二十九","f":"五言律诗","c":["庭前草华发，夜凉萤火流。","有怀不能寐，起望女与牛。","那无一苇航，繁念空悠悠。","泪如宵露零，散漫不可收。"]},{"t":"旅兴 其三十一","f":"五言古诗","c":["忡忡坐虚室，暧暧日向暮。","空烟敛曾岑，暝色半高树。","缅邈起遐思，逍遥散轻步。","婵娟天上月，的皪草间露。","物情岂异昔，人事殊非故。","芳岁不可淹，衰年况多虑。","谅无彭铿术，颓龄那能驻。"]},{"t":"旅兴 其三十二","f":"五言古诗","c":["夭夭芙蓉花，向晚犹媚妩。","娟娟明月辉，粲粲当庭户。","寒衾耿长夜，梦寐空自语。","劳生遘六极，老病在羁旅。","将思诉穹玄，恨无抟风羽。"]},{"t":"旅兴 其三十三","f":"五言古诗","c":["大火没西南，昼短宵巳长。","志士郁慷慨，老年怨凄凉。","萧萧草虫鸣，肃肃苍隼扬。","物情各有定，人意苦不常。","信步陟崇丘，流目睇康庄。","宁为款段驽，勿作骐骥良。","款段驾鼓车，道里有限量。","骐骥被重甲，力尽百战场。","死骨卖千金，虽贵亦何偿。"]},{"t":"旅兴 其三十五","f":"五言古诗","c":["青青潇湘竹，猗猗被寒水。","游子如飞蓬，佳人旷千里。","登高左右望，但见黄尘起。","凤凰翔不下，梧桐化为枳。","伤怀不可道，忧念何时巳。"]},{"t":"旅兴 其三十六","f":"古风","c":["吾观穹壤间，万变皆有穷。","何如顺天道，原始以知终。","清晨揽衣起，絺绤生秋风。","雍雍鸣雁来，灼灼酸枣红。","怅焉念所思，悲感集予衷。","佳期在何许，瑶草成枯蓬。","伫立望日月，劳心极??。"]},{"t":"旅兴 其三十九","f":"五言古诗","c":["乌鸣朝哑哑，鹊鸣暮啾啾。","闻鹊既不喜，闻鸟复何忧。","世人务苟得，君子绝外求。","沧浪迅风波，无风即安流。","胡为自冰炭，以贻达者羞。"]},{"t":"旅兴 其四十","f":"五言古诗","c":["严风萃群有，蝇蚊亦无多。","所憎虽去眼，若此岁晏何。","中夜揽衣裳，起视星与河。","出云未还山，落叶早辞柯。","沉思不成寐，太息继以歌。"]},{"t":"旅兴 其四十二","f":"五言古诗","c":["秋山青如烟，秋月白如水。","登高俯空旷，咫尺见千里。","悠悠孤云行，袅袅凉风起。","凉风吹客衣，客心随风飞。","愿作沧海潮，朝来莫还归。"]},{"t":"旅兴 其四十五","f":"五言古诗","c":["久旱草不生，一雨青满地。","新荑与旧蘖，好丑各自媚。","喈喈黄莺吟，习习玄鸟至。","闲庭人迹稀，白日澹清气。","平生孟公绰，庶足无妄觊。","但愿长若斯，拨置身外事。"]},{"t":"旅兴 其四十六","f":"五言古诗","c":["江城夜来雨，雷音亦何砰。","今晨视郊原，草木皆发荣。","双双布谷儿，来我墙上鸣。","园蔬犹可艺，无忘及时耕。","倦翮得安巢，感荷天地生。"]},{"t":"旅兴 其四十八","f":"五言古诗","c":["秋高潦水涸，旻天亦凄清。","枯箨响悲音，羁虫振馀声。","曀曀落日晖，惨惨游子情。","风林无定枝，驰车鲜安旌。","自愧匪贤达，默默嗟其生。"]},{"t":"旅兴 其四十九","f":"五言律诗","c":["山鬼处幽壑，自分不见天。","宁知无私照，及此暗井泉。","倦鸟思故林，穷鱼思故渊。","感荷实难忘，庶其保终年。"]},{"t":"旅兴 其五十","f":"五言古诗","c":["铩羽畏高风，疲马厌长道。","玄阴促暮节，何物能不老？","自非松柏质，敢冀出众草。","登山临流水，及此晴日好。","春芳蔼兰蕙，秋实栗粳稻。","黄精肥可食，石泉清可澡。","荣名何足言，息心以为宝。"]},{"t":"过苏州 其一","f":"七言绝句","c":["姑苏台下垂杨柳，曾为张王护禁城。","今日淡烟芳草里，暮蝉犹作管弦声。"]},{"t":"过苏州 其二","f":"七言绝句","c":["姑苏台下垂杨柳，落叶萧萧日暮风。","天地山河有真主，迎来送往总成空。"]},{"t":"过苏州 其三","f":"七言绝句","c":["忆昔吴宫无事时，满城杨柳舞西施。","如今柳尽西施死，恨杀当年陌上儿。"]},{"t":"过苏州 其四","f":"七言绝句","c":["陌上清歌最可听，谁知此是断肠声。","就中更有杨枝曲，恨杀昏鸦及晓莺。"]},{"t":"过苏州 其五","f":"七言绝句","c":["虎丘山下月朦胧，阊阖门前动地风。","子夜一声琴一阕，杜鹃声在碧云中。"]},{"t":"过苏州 其六","f":"七言绝句","c":["灯映前窗纸不鸣，四邻无语犬号声。","南阳巳起为霖了，何用人间更得名。"]},{"t":"过苏州 其七","f":"七言绝句","c":["满地寒风满面尘，荒烟白草旧通津。","晏安酖毒俱亡国，可但西施解误人。"]},{"t":"过苏州 其八","f":"七言绝句","c":["成败由天众所知，乌江拔剑更何疑。","谁言碧海剸蛟手，也学临春井底儿。"]},{"t":"过苏州 其九","f":"七言绝句","c":["小雨如膏渍陌尘，一沟寒碧晓生鳞。","馀年巳自无多子，更向途中见早春。"]},{"t":"漫成 其七","f":"五言绝句","c":["萱草花空发，丁香子又生。","浮云无处所，孤月不须明。"]},{"t":"漫成 其九","f":"五言绝句","c":["望帝千年魄，声声是泪流。","空庭无竹树，省得一春愁。"]},{"t":"老病叹","f":"七言古诗","c":["我身衰朽百病加，年未六十眼巳花。","筋牵肉颤骨髓竭，肤腠剥错疮与瘸。","人皆爱我馈我药，暂止信宿还萌芽。","肺肝上气若潮涌，旧剂再歠犹淋沙。","有眼不视非我目，有齿不齧非我牙。","三黄苦心徒自瘵，五毒浣胃空矛戈。","因思造物生我日，脩短巳定无舛差。","琚瓆不能使之少，卢秦焉能使之加。","攻犀盬朽各有分，凫悲鹤悼何缪耶。","不如闭户谢客去，有酒且饮辞諠哗。"]},{"t":"漫成","f":"七言律诗","c":["老去知心更有谁，愁将短发对花枝。","花残更发新春叶，发白空垂满面丝。","纵酒放歌怜往日，倚阑听雁立多时。","若为化得抟风翮，汗漫东西信所之。"]},{"t":"有感 其一","f":"七言绝句","c":["物换星移事巳迷，重来旧处惑东西。","可怜如镜天边月，独照栖乌半夜啼。"]},{"t":"有感 其二","f":"七言绝句","c":["焚书千古讶嬴秦，逃难茫茫走缙绅。","尚忆商山近京洛，白头容得采芝人。"]},{"t":"有感 其三","f":"七言绝句","c":["甲楯孤栖死不疑，那将宗社换西施。","想应尝胆秋风夜，恰似无忘携李时。"]},{"t":"有感 其四","f":"七言绝句","c":["鸿雁来时月满天，客途僮仆自相怜。","荒村触眼惟茅屋，榆柳萧疏起暮烟。"]},{"t":"有感 其五","f":"七言绝句","c":["黍穗高低菊有华，廛居恰似野人家。","夕阳日向西墙过，只为微生换鬓华。"]},{"t":"有感 其六","f":"七言绝句","c":["鱼盐充牣稻粱肥，谁寤繁华是祸机。","日暮无人唁亡国，寒鸦犹带夕阳飞。"]},{"t":"有感 其七","f":"七言绝句","c":["漫漫阳春不见秋，人生得意总忘愁。","茱萸谢尽芙蓉发，清夜吹笙月满楼。"]},{"t":"古歌 其一","f":"七言律诗","c":["红葵高花高以妍，清晨方开夕就蔫。","美人迢迢隔山水，可望不见心茫然。","花开花落日复夜，惟觉新年非故年。","人生百岁花一度，何不作乐令人怜。"]},{"t":"古歌 其二","f":"七言律诗","c":["旧花欲落新花好，新人少年旧人老。","佳人见此心相怜，举觞劝我学神仙。","我闻神仙亦有死，但我与子不见耳。","秪言老彭寿最多，八百岁后还如何。"]},{"t":"古歌 其三","f":"七言律诗","c":["双燕双飞入我堂，衔泥养雏何太忙。","养得雏成却飞去，双燕双飞复如故。","东园桃李春萋萋，日华烘露生紫霓。","一朝实熟付人采，叶枯枝折空成蹊。"]},{"t":"夜泊桐江驿","f":"七言绝句","c":["伯夷清节太公功，出处非邪岂必同。","不是云台兴帝业，桐江无用一丝风。"]},{"t":"松叶酒歌寄梁安宅","f":"七言古诗","c":["道人赠我松叶酒，味似琼浆色琼玖。","咽之骨爽神魂清，令我寿同金石久。","我生疏懒无所能，瘦皮黏骨危崚嶒。","病来啖药犹啖水，梦寐恍惚风中灯。","常闻徂徕有嘉木，玄醴涤濯黄露沐。","上有菟丝扬翠旌，下有茯苓蹲白鹿。","咀华嚼叶咽以津，岁久定化肠为筋。","便从偓佺觐黄帝，身骑肉角青骐驎。","我欲求之百忧集，满眼蚊蝇随出入。","踆乌箭逝纤阿急，日暮空瞻邓林泣。","道人此酒还有方，我欲与子同徜徉。","世上神仙亦何限，留侯辟谷应未晚。"]},{"t":"侍宴钟山应制","f":"七言律诗","c":["清和天气雨晴时，翠麦黄花夹路岐。","万里玉关驰露布，九霄金阙绚云旗。","龙文騕袅骖鸾辂，马乳蒲萄入羽卮。","衰老自惭无补报，叨陪仪凤侍瑶池。"]},{"t":"秋怀 其一","f":"五言古诗","c":["东风吹晨霞，初日垂白足。","湿烟屯檐栋，飞雨鸣朴樕。","厌厌叶就黄，萋萋草还绿。","索居谢喧嚣，庭绝车马躅。","念来多所怀，追往不可复。","懒随老共至，病与年相促。","省躬惭寡尤，守分无望福。","驽骀立皂枥，敢慕骐骥逐。"]},{"t":"秋怀 其三","f":"五言古诗","c":["空阶走穴蚁，荒垤唳巢鹳。","阴氛方腾达，密雨巳弥漫。","沉沉翳光景，昧昧感昏旦。","林鸦湿休飞，檐雀饥相唤。","跬步隔关河，四望空慨叹。","悽悽衣裳单，戚戚岁年晏。","微生如石火，徒劳暂时焕。","永寤烂柯人，万事一梦幻。"]},{"t":"秋怀 其四","f":"五言古诗","c":["清晨启扉坐，微风动游龙。","离离墙上花，切切砌下蛩。","喓喓自成音，灼灼各有容。","四序迭推移，衰病情所钟。","身羸足巳弱，有愿不得从。","愧负天地生，怆悢填心胸。"]},{"t":"秋怀 其五","f":"五言律诗","c":["蟋蟀巳在宇，鸿雁方来宾。","天秋风露寒，阴谷何时春。","欲为商声歌，恐惊梁上尘。","衡门掩仲蔚，庶用存吾真。"]},{"t":"秋怀 其八","f":"五言古诗","c":["薄云散高风，天色青如染。","盈庭露辉辉，当窗星燄燄。","寒来爱兰釭，暑往却筠簟。","忧思浩无际，起坐数更点。","晦明相代谢，避盈乃无歉。","未尝陟孟门，谁识行路险。","贾害岂无因，戒之在怀琰。","冥豫何可长，用之以自检。"]},{"t":"题谢皋羽传后","f":"古风","c":["阮籍哭穷途，墨翟哭素丝。","贾谊上书期寤主，卞和抱玉无人知。","人生有情不可塞，谢生恸哭非狂痴。","神奔鬼遁天地革，龙鱼猫虎三辰黑。","黼裳玄衮换毡裘，鞮唱羌歌满中国。","生也何辜逢此时，有才不用空男儿。","伯益丘墟管仲没，孤根弱植谁扶持？","既不能学申胥顿首血沾臆，却吴再建荆社稷。","又不能学邹衍长号彻帝关，飞霜六月凄燕山。","空将泪洒荒冈雨，添作秋涛撼江浦。","君不见杞梁之妻善哭夫，哭得城崩又何补？","夜猿叫罢天晦冥，哭声摇动虚危星。","潇湘竹死凤凰去，但见白波连洞庭。","呜呼此士今安在，金石可销心不改。","应将魂魄化精卫，衔取南山填北海。"]},{"t":"秋感","f":"五言律诗","c":["老病偏多感，宵长昼亦长。","衣冠方谢暑，枕席巳惊凉。","往事镌心在，新知过眼忘。","篱边旧栽菊，岁晚为谁黄。"]},{"t":"秋感","f":"七言律诗","c":["日白天青木叶凋，云山漫漫故乡遥。","石床坠露珠光动，碧砌幽花玉色销。","十载故人俱土壤，五更归梦负渔樵。","怀来忆往成惆怅，蔓草羁虫对寂寥。"]},{"t":"悼废圃残菊","f":"七言律诗","c":["旧菊将芜尚有根，高秋相顾耿无言。","芳心不共青莎死，生态犹欺白露繁。","要待灵均餐落蕊，从教元亮耻空尊。","何人解识凄凉意，分付寒螀仔细论。"]},{"t":"杂诗 其二","f":"五言古诗","c":["白露出草根，颗颗如明珠。","黄华炫金钱，亦复盈阶除。","闲居无尤物，玩之聊可娱。","衡门不必扃，此非众所须。","但恐成薏苡，千载令人吁。"]},{"t":"杂诗 其三","f":"五言古诗","c":["服力徇穑事，矻矻望有秋。","凌晨荷锄出，日入且未休。","中夜看星辰，旱潦切所忧。","西成告丰岁，珠玑满田畴。","饱食幸可期，喜色欲盈眸。","宁知霜雪早，零落不得收。","荒畦委滞穗，槿篱挂空篝。","斜阳照白发，短褐还饭牛。","天命固如此，汲汲复何求。"]},{"t":"杂诗 其四","f":"五言古诗","c":["季世罕上寿，百岁为长年。","轩皇不可见，颜冉复谁怜。","安期乘彩虹，羡门驾紫烟。","朝游蓬莱岛，夕宿曾城巅。","常恐声风枝，摧折沧海田。","徒令骊山客，想望称神仙。"]},{"t":"杂诗 其五","f":"五言古诗","c":["月明栖鸟动，月暗栖鸟定。","茅鸱潜枳枸，大眼挂宵镜。","皇天生万物，一物畀一性。","遂令盖壤间，扰扰事争竞。","喧呶穷日夕，岂不慁天听。","化工虽云巧，为法秪自病。","沉思令人嗟，欲问谁与应。"]},{"t":"杂诗 其七","f":"五言古诗","c":["速成非良器，骤得难久好。","桃李望春舒，亦复迎秋槁。","蕣英耀朝日，未夕委蔓草。","饥农种植禾，自庆得食早。","岁暮寒凛冽，衡门净如扫。","瀛洲对方壶，弱水为池沼。","不有千年花，安得如瓜枣。","徐市驾楼船，轻帆迅如鸟。","仙人倘可见，常恐三光老。","寄书附文鳐，碧云空缥缈。"]},{"t":"旧在杭时为冷起敬赋泉石歌乱后失之今起敬为恊律郎邀予写旧作已忘而记其起三句因更足之","f":"古风","c":["君不见吴山削成三百尺，上有流泉发苍石。","冷卿以之调七弦，龙出太阴风动天。","初闻涓涓响林莽，悄若玄宵鬼神语。","玲然穿崖达幽谷，竽籁飕飕振乔木。","永怀帝子来潇湘，瑶环琼佩千鸣珰。","女夷鼓歌交甫舞，月上九疑啼凤凰。","还思娲皇补穹碧，排抉银河通积石。","咸池泻浪入重溟，玉井冰凘相戛击。","三门既凿龙池高，三十六鳞腾夜涛。","丰隆咆哮震威怒，鲸鱼揵尾惊蒲牢。","倏然神怪归寂寞，殷殷馀音在寥廓。","鲛人渊客起相顾，江白山青烟漠漠。","伯牙骨朽今几年，叔夜广陵无续弦。","绝伦之艺不常有，得心应手非人传。","忆昔识子时，西州正繁华。","筝笛沸晨暮，兜离僸佅争矜誇。","子独倘佯泉石里，长日松阴净书几。","取琴为我弹一曲，似掬沧浪洗尘耳。","否往泰来逢圣明，有虞制作超茎英。","和声恊律子能事，罔俾夔挚专其名。"]},{"t":"雪鹤篇赠詹同文","f":"古风","c":["有鹤有鹤丁令威，碧玉为骨玄霜衣。","层城十二身所依，千年伐毛一度归。","洗髓织女黄姑矶，瑶台雪花大十围。","食之神爽肉不肥，乘风振羽芳菲菲。","丹砂结顶烨有煇，咳唾璀错生珠玑。","朝游明星夕大騩，腾光蹑景超巍巍。","滕六骖乘虹蜺騑，蕊宫仙娥顼帝妃。","镕云鍊雨成琼葳，眩晃昼夺扶桑辉。","离眸闪烁不可睇，回猋摐摐翼缟旂。","白虎觳?艮厥腓，鸾鹓鸟鸿鹑鹄翚。","鹭鹗鹳鹊鷢与鵗，局促缩胸潜崿崎。","惟有皓鹤从之飞，竦翮夜过东皇畿。","玲珑琪树戛金徽，砉然长鸣惊海圻。","海波喷作烟雾霏，马衔罔象蹲若鞿。","鲲鲸夭矫相嘘唏，银河腹坚胶蜃豨。","王母桃花冻不绯，五色石裂女娲譩。","祝融上诉开九扉，帝命养之青锁闱。","赐以沆瀣怜其饥，朝朝暮暮朝太微。","翅翎披拂天香馡，北斗粲烂星依稀。","翠霞抱日露未晞，圆肮脩趾逸且颀。","跄跄蹈舞霍以挥，散仙引领空相希。","嗟哉清峻天下稀，勿叹辽东城郭非。","桂华窅洼甘露溰，味美远胜商山薇。","撷英为羞堪咀叽，比之琅玕亦庶几。","盘空硬语去脂韦，歌以赠君君莫讥。"]},{"t":"秋夜听冷恊律弹琴分韵得夜字","f":"五言古诗","c":["秋清众籁寂，华月耿遥夜。","玉琴奏瑶席，逸响发高榭。","微微风入林，稍稍泉出罅。","关关黄鸟春，嘒嘒玄蝉夏。","幽忧北酆语，赫怒西楚咤。","初疑广寒府，和銮起仙驾。","忽惊龙腾霄，雷电劈太华。","凄凉汉宫女，万里异国嫁。","逍遥商山老，芝歌意闲暇。","斯须变暄凉，要妙夺造化。","终焉返淳朴，瑚琏在缫藉。","郑卫失其淫，仪秦失其诈。","虎狼失其攫，乌鸢失其嚇。","大音信希声，馀美甘如蔗。","持此涤尘心，永与筝笛谢。"]},{"t":"青罗山房歌寄宋景濂","f":"楚辞体","c":["若有人兮乃在大江之南，浙河之东。","连山掎拔瀛海上，上与河鼓天津通。","忆昔四女下天来，遗鬟堕剃根庞鸿。","仙华杰出最怪异，望之如云浮太空。","嵚崟峛崺齾齧不可上，荟蔚杂树昏朣胧。","虎龙咆号猿鹤叫，山鬼呵歘生悲风。","嗟哉若人兮，胡为乎其中！","梁檀楠兮柱桂枫，结青萝兮以帡幪。","不剪不伐兮，不盬以攻。","晨岚暮蔼滴晴雨，烟条雾叶相蒙茏。","縿縿兮纚纚菶菶兮蓬蓬。","缭纠要绍兮，若苍龙垂胡降玄穹。","棽丽披离兮，若翠鸾振迅飞蕤氃。","鹂黄和鸣桑扈应，髣髴牙旷之丝桐。","幽泉发窦锵玲珑，六月赤日收蕴隆。","阳凌阴蓄春融融，岩花涧草纷白红。","有时皇初平清夜，骑羊朝帝君琼蕤，羽盖冰玉佩，华月闪烁光成虹。","松吹笙兮竹舞翿，影旆旆兮声沨沨。","娱目悦耳兮乐不可言。","世间尘土何梦梦。","山有芝，隰有葑，石凿凿兮水漴漴。","猗若人兮美且充，饥食倦息兮可以保我躬。","逍遥兮栖迟，又何必访广成于崆峒。"]},{"t":"送姚伯渊之清溪河泊所任","f":"古风","c":["清溪之水通秋浦，石白水清鱼可数。","鲦鲿鯩鲢鲂与鱮，小鱼如针大如杵。","侵晨渔艇浮空来，千夫撒网云烟回。","鸣榔击楫声如雷，水怪駾啄珠宫开。","课鱼使者矢鱼急，冯夷嘘唏龙母泣。","琴高赤鲤纵有神，何暇超腾作人立。","吾观大江之中有壮鱼，名曰海狶头如猪；","群行九十其朋徒，喷沫成雨倏歘肓风俱。","旌阳仙人上天去巳久，平地波涛随处有。","春渊潜鳞陟负冰，时哉罔俾虞人后。","小鱼琐碎獭所捐，大鱼多膏秪自煎。","君不见振振鹭白白如玉，沙头见鱼饥不啄。","一朝飞上瑶华池，紫鹓黄鹄相追随。","俯视秃鹤垂六羽，还共野乌争腐鼠。"]},{"t":"旅夜 其二","f":"五言律诗","c":["昨夜起观星，月在杨板上。","今宵不见月，星影空摇漾。","羽虫飞拂户，灯吐孤火壮。","伫立掩衡门，愁来独惆怅。"]},{"t":"旅夜 其三","f":"五言律诗","c":["客愁常突兀，今夜灯花生。","虽知无喜报，愁亦暂时平。","解襟成独寝，留灯待天明。","喜固不可求，客心恒畏愁。"]},{"t":"道士周玄初鹤林行","f":"七言古诗","c":["鹤林道士轩辕徒，以飙为轮雷为舆。","开山养鹤作骐骥，上下二仪周六虚。","雏成洗髓扶桑窟，缟练羽毛镠铁骨。","声飘碧落玉清扬，影拂太微云灭没。","永夜月明风满林，竹柏戛击笙箫音。","云是旌阳许县令，蹑蹻佩剑来相寻。","靡蓱西枝摇倒景，借去林间两丹顶。","伐蛟北海奠玄冥，斩蜃南讹封浪井。","上穷列缺旁九围，却过度朔山中归。","归来赠我桃树枝，朱衣赤郭手所持。","令我鞭龙抶虓虎，摄缚臊魃如奴虏。","授我尧时松子诀，转睛出电嘘成雨。","钟山秀色连冶城，百花绕屋风泠泠。","焚香独坐诵真诰，坠露点滴流华星。","土伯骏奔从号令，鹤鸣闻天空谷应。","寥阳宝殿歌步虚，河汉当窗回斗柄。","嗟子衰朽杂病攻，盈颠素发吹秋蓬。","空馀硬骨如瘦鹤，因子致意浮丘公。"]},{"t":"为詹同文题浙江月夜观潮图","f":"古风","c":["君不见四时平分成岁功，以秋继夏独不同。","炎官挟长握天柄，七月赤日熺玄穹。","蓐收抱钺蹲白水，野气赫赫摅赪虹。","阳侯喘汗河伯暍，少昊上诉愁天公。","会须万物长养遂，期以仲月虚宵中。","此夜姮娥魄正满，命驾四蟾骖两駥。","指挥禺强出玄渚，荡涤歊熇清霾蒙。","河汉发源牛斗下，曲江上与天津通。","初看屸发起溟徼，如曳组练来于东。","渐闻殷驎鼍鼓发，倏忽万雷声撼风。","天吴掉尾出溟涬，马衔扬鬐招海童。","霓旌缟帐鹭羽帱，瑶台十二浮空濛。","蕊珠仙人乘玉辂，腾驾鹤鹄飞氋氃。","长庚歘霍掞光耀，灵母扶龙嗥戛铜。","宓妃起舞素女从，琼佩綷縩云帡幪。","冰绡雾縠纷飒纚，霜旂雪幡高翳空。","鲸鱼呀呷鲛鳄遁，蒲牢哮吼冯夷宫。","瞿唐巫峡起平地，滟滪若象鏖回潨。","先驱巳过赤亭嶂，后从始发龛山谼。","商声爽淅合群籁，泽国凛凓寒欲冻。","先生玩月坐楼上，夜气澄寂神和冲。","凭阑快睹烦暑退，呼儿命酒浇喉咙。","自舞自歌歌自作，月照白发三千总。","歌声迤飏林壑应，竹树戛击丝与桐。","渊鱼跃波栖鸟作，紫桂绕屋清香融。","君歌曲终响未终，我歌激烈留征鸿。","瞠眸相视俱老矣，况有众病来交攻。","圣明天子御宇宙，威惠与天相比隆。","首丘倘许谢鞿绊，犹有古月光朣胧。","行当唱和三百首，末与潮汐流无穷。"]},{"t":"病眼作","f":"古风","c":["君不见，昔日方相氏，黄金为四目。","精光倏昱夺长庚，导者趋风观者肃。","一朝竣事归有司，委弃尘埃同朽木。","我生两眼粗能视，要探天根窥地轴。","论价未止连城璧，傅声共推天下独。","宁知用誉贵含章，鬼物由来阚高屋。","三彭上谇三卢闻，乘时作衅何其速。","吴回炽炭煎赤汗，灌注清扬发炎燠。","赫如巨鳟出渊沦，褧若锦衣蒙绮縠。","泪渍红桃浥露开，旂昏丹雀披烟宿。","鹧鸪呼雨荔支垂，布谷啼山蓬蔂熟。","雪深太白脒碧鸡，雾苦瑶台落黄鹄。","自分衰年已无几，膂力卒单筋脉缩。","春荣秋悴两茫茫，柳绿花红非所逐。","天公若复可怜生，乞与寸光分粟菽。","无劳指点某在斯，不用南阳潭上菊。"]},{"t":"秋日即事 其一","f":"七言绝句","c":["秋风吹雨冷翛翛，阶下金钱烂漫愁。","鸿雁不来巢燕去，草虫辛苦独知秋。"]},{"t":"秋日即事 其五","f":"七言绝句","c":["春华秋草两悠悠，素发多情却满头。","落叶自随流水去，远山空带夕阳愁。"]},{"t":"秋日即事 其六","f":"七言绝句","c":["垂垂密雨亸脩杨，点点青苔绘短墙。","不是雁声天畔过，争知今日是重阳。"]},{"t":"秋日即事 其七","f":"七言绝句","c":["秋气萧条宋玉悲，西风唯有雁相宜。","秦淮岸上青青草，想见繁霜未落时。"]},{"t":"秋日即事 其八","f":"七言绝句","c":["寒星无数月如钩，槁叶呼风入敝裘。","人世可怜唯有老，镜中憔悴梦中愁。"]},{"t":"秋日即事 其九","f":"七言绝句","c":["挂壁青釭照不眠，相看到此亦堪怜。","露寒霜重残萤尽，肠断秋风忆往年。"]},{"t":"秋日即事 其十","f":"七言绝句","c":["病眼昏昏四顾迷，独行浑似雪中鸡。","花开叶落真成梦，愁听门前过马蹄。"]},{"t":"秋日即事 其十一","f":"七言绝句","c":["槿华数树夕阳时，收拾秋光在短篱。","自紫自红还自碧，祗应独有暮蝉知。"]},{"t":"秋日即事 其十五","f":"七言绝句","c":["北风吹雁过萧萧，旅馆青灯共寂寥。","蓬鬓一时成白雪，老来禁得几秋宵。"]},{"t":"赠杜安道","f":"七言古诗","c":["忆昔天兵伐荆楚，舳舻蔽江齐万橹。","欢声激烈似雷霆，猛气炰炰震貔虎。","拔栅皖城犹俯拾，探穴九江无险阻。","明年大战康郎下，日月坱圠相吞吐。","冯夷蹋浪群水飞，巨鳌掉首三山舞。","云随太乙拥锋旗，鼍为丰隆作灵鼓。","将军金甲箭攒猬，战士铁衣汗流雨。","火龙熺燄绛天衢，燧象豗烟煎地府。","鲸鲵既剪搀抢落，草木熙阳鱼出谷。","当时从臣皆俊良，近侍共推徐与杜。","或操陈子之刀镊，或负伊公之鼎俎。","艰难出入矢石下，鞠躬尽力无摧阻。","夙兴夜寐事一人，小心不贰帝临女。","只今四海同车轨，葑菲罔遗遵往古。","琼琚赤芾簉鹓行，鞍马禄食光门户。","天鸡一声金阙启，龙颜有喜常先睹。","顾我愚疏忧患集，病骨崚嶒蒸溽暑。","兴来怀旧倚长歌，星星两鬓丝千缕。"]},{"t":"春夜一首","f":"古风","c":["春夜迢迢，微风不兴。","六合无氛，银河欲冰。","月流素波，星回玉绳。","孤坐不寐，忧思相仍。","壮年巳谢，昔非莫惩。","如彼老马，心念超腾。","道路崎岖，劢不可能。","俯拨红炉，仰剔青灯。","欲与晤语，谁其我应。"]},{"t":"青阳一首","f":"古风","c":["青阳俶载，白日孔昭。","草生于野，华发于条。","随气成形，或蕊或翘。","眷眷兴怀，中心飘摇。","麦有雉雊，藻有鱼跳。","嘤鸣在树，磬管箫韶。","驾言出游，以犹以陶。","皤不可髫，箨不可夭。","自非松柏，不能后彫。","来者弗畏，往者其消。"]},{"t":"新春","f":"五言古诗","c":["昨夜东风来，吹我庭前柳。","柳芽黄未全，草根青巳有。","鹁鸠屋上鸣，劝我尝春酒。","我发日巳白，我颜日巳丑。","开樽聊怡情，谁能计身后。"]},{"t":"鸡鸣一首赠宗文侄","f":"古风","c":["鸡鸣朝晖，草露未晞，巢鸟于飞。","鸡鸣夕阴，草露淋淫，鸟归于林。","鸡鸣匪司时，鸟举匪有期。","氓之蚩蚩，盖亦何思？","朝露白如玉，我不敢躅，恐湿我足。","夕露光如珠，我不敢踰，恐湿我裾。","谁谓河弗广，可航可荡。","风波无期，不如勿往。","谁谓林弗幽，可遨可游。","豺虎无虞，不如勿由。","中田有禾，园有树麻。","发石有泉，可以为家。","中田有麦，园有树核。","采山有蔬，可以为宅。"]},{"t":"送金华何生还乡觐省 其四","f":"七言绝句","c":["楼外桃花红锦披，当花把酒映花枝。","慈亲饮酒看儿笑，记摘桃花洗面时。"]},{"t":"潜溪图歌为宋景濂赋","f":"古风","c":["金华山水天下希，潜溪龙门尤绝奇。","群峰峻极河汉上，一峰独立芙蓉陂。","先生结庐在其下，文追班扬兼贾马。","遂令此山增壮观，野有朴樕皆梧槚。","上清道士方方壶，乘兴为作潜溪图。","丹崖翠麓神仙居，东望日出树如苏。","溪流穿林还度谷，十里一达五里伏。","龙湫吐景生白虹，藤萝振雨松呼风。","却忆往时清夜月，帝女乘云下天阙。","钟镛铿鍧萧鼓发，霓裳羽衣飘灭没。","初平骑羊前启行，长髯鬖髿飞玉霜。","秦娥吹笙玄鹤舞，牵牛河鼓凝寒芒。","相思迢迢频入梦，梦驾两鸾从一凤。","觉来毛发犹爽淅，目送征鸿度空碧。","山有蔬，水有鱼，幽涧有泉清可?。","何时上疏乞骸骨，寄声先遣双飞凫。"]},{"t":"有泉在山一首","f":"古风","c":["有泉在山，爰注为壑。","膏火自煎，一室之烛。","蔚彼茂林，有檀有松，有梓有桐。","可以为车，可以为宫。","有泉在山，爰注为渊。","膏火之烛，维以自煎。","蔚彼茂林，有柞有棫，有樗有栎。","可以为薪，可以为杙。"]},{"t":"春日杂兴 其三","f":"七言绝句","c":["春雾冥冥木叶稠，苍鹰拂羽化为鸠。","莫将松桂夸桃李，柱下先生早白头。"]},{"t":"春日杂兴 其四","f":"七言绝句","c":["日自西驰水自东，落花飞絮总随风。","旧巢燕子今何处，烟雨庭台似梦中。"]},{"t":"春日杂兴 其六","f":"七言绝句","c":["细雨冥冥昼掩扉，更无芳草有垣衣。","人生一世邯郸梦，老病无眠梦亦稀。"]},{"t":"春日杂兴 其七","f":"七言绝句","c":["雨隐沧江雾隐山，乡关迢递寄书难。","病来只盼春风到，不拟春风晓更寒。"]},{"t":"春日杂兴 其八","f":"七言绝句","c":["日出江空晓气柔，白蘋风起渚烟收。","夜来一饷三更雨，送尽飞花入海流。"]},{"t":"感春 其三","f":"五言律诗","c":["日暮东风起，沧江水微波。","水深不可涉，路远将柰何。","蘼芜叶巳齐，故乡隔山河。","盛年难再得，芳意其蹉跎。"]},{"t":"感春 其四","f":"五言律诗","c":["朝采山上蕨，暮采涧底薇。","虽无粱肉味，聊可以御饥。","羔羊荐美酒，饱食同豢牺。","玄庐苟未闭，彼此谁是非。"]},{"t":"感春 其六","f":"五言古诗","c":["人生多忧患，死去百患消。","但恨不便得，无由脱鞿镳。","浮荣众所贵，何异掠草焱。","一生与一死，一夕复一朝。","周器忌盈满，老子戒矜骄。","园林无恒芳，江海有回潮。","委心从大化，庶几永逍遥。"]},{"t":"枯树图","f":"七言古诗","c":["道傍古树身半枯，白蚁穴根虫穴肤。","风摧雨撼霜雪冻，断石臲卼无人扶。","忆昔勾芒肇初政，百卉腾达随呵嘘。","新柯荏苒旧柯壮，雾露膏沐光如濡。","黄鹂翡翠语娇滑，桑扈戴胜鸣相呼。","白鹤来巢鹿止荫，匠石愕睨争叹誉。","宁知忧患生旦夕，野火倏忽起不虞。","燎原烈焰难向迩，孰问柞栎杉与槠。","枝燔叶焮根半赤，朽腐瞒液非时须。","山林摇落岁方晏，聊以薜荔为衣袽。","呜呼广厦栋梁具，委弃草莽同薪刍。","皇天未必替生意，更盼玉烛回旸乌。"]},{"t":"即事","f":"七言律诗","c":["春半馀寒似暮秋，掩门高坐日悠悠。","树头独立知风鹊，屋角双鸣唤雨鸠。","芳意自随流水逝，华年不为老人留。","浮花冶叶休相笑，自古英贤总一沤。"]},{"t":"遣兴","f":"七言律诗","c":["江上潮来风捲沙，城头毕逋乌尾讹。","燕泥半湿昨夜雨，蛛网忽粘何处花。","孤坐日月自闲暇，出门岐路空交加。","漫将白发对芳草，目送去鸿天一涯。"]},{"t":"丙戌岁将赴京师途中送徐明德归镇江","f":"五言律诗","c":["疲马怀空枥，征衣怯路尘。","那堪远游子，复送欲归人。","月满西津夜，花明北固春。","论文应有日，话别莫悲辛。"]},{"t":"过南望时守闸不得行","f":"五言律诗","c":["客路三千里，舟行二月馀。","壮颜随日臧，衰鬓受风疏。","蔓草须句国，浮云少吴墟。","愁心如汶水，荡漾绕青徐。"]},{"t":"发景州","f":"五言律诗","c":["澹澹夕风作，萧萧芦叶鸣。","林间众鸟息，河上一舟行。","海近云常湿，天虚月更清。","神京看渐近，且缓望乡情。"]},{"t":"过闽关九首 其三","f":"七言绝句","c":["建溪激箭向南流，石齿如锋斗客舟。","篙子踏歌浑不畏，行人遥望替生愁。"]},{"t":"过闽关九首 其六","f":"七言绝句","c":["漠漠轻云结晚阴，依依斜日挂遥岑。","炊烟忽起桑榆上，散作鲛绡抹半林。"]},{"t":"钱塘怀古得吴字","f":"五言古诗","c":["泽国繁华地，前朝旧此都。","青山弥百粤，白水入三吴。","艮岳销王气，坤灵肇帝图。","两宫千里恨，九子一身孤。","设险冯天堑，偷安负海隅。","云霞行殿起，荆棘寝园芜。","币帛敦和议，弓刀抑武夫。","但闻当守奏，不见立庭呼。","鬼蜮昭华衮，忠良赐属镂。","何劳问社稷，且自作欢娱。","粳稻来吴会，鱼鼋出具区。","至尊巍北阙，多士乐西湖。","鹢首驰文舫，龙鳞舞绣襦。","暖波摇襞积，凉月浸氍毹。","紫桂秋风老，红莲晓露濡。","巨螯擎拥剑，香饭漉雕胡。","蜗角乾坤大，鳌头气势殊。","秦庭迷指鹿，周室叹瞻乌。","玉马违京辇，铜驼掷路衢。","含容天地广，养育羽毛俱。","橘柚驰包贡，涂泥赋上腴。","断犀埋越棘，照乘走隋珠。","吊古江山在，怀今岁月逾。","鲸鲵空渤澥，歌咏巳唐虞。","鸱革愁何极，羊裘钓不迂。","征鸿暮南去，回首忆莼鲈。"]},{"t":"读史有感","f":"七言绝句","c":["千古怀沙恨逐臣，章台遗事最酸辛。","可怜日暮高唐梦，绕尽行云不到秦。"]},{"t":"感兴七首 其二","f":"七言律诗","c":["清时不乐道干戈，鼯鼠其如虎豹何。","淮海风云连鼓角，湖山花木怨笙歌。","紫微画省青烟入，细柳空营白骨多。","惆怅无人奏丹扆，侧身长望涕滂沱。"]},{"t":"感兴七首 其四","f":"七言律诗","c":["将军意气薄丹霄，欲把孤航截海潮。","苏武节来无忌死，岑彭营恶子阳骄。","鸱鸮诗奏忠谁白，松柏歌成恨岂销。","怅望天涯一洒泪，鲸鲵罔象杂三苗。"]},{"t":"感兴七首 其五","f":"七言律诗","c":["落日悲风云满川，家家闭户少炊烟。","也知渤海无龚遂，漫忆邯郸有鲁连。","三尺青萍思出匣，数茎白发望归田。","请看如镜南楼月，此夜清光最可怜。"]},{"t":"感兴七首 其六","f":"七言律诗","c":["天弧不解射封狼，战骨纵横满路傍。","古戍有狐鸣夜月，高冈无凤集朝阳。","雕戈画戟空文物，废井颓垣自雪霜。","漫说汉庭思李牧，未闻郎署遣冯唐。"]},{"t":"感兴七首 其七","f":"七言律诗","c":["天上九关森虎豹，人间七泽起龙蛇。","尘埃不辨风云色，雨露全归枳棘花。","秦国有人迷鹿马，周郊无土载虫沙。","淮濆何日歌常武，肠断严城戍鼓挝。"]},{"t":"越山亭晚望","f":"七言律诗","c":["越绝孤城枕海湄，越王亭下景迟迟。","云埋夏后藏书穴，草没秦皇颂德碑。","凿齿未驯虞礼乐，戈船犹驻汉旌旗。","春风淡荡吹杨柳，笑看吴钩有所思。"]},{"t":"谒夏王庙有感","f":"七言律诗","c":["一片宫垣粉雘新，前王陵庙在松筠。","玉书金简归天地，贝叶昙花诧鬼神。","沧海波涛纡职贡，山川草木望时巡。","苗顽未狎虞阶舞，空使忠良泪满巾。"]},{"t":"冬暖","f":"七言律诗","c":["今年南国天气暖，十月赤城桃有花。","江枫未肯换故色，汀草强欲抽新芽。","野畦落日舞残蝶，小池过雨喧鸣蛙。","城上几时罢击柝，愁见海云蒸晚霞。"]},{"t":"不寐","f":"五言律诗","c":["不寐月当户，起行风满天。","山河青霭里，刁斗白云边。","避世惭商绮，匡时愧鲁连。","徘徊怀往事，恻怆感衰年。"]},{"t":"漫成","f":"七言律诗","c":["春雨日日送愁来，雨中百花浑未开。","青山不见神禹穴，碧草巳满越王台。","鱼儿弄水浮还没，燕子寻巢去却回。","头白扬雄懒献赋，衡门从此掩蒿莱。"]},{"t":"夏日杂兴七首 其四","f":"七言律诗","c":["故里无书问远游，他乡萍梗漫淹留。","盲风怪雨蛟龙喜，荒楚寒芜燕雀愁。","天上古今星北拱，人间日夜水东流。","谁能走报西王母，乞与还丹驻黑头。"]},{"t":"夏日杂兴七首 其五","f":"七言律诗","c":["层楼迢递俯清郊，天际群山槛外交。","日暖水禽鸣哺子，风轻沙燕语寻巢。","绿荷雨洗藏龟叶，翠竹烟寒集凤梢。","可叹仲宣归未得，苦吟终日倚衡茅。"]},{"t":"夏日杂兴七首 其六","f":"七言律诗","c":["夏至阴生景渐催，百年巳半亦堪哀。","葺鳞不入龙螭梦，铩羽何劳燕雀猜。","雨砌蝉花粘碧草，风檐萤火出苍苔。","细观景物宜消遣，寥落兼无浊酒杯。"]},{"t":"夏日杂兴七首 其七","f":"七言律诗","c":["菱叶荷花渐满池，红榴绿筱正相宜。","天边日出园葵觉，地底云生柱础知。","长夏未应炎暑过，薄寒恰似晚秋时。","朝来苦怪双青鬓，辄向风前学素丝。"]},{"t":"夏日访王友文留饮赠诗","f":"七言律诗","c":["长夏园林白昼闲，高轩留客雨漫山。","倾壶竹叶沉沉绿，落树杨梅颗颗殷。","槛外新荷摇水佩，檐前弱柳舞风鬟。","醉来带月浮舟去，忘却尘埃世路艰。"]},{"t":"次韵高则诚雨中三首 其一","f":"七言律诗","c":["短棹孤篷访昔游，冷风凄雨不胜愁。","江湖满地蛟螭浪，粳稻连天鼠雀秋。","莫怪贾生偏善哭，从来杞国最多忧。","绝怜窗外如圭月，只为离人照白头。"]},{"t":"次韵高则诚雨中三首 其二","f":"七言律诗","c":["霖雨萧萧泥客途，岁华冉冉隙中徂。","不知燕赵车千乘，何似嵩邙饭一盂。","露冷芙蓉捐玉佩，天寒薏苡结明珠。","东邻艇子如堪借，去钓松江巨口鱼。"]},{"t":"次韵高则诚雨中三首 其三","f":"七言律诗","c":["吴苑西风禾黍黄，越乡倦客葛衣凉。","楸梧夜冷鸟惊树，霜露秋清蜂闭房。","天上出车无召虎，人间卖卜有王郎。","干戈满目难回首，梦到空山月满堂。"]},{"t":"次韵和谦上人秋兴七首 其一","f":"七言律诗","c":["一自中原万马奔，江淮今有几州存。","龙韬豹略痴儿戏，秾李夭桃猛士门。","废垒秋风销战骨，荒郊夜雨泣冤魂。","江湖愁绝无家客，伫立看天泪眼昏。"]},{"t":"次韵和谦上人秋兴七首 其二","f":"七言律诗","c":["东海波涛激迅飙，西风氛雾虎狼骄。","高牙画戟尊方伯，绣段黄封出内朝。","无客金戈桩凿齿，有人玉帐舞弓腰。","武陵日暮桃花尽，何处林泉可采樵。"]},{"t":"次韵和谦上人秋兴七首 其四","f":"七言律诗","c":["浙江流水绕东吴，佳丽犹传故国都。","红锦漫山春雨后，黄云压树晓霜馀。","娇莺逐暖归牙帐，征雁冲寒送羽书。","惆怅南园钓舟子，蒺藜满地不胜锄。"]},{"t":"次韵和谦上人秋兴七首 其五","f":"七言律诗","c":["绣幕香帏隐日华，金鞍玉辔巧矜誇。","深山雾雨貙生虎，大海波涛虺作蛇。","朴樕有枝寒集鹊，梧桐无叶夜啼鸦。","凉风袅袅吹游子，何处松楸是汝家。"]},{"t":"次韵和谦上人秋兴七首 其六","f":"七言律诗","c":["故乡知己不曾逢，满目云山恨万重。","斥堠霜清寒夜柝，谯楼风急晓城钟。","此时绕树怜乌鹊，异县携家想駏蛩。","独向晴檐问梅蕊，数枝和雪为谁容。"]},{"t":"次韵和谦上人秋兴七首 其七","f":"七言律诗","c":["江上悲风起白波，山中芳草柰愁何。","紫菱青荇鲛人舞，翠藟苍藤木客歌。","旷野烟尘迷虎兕，长亭泥泞没骊騧。","浊河日夜东流去，肠断霓旌影馺娑。"]},{"t":"次韵和天童良上人见寄","f":"七言律诗","c":["不辞尘匣掩青萍，愿见天边陨盗星。","白日有时容黑子，紫微终古照玄冥。","轻风瀹雪归兰汜，细雨涵春入草亭。","但得此身强健在，江山相见眼长青。"]},{"t":"送李子庚之金陵","f":"七言律诗","c":["舍下微波涌碧鳞，湖边草色可怜人。","也知使者徵书急，莫厌轻舟出郭频。","春酒盈釭清似水，时鱼带子白于银。","山桃野杏能红紫，醉眼相看意自真。"]},{"t":"次韵追和音上人","f":"七言律诗","c":["绝顶浮云锁石关，曲途危磴阻跻攀。","他年甲楯孤臣泣，此日斋钟老衲闲。","夜永星河低半树，天清猿鹤响空山。","干戈未定归无处，拟结茅庐积翠间。"]},{"t":"二月二日登楼作","f":"七言律诗","c":["薄寒疏雨集春愁，愁极难禁独上楼。","何处山中堪采药，几时湖上好乘舟。","衔泥客燕聊相傍，泛水浮萍可自由。","见说兰亭依旧在，于今王谢少风流。"]},{"t":"发绍兴至萧山","f":"七言律诗","c":["落日牛羊下绿坡，微风短楫拂晴莎。","穷愁白发真相得，悲感青春最苦多。","水暖菰蒲沙鸨集，月明洲渚榜人歌。","此时忽漫思身世，柰尔桃花满眼何。"]},{"t":"宿蜡烛庵俊上人房","f":"七言律诗","c":["城外春江动客愁，江边细草绿悠悠。","还将短发临岐路，畏向东风忆旧游。","斜日远天归雁急，薄寒孤馆落花稠。","青灯不放还乡梦，一夜肠回一万周。"]},{"t":"二月七日夜泊许村遇雨","f":"七言律诗","c":["漫喜晴天出北门，还愁急雨送黄昏。","山风度水喧林麓，野树翻云动石根。","宿麦巳随江草烂，新泉休共井泥浑。","鱼龙浩漫沧溟阔，泽畔谁招楚客魂。"]},{"t":"感怀二首 其一","f":"七言律诗","c":["新晴杨柳散春丝，长路行人有所思。","愁上容颜青镜识，寒生亭馆落花知。","高云送雨来无定，独鸟惊风去自迟。","闷对亭前紫荆树，同根那得却相离。"]},{"t":"寄台郎张质夫","f":"七言律诗","c":["春愁忽得故人书，喜极成悲泪满裾。","冀野驽骀虚伯乐，鲁门钟鼓骇爰居。","全家荡析饥寒切，病骨支离志虑疏。","敢以浮名误知己，缄辞写意愧何如。"]},{"t":"水西寺东楼晓起闻莺","f":"七言律诗","c":["日上高城柳影齐，风轩临水看莺啼。","初来木杪鸣相应，稍入花间听却迷。","芳草自深句践国，行人犹隔禦儿溪。","思家每恨无轻翼，可对莺华不憯悽。"]},{"t":"茶园别朱伯言郭公葵","f":"七言律诗","c":["细水吹烟送客舟，离情恰似水东流。","此时对酒难为乐，何处寻春可纵游。","去雨来云天渺渺，轻蜂乱蝶日悠悠。","绝怜短发无聊赖，一夜如丝白满头。"]},{"t":"晚泊海宁州舟中作","f":"七言律诗","c":["春雾今宵气稍清，空江一舸客心惊。","东流浊浪冲山动，西望长庚似月明。","不有龚黄为郡县，徒令耒耜化戈兵。","溥天何处非王土，无地安身愧此生。"]},{"t":"春兴七首 其二","f":"七言律诗","c":["勿听屋角闹晨鸠，起看园林绿渐稠。","小雨霏霏涵日过，新泉细细入河流。","残花断柳虚归计，远水他山聚客愁。","鸿雁南飞限苍岭，伤心何处问松楸。"]},{"t":"春兴七首 其六","f":"七言律诗","c":["深春积雨感年芳，暮馆轻寒透客裳。","翠柳条柔先改色，紫兰花冷不飘香。","山中虎豹人烟少，海上楼台蜃气长。","燕子新来畏沾湿，一双相对立空梁。"]},{"t":"春兴七首 其七","f":"七言律诗","c":["忆昔江南未起兵，吴山越水共知名。","蘋萍日暖游鱼出，桃李风和乳燕鸣。","紫陌尘埃嘶步景，画船歌管列倾城。","于今征戍诛求尽，翻对莺花百感生。"]},{"t":"萧山山行","f":"七言律诗","c":["积雨今朝天气佳，山亭晓色上林花。","未须汗漫思身世，且可逍遥玩物华。","偶值断桥妨去路，却随脩竹到邻家。","篱边野鸭惊人过，拨剌飞鸣落远沙。"]},{"t":"普济寺遣怀","f":"七言律诗","c":["江上西风一叶黄，莎鸡络纬满丛篁。","物华乘兴看都好，时序逢愁速不妨。","露下星河光潋滟，月明岩谷气清凉。","愿闻四海销兵甲，早种梧桐待凤凰。"]},{"t":"题水墨蓼花草虫","f":"七言律诗","c":["为爱江头红蓼花，秋来独作草虫家。","寻香粉蝶应随梦，采蜜黄蜂不趁衙。","络纬语残凉露滴，蜻蜓立困晚风斜。","画图水墨惊初见，却似扁舟过赤沙。"]},{"t":"题山水图为宝林衍上人作","f":"七言律诗","c":["雨过秋山日欲暾，白云如雪拥山根。","高松浥露和烟冷，迸水穿沙出谷浑。","拟向萝阴缘石径，却寻花片入桃源。","画图应有通神处，他日相从子细论。"]},{"t":"再用韵荅严衍二上人","f":"七言律诗","c":["负郭无田生事疏，微官巳谢不须除。","散愁漫入高僧舍，乘兴还过野老居。","草冷虫声悲杼轴，霜馀蕉叶碎缄书。","黄花素发相将暮，独立凄凉忆往初。"]},{"t":"次韵和新罗严上人秋日见寄二首 其二","f":"七言律诗","c":["爱汝精蓝抱翠微，青松绿竹共依依。","龟台落日明霞绮，鳗井寒潮长石衣。","银杏子成边雁到，木犀花发野莺飞。","钟残永夜禅心定，一任秋虫促杼机。"]},{"t":"重用韵荅严上人 其一","f":"七言律诗","c":["坐见风霜百草疏，却怜光景渐消除。","萍蓬飘荡三年客，松菊荒凉五亩居。","陋巷苍苔封蚁垤，空庭黄叶带虫书。","江枫恰似知人意，强学芳菲二月初。"]},{"t":"重用韵荅严上人 其二","f":"七言律诗","c":["江水东流西日微，闲身不系独何依。","尘埃爽飒枯蓬鬓，霜露凄凉破衲衣。","百粤雨馀山翠合，三韩云净海青飞。","沧溟自古通天汉，梦绕黄姑织女机。"]},{"t":"仍用韵酬衍上人 其一","f":"七言律诗","c":["多愁秖觉世情疏，愁极凭谁与破除。","江海烟尘羁客泪，云山桑梓别人居。","高风断雁惟将恨，衰草残萤不照书。","世乱弓刀方有用，休誇新句逼黄初。"]},{"t":"仍用韵酬衍上人 其二","f":"七言律诗","c":["岁莫天寒生意微，空林鸟雀自相依。","有情霜叶欺花貌，无用风荷象客衣。","西塞鼓鞞山岳震，东郊羽檄海波飞。","传闻有诏颁南服，早晚阳和斡化机。"]},{"t":"又用前韵 其一","f":"七言律诗","c":["树头寒月影扶疏，天上清霜下玉除。","紫塞风高鸿失路，碧梧枝冷鹊移居。","虎头旷日糜仓粟，牛腹中霄诧帛书。","见说抱关堪避世，稗官犹可学虞初。"]},{"t":"又用前韵 其二","f":"七言律诗","c":["西风吹面雨霏微，片片浮云水上依。","鸿雁群翔营口实，凫鹥对立惜毛衣。","关河惨烈时将晚，原野萧条叶自飞。","惭愧江湖一萍梗，厌听咿轧响邻机。"]},{"t":"题小景","f":"七言绝句","c":["江头日日起西风，江树惊寒叶变红。","天澹云低何处雁，一行飞下荻花中。"]},{"t":"题梅花小禽图","f":"七言绝句","c":["三鸟翩翩海上来，一双飞去入瑶台。","可怜铩羽空山里，独立寒枝怨野梅。"]},{"t":"感兴三首 其一","f":"七言律诗","c":["病骨愁寒忆见春，及观春色却愁人。","转添细草当门径，不惜秾华委路尘。","去国杜鹃红泪尽，伤时庾信白头新。","风波满地鸬鹚鸟，相趁衔鱼饱一身。"]},{"t":"感兴三首 其二","f":"七言律诗","c":["二月江南雪片飞，吴山寒色动征衣。","莫寻花径防泥滑，且掩衡门待日晞。","弱柳先舒应自损，蛰虫巳出更安归。","乾坤处处旌旗满，肉食何人问采薇。"]},{"t":"有感","f":"七言绝句","c":["浪动江淮战血红，羽书应不达宸聪。","紫薇门下逢宣使，新向湖州召画工。"]},{"t":"感叹","f":"五言律诗","c":["闻说苏州破，仓皇问故人。","死生俱可悼，吾道一何屯。","北去应无路，南藩自此贫。","凄凉转蓬客，泪尽浙江滨。"]},{"t":"题画鱼二首 其一","f":"七言绝句","c":["为爱濠梁乐有馀，故拈兔颖写成图。","秋风忽忆银丝鲙，肠断松江隔具区。"]},{"t":"柯桥灵秘寺即景赠基上人","f":"七言律诗","c":["尽日阴阴风坠花，楼前沟水发芹芽。","青春院宇僧房好，白昼豺狼客路赊。","对坐虾须回舞燕，出门鸱尾立饥鸦。","相期握手何时再，五月芙蓉隘若耶。"]},{"t":"次韵和石末元帅见赠二首 其一","f":"七言律诗","c":["雨过前溪晓色新，山城草木静埃尘。","殊方负固犹蜗角，此地偷安赖虎臣。","高阁绿萝相对晚，画阑红药不胜春。","谁怜衰病兼疏拙，标泊东西一旅人。"]},{"t":"次韵和石末元帅见赠二首 其二","f":"七言律诗","c":["元戎玉帐拥旌麾，武略文韬并出奇。","构厦可堪无大匠，安邦曾见活危棋。","此时山斗归民望，他日龙螭简帝思。","我辈迂狂垂世务，趍风执御更何疑。"]},{"t":"雨中寄季山甫二首 其一","f":"七言律诗","c":["山雨随风去复来，南明晚色动楼台。","犹怜仗节中郎在，不见乘槎使者回。","感兴诗成聊自遣，忘忧花好为谁开。","偏嫌近水多蝼蝈，永夜喧呼聒梦回。"]},{"t":"雨中寄季山甫二首 其二","f":"七言律诗","c":["长夜雨多泥没车，白日闭门人迹疏。","阶下水衣看上壁，庭前檐溜欲成渠。","闲花自发无劳种，蔓草从生不遣锄。","想见幽栖张仲蔚，蓬蒿如树塞园庐。"]},{"t":"病足戏呈石末公","f":"七言律诗","c":["旻天容我作支离，病疟才除足就羸。","跬步不妨犹似鳖，踔行那得更怜夔。","抱珍献楚何堪再，斫树收庞亦未迟。","塞叟于今知匪祸，周鸡从此免为犠。"]},{"t":"遣闷柬石末公","f":"七言律诗","c":["绿杨落尽白杨枯，坐石徒令岁月徂。","尚想藩臣知患盗，岂期驿使似投巫。","当时粳稻通辽海，今日风涛隔具区。","豺獭可堪专节钺，衣冠何以拔泥涂？"]},{"t":"惆怅二首 其一","f":"七言绝句","c":["紫薇花树小楼东，日炙霞蒸似锦红。","过了春风到秋露，可堪零落碧苔中。"]},{"t":"惆怅二首 其二","f":"七言绝句","c":["与君为别几清秋，鸿雁来时辄上楼。","今日倚楼无雁过，断肠风水隔瀛洲。"]},{"t":"次韵和石末公闻海上使命之作因念西州怆然有感二首 其一","f":"七言律诗","c":["巫闾析木天空阔，桐柏终南水乱流。","邑里萧条无吠狗，田畴芜秽少耕牛。","萋萋蔓草随人远，淡淡残阳向客留。","迟莫飘零偏感旧，几回垂泪睇神州。"]},{"t":"再用前韵 其二","f":"七言律诗","c":["大阃寻常弃郑师，后人休望及瓜期。","豺狼封豕咸登用，都邑人民委若遗。","曾见羌夷皆内地，忍闻淮济是边陲。","经纶事业君当念，闻道任嚣髻已椎。"]},{"t":"再用前韵 其一","f":"七言律诗","c":["常闻星宿能环拱，未见江河解逆流。","无肉可供徐勉狗，有刍难啖景升牛。","梧桐冷落鸾先逝，芦荻苍茫雁独留。","苏息疲氓还有术，那无一斗博凉州。"]},{"t":"次韵和石末公闻海上使命之作因念西州怆然有感二首 其二","f":"七言律诗","c":["弟子舆尸漫有师，圮桥谁共老人期。","龙鱼并出应难识，樗栎无庸幸见遗。","每上楼台瞻北极，愿闻波浪帖南陲。","吴山越水元相接，莫更中流下铁椎。"]},{"t":"驿传杭台消息石末公有诗见寄次韵奉和并寓悲感二首 其一","f":"七言律诗","c":["被谗去国终思楚，厚貌深情漫剧秦。","禾识庞萌直老贼，妄期侯景作忠臣。","池鱼幕燕依栖浅，轩鹤冠猴宠渥新。","何处荃兰不萧艾，种蔬犹得养闲身。"]},{"t":"驿传杭台消息石末公有诗见寄次韵奉和并寓悲感二首 其二","f":"七言律诗","c":["丧乱如川未有涯，悲风满地是虫沙。","衰迟两臂从生柳，疾病双眸但陨花。","暗蛬寒蝉秋色老，丹枫紫菊夕阳斜。","颇闻四国思郇伯，尚想诗人赋木瓜。"]},{"t":"再次韵二首 其一","f":"七言律诗","c":["南州昔日称三楚，西国今闻又一秦。","有爵与縻亡命贼，无才深愧具官臣。","青冥鸾凤风尘隔，画省貔貅服色新。","怅望令人忆李郭，谁能匡济想捐身。"]},{"t":"再次韵二首 其二","f":"七言律诗","c":["深秋蔓草接天涯，极目飞鸿没远沙。","绿水青山长送目，汀兰岸蓼各生花。","风来西塞云阴合，涛落东溟蜃气斜。","叹息笙歌旧亭馆，坏垣丛棘老王瓜。"]},{"t":"次韵和石末公感兴见寄","f":"七言律诗","c":["使君学术似文翁，奕世流芳缉武功。","赤芾青衿来燕喜，黄童白叟望车攻。","笔端波浪翻三峡，旗尾龙蛇动八风。","惭愧谫才多谬误，忧时独有此心同。"]},{"t":"次韵和石末公无题之作","f":"七言律诗","c":["秋风袅袅作商音，落叶枯荄日夜深。","巳为抵乌投白璧，徒劳点铁冀黄金。","轩辕未必迷襄野，夸父终当死邓林。","笑撚东篱菊花蕊，天寒岁晚尔知心。"]},{"t":"立冬日作","f":"七言律诗","c":["忽见桃花出小红，因惊十月起温风。","岁功不得归颛顼，冬令何堪付祝融。","未有星辰能好雨，转添云气漫成虹。","虾蟆蛱蝶偏如意，旦夕蜚鸣白露丛。"]},{"t":"丙申岁十月还乡作七首 其二","f":"七言律诗","c":["风急霜飞天地寒，草黄木落水泉乾。","千村乱后荒榛满，孤客归来抆泪看。","野宿狐狸鸣户外，巢居烟火出云端。","黍苗处处思阴雨，王粲诗成损肺肝。"]},{"t":"丙申岁十月还乡作七首 其三","f":"七言律诗","c":["故园梅蕊依时发，异县归人见却悲。","花自别来难独立，人今老去复何之。","未能荷锸除丛棘，且可随方著短篱。","等待薰风暄暖后，枝间看取实离离。"]},{"t":"丙申岁十月还乡作七首 其四","f":"七言律诗","c":["手种庭前安石榴，开花结子到深秋。","可怜枝叶从人折，尚有根株为客留。","枳枸悲风吹白日，苕华高影隔青丘。","坏垣蟋蟀知离恨，长夜凄凉吊独愁。"]},{"t":"丙申岁十月还乡作七首 其五","f":"七言律诗","c":["舍北草池寒巳枯，草中时复见菰蒲。","滥泉觱沸无留鲋，弱藻蒙茸不系凫。","绿叶红花空代谢，春蛙秋蚓任喧呼。","窥临最忆琴高鲤，腾驾风雷定有无。"]},{"t":"丙申岁十月还乡作七首 其六","f":"七言律诗","c":["小舟冲雨清溪上，雨密溪深宿雾昏。","游子到家无旧物，故人留客叹空尊。","荒畦蔓草缠蒿草，落日青猿叫白猿。","语罢不须还秉烛，耳闻目见总销魂。"]},{"t":"冬至日泊舟戈溪","f":"七言律诗","c":["日薄云阴雪在山，野寒溪静客舟还。","乾坤簸荡逾三载，风俗乖张似百蛮。","废井衰芜霜后白，空村乔木晓馀殷。","独怜节序逢冬至，不得安栖学闭关。"]},{"t":"次韵和石末公红树诗","f":"七言律诗","c":["红树漫山驻岁华，玄冬惊见眼生花。","井陉旗帜军容盛，汴水帆樯御气赊。","春草凄迷金谷障，夕阳照灼赤城霞。","靡蓱丹木扶桑里，惆怅谁乘博望槎。"]},{"t":"次韵和石末公元夜之作","f":"七言律诗","c":["八表流云澄夜色，九霄华月动春城。","条风细细吹旗影，香蔼微微引漏声。","河汉虹桥应断绝，沧溟鳌足漫峥嵘。","愁来更听渔阳操，独倚阑干坐到明。"]},{"t":"次韵和石末公见寄五绝 其一","f":"七言绝句","c":["楩楠割截为椽杙，岁暮搜材到柞薪。","怅望无因见夏后，再平水土叙彝伦。"]},{"t":"次韵和石末公见寄五绝 其二","f":"七言绝句","c":["庙略能回十万夫，诗书郤縠近来无。","何由入奏明光殿，指点山河一统图。"]},{"t":"次韵和石末公见寄五绝 其三","f":"七言绝句","c":["春满郊原乐意融，野花庭草竞纤秾。","惟馀陵上青青柏，不向东风改旧容。"]},{"t":"次韵和石末公见寄五绝 其四","f":"七言绝句","c":["越溪清水淬干将，鬼魅惊啼畏夜光。","不共铅刀争利钝，何妨玉匣且深藏。"]},{"t":"次韵和石末公见寄五绝 其五","f":"七言绝句","c":["汉殿千门锦绣开，不堪一夜柏梁灾。","鲁般骨朽萧何死，肠断无人为取材。"]},{"t":"社日偶成奉呈石末公","f":"七言律诗","c":["昔闻同社燕鸡豚，今见操戈竞一飧。","松柏空坛饥鼠出，枌榆落日乱鸦喧。","地连吴会嗟何蹙，民是周馀不半存。","疏懒浑愁闻世事，治聋有酒漫盈尊。"]},{"t":"次韵和林彦文刘山驿作诗","f":"七言律诗","c":["青泥九折度危峰，翠木千章集远风。","欲为流离安堡障，宁辞辛苦涉蒿蓬。","梧桐叶落无栖凤，荆棘枝寒有怨鸿。","旦夕升虚聊望楚，何时重赋定方中？"]},{"t":"题陈太初画扇 其二","f":"七言绝句","c":["泛湖浮海两如何，满地悲风起白波。","争似乘槎随博望，玉绳光里看山河。"]},{"t":"题太公钓渭图","f":"五言律诗","c":["璇室群酣夜，璜溪独钓时。","浮云看富贵，流水澹须眉。","偶应非熊兆，尊为帝者师。","轩裳如固有，千载起人思。"]},{"t":"题烟波泛舟图","f":"七言律诗","c":["旧游忆鼓湘湖棹，自净风微江练平。","小艇曲穿花底出，游鱼相伴镜中行。","别来漫想心徒切，画里重看眼亦明。","素石苍松是何处，愿从巢父濯冠缨。"]},{"t":"闻盗过界首季君山甫亦蒙访及以诗唁之","f":"七言律诗","c":["妖星何故犯奎躔，鹤上云霄鲤入渊。","寇退喜闻曾子反，书焚尚赖伏生传。","齑酸并与青毡去，瓜苦空馀绿蔓牵。","惭愧杜郊汤博士，白盐赤米数相怜。"]},{"t":"次韵和刘宗保秋怀二首 其一","f":"七言律诗","c":["眼见宾鸿去复回，可堪云雾隔瑶台。","黄花自在山中发，青鸟何由海上来。","墙角虫号瓜蔓索，树头禽嚇栗房开。","凉蟾照幕还清夜，惭愧千村野哭哀。"]},{"t":"次韵和石末公红树诗","f":"七言律诗","c":["岸柳江蒲总戚施，桕林辛苦擢金支。","虞人诧见炎官伞，候骑讹传汉将旗。","照水荧煌空衒貌，因风飘落竟从谁。","应惭若木生旸谷，长驻踆乌烛崦嵫。"]},{"t":"次韵和石末公悲红树二首 其二","f":"七言律诗","c":["霜与秋林作锦帏，一朝霜重却全稀。","坐看绝艳成尘土，应悟浮华是祸机。","惊鹊月明难自定，穷猿岁暮欲何归。","犹怜有客期欢赏，太息斯须志愿违。"]},{"t":"诏书到日喜雨呈石末公","f":"七言律诗","c":["将军铁马高秋出，使者楼船渤海来。","甘雨恰随天诏下，冻云应与地图开。","枯黄背日纷纷落，细绿迎春苒苒回。","怅望山中多病客，坐看乌鹊绕庭梅。"]},{"t":"感事呈石末公","f":"七言律诗","c":["前飞鵨鹄后鴐鹅，天阔风高柰汝何。","不羡焦头居上客，空怜舐痔得车多。","深山虎豹来城市，落日鼪鼯出薜萝。","薇蕨可羹鱼可脍，白云长自在岩阿。"]},{"t":"次韵和石末公漫兴见寄二首 其一","f":"七言律诗","c":["王侯古有兴屠狗，郎吏今无善牧羊。","青海风波腾罔象，紫霄氛祲翳摇光。","江寒逝水东流急，天远冥鸿北去长。","莫笑乌鸢恶毛羽，翻飞齐得簉鹓行。"]},{"t":"次韵和石末公漫兴见寄二首 其二","f":"七言律诗","c":["济世何人希管乐，隐居无处觅求羊。","扶桑未换旸乌彩，腐草犹争爝火光。","百载承平戎马佚，十年战伐艾菅长。","长沙迁客能流涕，一日须垂一万行。"]},{"t":"闻鸠鸣有感呈石末公","f":"七言律诗","c":["郊原过雨东作始，枝上鹁鸠鸣可怜。","此地巢居犹葺垒，他乡去子望归田。","匡时势异民思汉，忧国心随雁到燕。","逝水自流人自老，倚楹长忆至元年。"]},{"t":"和石末公冬暖","f":"七言律诗","c":["世乱干戈日夜寻，可堪灾沴又相侵。","烟霞出地皆成祲，雷电飞时肯作霖。","祝蝪漫劳遵故事，问牛谁复轸忧心。","小虫未寤年光晚，犹抱枯荄学苦吟。"]},{"t":"雨中呈石末公","f":"七言律诗","c":["去年三冬暖不雨，今年孟春寒有馀。","大云垂垂压宇宙，密雪衮衮飘庭除。","安排白水与泛舸，酝酿青泥容没车。","辛苦陌头杨柳树，含颦等待太阳舒。"]},{"t":"次李子庚韵","f":"七言律诗","c":["风落馀花春事非，愁心烟雨共霏霏。","溪云不作从龙起，山石何须学燕飞。","篱下旧存彭泽菊，林间新长首阳薇。","夜阑忽漫闻啼鸟，肠断天涯信使稀。"]},{"t":"雨中遣闷","f":"七言律诗","c":["雨渍愁云重不飞，山蒸冷雾袭人衣。","亦知屏翳空多事，只恐羲和失所归。","岁晏波涛东逝急，天寒鸿雁北来稀。","残灯永夜清无焰，坐听饥猿响翠微。"]},{"t":"咏史 其一","f":"七言绝句","c":["六雄糜沸扰天纲，天下嗷嗷望禹汤。","多事秦皇能一统，却教人忆楚怀王。"]},{"t":"题秋江独钓图","f":"七言律诗","c":["秋风江上垂纶客，知是严陵是太公？","细水浮岚天与碧，斜阳炙面脸生红。","形容想像丹青在，岁月荒凉草泽空。","日暮忽然闻欸乃，蓼花枫叶忘西东。"]},{"t":"送医士贾思诚还浙东二首 其一","f":"七言绝句","c":["西风袅袅水鳞鳞，一曲离歌泪满巾。","残柳数株鸥数点，夕阳江上送归人。"]},{"t":"送医士贾思诚还浙东二首 其二","f":"七言绝句","c":["落木长亭独客回，蹇驴聊可当驽骀。","还山须种千株杏，等待仙华道士来。"]},{"t":"绝句漫兴七首 其七","f":"七言绝句","c":["永夜西风袅袅来，露华如玉委苍苔。","碧鸡啼落山头月，肠断槐根梦不回。"]},{"t":"夜坐二首 其一","f":"七言绝句","c":["露泣寒螀唁断魂，风惊檐铎语黄昏。","羁愁悄悄成危坐，看尽空墙上月痕。"]},{"t":"无寐","f":"七言绝句","c":["夜长无寐待鸣鸡，及至鸡鸣梦却迷。","惊起朝阳斜照屋，一眉残月在天西。"]},{"t":"雪中有怀章三益叶景渊","f":"七言律诗","c":["岁莫怀人雪满天，饥乌病客对凄然。","地炉无火同谁坐，石砚生冰尽日眠。","栗里何时归白发，茅檐几处起青烟。","稻畦麦陇看春及，土膏泉滋谶有年。"]},{"t":"白发","f":"七言律诗","c":["白发应同春草茎，风吹一夜满头生。","欲收浮艳归根柢，故遣芳菲定老成。","碧瓦晓霜怜变灭，纸窗宵月妒分明。","据鞍上马非吾事，赖尔妆严意不轻。"]},{"t":"绝句九首 其五","f":"七言绝句","c":["槐叶阴阴覆短墙，微风细雨麦秋凉。","如何一岁三春景，不及闲窗午梦长。"]},{"t":"绝句九首 其七","f":"七言绝句","c":["花落江皋宿雨晴，野烟消尽见芜城。","凤箫一去无回日，不及年年绿草生。"]},{"t":"绝句九首 其八","f":"七言绝句","c":["天堑长江似海深，江头山鬼笑埋金。","东家酿酒西家醉，世上英雄各有心。"]},{"t":"绝句漫兴十一首 其三","f":"七言绝句","c":["莫道花开便是春，莫言沙涨即成津。","南风过了东风起，愁杀江头待渡人。"]},{"t":"绝句漫兴十一首 其六","f":"七言绝句","c":["五湖风雨夜垂纶，一叶扁舟一粟身。","至竟云涛归大壑，烟波还属钓鱼人。"]},{"t":"绝句漫兴十一首 其七","f":"七言绝句","c":["病客无钱试药方，出门聊复信行藏。","争知头上萧萧发，却与游丝较短长。"]},{"t":"漫成三首 其一","f":"七言绝句","c":["八骏茫茫去不回，白云歌曲使人哀。","鲮鱼风起鲸鲵涌，青鸟何由海上来。"]},{"t":"漫成三首 其三","f":"七言绝句","c":["微凉生袂一登楼，落照归鸦点点愁。","谁似孤云独无事，随风直到海西头。"]},{"t":"不雨遣闷二首 其二","f":"七言绝句","c":["池上芹泥即渐乾，梁间燕子拾虫难。","绿窗无限伤春意，看尽斜阳更倚阑。"]},{"t":"春蚕","f":"七言绝句","c":["可笑春蚕独苦辛，为谁成茧却焚身。","不如无用蜘蛛网，网尽蜚虫不畏人。"]},{"t":"愁感代哭","f":"七言律诗","c":["燕鸿北去又南来，断垄荒冈几劫灰。","慈母矶寒风落木，望夫石老雨添苔。","江流定与天河合，客泪还经地底回。","未必春光便销歇，白华犹发烧残梅。"]},{"t":"望孤山作","f":"五言律诗","c":["晓日千山赤，寒烟一岛青。","羁心霜下草，生态水中萍。","黄屋迷襄野，苍梧隔洞庭。","空将垂老泪，洒恨到沧溟。"]},{"t":"青丝马","f":"五言律诗","c":["蹀躞青丝马，艰难赤伏符。","穷阴岁欲暮，落日鬼相呼。","见雁愁心裂，看天泪眼枯。","殷勤夜深月，还照旅魂孤。"]},{"t":"十二月一日","f":"五言律诗","c":["耿耿夜不寐，源源忧思来。","岁馀三十日，肠定九千回。","江响风初发，天昏月未开。","白头真合得，非是楚猿哀。"]},{"t":"春城","f":"七言律诗","c":["春尽江城不见花，似知白发畏韶华。","战争故习俱无赖，丧乱馀生未有涯。","三岛虹蜺昏日月，二仪风雨化龙蛇。","何年百谷归沧海，寻取河源泛客槎。"]},{"t":"钟山作十二首 其九","f":"七言绝句","c":["白雁萧萧柿叶红，野花开尽六王宫。","空馀一道秦淮水，著意西流竟向东。"]},{"t":"岁晏","f":"五言绝句","c":["岁晏悲风急，空江白昼阴。","黄芦与红蓼，无处不伤心。"]},{"t":"摇落","f":"七言律诗","c":["摇落江天气惨凄，野黄云白惑东西。","可怜饥鼠当人立，无柰寒鸦向客啼。","杳杳夕阳葭浦阔，茫茫秋水稻田低。","销魂何地归衰疾，触处烟尘沸鼓鼙。"]},{"t":"秋夕","f":"七言律诗","c":["柏叶萧疏柳叶黄，露华如玉缀空廊。","丹心欲共灯花结，白发偏随漏水长。","月色故园同窈窕，虫声此夜独凄凉。","寒鸦莫更啼金井，衰病能堪几断肠。"]},{"t":"将晓","f":"五言律诗","c":["愁梦不更续，寒天将欲明。","雪风吹海树，霜月凛江城。","衰病丹心在，艰虞素发盈。","殷勤东注水，渺渺若为情。"]},{"t":"题梅屏二绝 其一","f":"五言绝句","c":["树杪过流星，轻霜落半庭。","疏花与孤客，相对一青灯。"]},{"t":"次韵和石末公秋日感怀见寄二首 其一","f":"七言律诗","c":["郊原如赭巳无秋，况复干戈未肯休。","肉食不知田野事，布衣深为庙廊忧。","典章沦落悲刍狗，馈饷倭迟想木牛。","礼乐将军今郤縠，豺狼满地待虔刘。"]},{"t":"夜坐有怀呈石末公","f":"七言律诗","c":["西风白露下清寥，岸柳江蒲取次凋。","诸将旌麾非一统，大藩衣服变三苗。","雄豪窃据皆屠狗，功业舆台总续貂。","弃马独知怀故枥，天涯涕泪北辰遥。"]},{"t":"次韵和石末公春晴诗","f":"七言律诗","c":["幽禽啧啧语朝阳，细绿骎骎入女桑。","天上深宫调玉烛，人间和气应勾芒。","赤眉青犊终何在，白马黄巾莫漫狂。","将帅如林须发踪，太平功业望萧张。"]},{"t":"望江亭","f":"七言律诗","c":["柳拂江亭旧画栏，望潮人去地应闲。","寝园寂寞秋风里，行殿荒凉野草间。","白塔尽销龙虎气，荒城空锁凤凰山。","兴亡莫问前朝事，江水东流去不还。"]},{"t":"至日遣兴","f":"七言律诗","c":["十九年前此日同，浙江西望粤城东。","山川拥隔乖同轨，气朔分齐正八风。","坐阅天时占道长，起征云物欲年丰。","嬴粮儗问商颜路，好采灵芝伴四翁。"]},{"t":"即事","f":"七言律诗","c":["千林摇落暮天寒，短景经檐岁序残。","口舌得官齐虏易，膏肓致疾上医难。","无根荒蔓风飘急，阅世松乔气厚蟠。","鸿雁随阳经远道，帛书何日到长安？"]},{"t":"杂诗四十首 其二","f":"五言古诗","c":["小鱼头如针，大鱼须如松。","小大各生育，孰私天地功。","坤灵发淫怒，溟海簸惊风。","大鱼食小鱼，陂池为之空。","陂空水亦竭，小大相噞喁。","但见灌莽间，颅骨成崆巃。","残膏饫蝼蚁，孰辨鲸与鯼。"]},{"t":"杂诗四十首 其三","f":"五言古诗","c":["儳妇厌贫夫，常怀相弃心。","慨慕东家子，年少多黄金。","轻身改西托，布被烂锦衾。","宁忆秋风起，霜露凄繁林。","叶落枝亦尽，愁闻蜻蛚吟。"]},{"t":"杂诗四十首 其四","f":"五言律诗","c":["云月虽不明，精魄固长在。","飞蛾亦何知，乘时妒光彩。","天高多飘风，烟雾中叆叇。","纷纷堕蒿棘，终竟为何罪。"]},{"t":"杂诗四十首 其五","f":"五言古诗","c":["人生如浮云，飘摇无根蒂。","昨暮青山阿，今朝沧海澨。","风波无定时，沦踬难为计。","是中苟不爽，曷问耿与翳。","申胥存楚国，仲连却秦帝。","此士虽则亡，英名千万世。"]},{"t":"杂诗四十首 其六","f":"五言律诗","c":["渴人常梦饮，饥人常梦餐。","中宵羁旅梦，两臂生羽翰。","腾身入紫青，吹面天风寒。","惊觉凛毛发，感我涕汍澜。"]},{"t":"杂诗四十首 其七","f":"五言古诗","c":["吾观神龙变，天地为晦冥。","龙成宰元化，嘉泽浃四溟。","出山不飘风，入水无震霆。","枯萎仰沾溉，沃若生葱青。","岂比蜧与蜦，裂石摧巘陉。","俾民举疾首，抏神蹙眉听。"]},{"t":"杂诗四十首 其八","f":"五言古诗","c":["鹰本是鸷鸟，爪利翮劲疾。","胡为化为鸠，钝拙无与匹。","栖迟荆棘间，粒啄营口实。","暮啼墙角雨，朝啼屋头日。","昔为众鸟畏，今为众鸟咥。","运命苦不常，孰为金石质。"]},{"t":"杂诗四十首 其九","f":"五言律诗","c":["愚公志移山，精卫思填海。","山高海茫茫，心事金石在。","松柏冒雪霜，秀色终不改。","春阳熙幽林，卓立有光彩。"]},{"t":"杂诗四十首 其十","f":"五言古诗","c":["急雨涨潢潦，沟池成五湖。","青蛙与耿黾，得意鸣相呼。","自谓乐无似，至足不求馀。","蓬莱有玄鹤，曾见东海枯。","清夜唳长风，哀音绕天衢。","使我起太息，黑髯变霜须。"]},{"t":"杂诗四十首 其十二","f":"五言古诗","c":["惟豺知祭兽，獭亦知祭鱼。","豺獭有报本，人道当何如。","华堂饫玉食，盗贼塞中涂。","那能不自愧，而以耀庸愚。","吁嗟千载下，枯骨空专车。"]},{"t":"杂诗四十首 其十三","f":"五言律诗","c":["雷藏蛰虫伏，雷动蛰虫起。","虫雷不相期，冥契非人使。","英雄应有时，何异膻致蚁。","神剑无风胡，铜花蚀泥滓。"]},{"t":"杂诗四十首 其十五","f":"五言古诗","c":["阴崖有乔树，乾鹊巢其颠。","朝食叶上露，暮食叶下蝉。","巢成长众雏，鸣飞一何嬛。","但愿本根固，风雨得安眠。","如何就摇落，而不抱悁悁。"]},{"t":"杂诗四十首 其十六","f":"五言古诗","c":["苍蝇眼昼明，蚊虫眼夜明。","明眼利口觜，昼夜无时停。","拍死纷籍籍，飞来更营营。","一旦霜风起，棱威肃天刑。","飞者不复飞，鸣者不复鸣。","虽有太阳光，不能煦其生。","乃知天胜人，智力徒斗争。"]},{"t":"杂诗四十首 其十七","f":"五言律诗","c":["豺狼食人肉，蚊虻食人血。","食肉死须臾，食血死不辍。","哀哀露筋女，肉尽惟皮骨。","谁谓蚊虻微，积锈能销铁。"]},{"t":"杂诗四十首 其十八","f":"古风","c":["蚊母羽虫孽，与人无怨尤。","胡为含毒害，吐蚊吼如牛。","纷纷散草泽，??森戈矛。","无辜受螫蠚，皮破腥血流。","覆巢或有令，未应后鸺鹠。"]},{"t":"杂诗四十首 其十九","f":"五言古诗","c":["黄鹰食鸟雀，山鸡食虫豸。","蜂食花上蜜，虾食苔间滓。","兔食茅草根，凤食梧桐子。","所嗜由性成，易之则皆死。","冥观付一笑，谁与穷兹理。"]},{"t":"杂诗四十首 其二十","f":"五言古诗","c":["鲁阳仰挥戈，羲和为纡辔。","耿恭俯拜井，涌液出荒地。","精诚所感格，高厚靡不至。","人生亦良难，如何殄其类。","蓬蒿满六合，惭愧真宰意。"]},{"t":"杂诗四十首 其二十一","f":"五言古诗","c":["在昔信陵君，谦劳实弘度。","好士天下稀，宾客远倾慕。","救赵夺兵符，扫清邯郸雾。","归来存大梁，秦甲詟东顾。","魏王木偶人，朽心自成蠹。","谗言一以入，危石不可据。","日落西河阴，歌钟怨零露。"]},{"t":"杂诗四十首 其二十二","f":"五言律诗","c":["天鸙巢蒿草，形躯纤且微。","不知怀何事，直上闻天扉。","啾啾终日鸣，天听不可希。","铩羽口吻裂，落日空悲归。"]},{"t":"杂诗四十首 其二十三","f":"古风","c":["雉死为从雌，鹖死为斗力。","蜜蜂死泄愤，鸤鸠死求食。","象犀好齿角，狨豹美毛色。","纷纷死相藉，杀身奉华饰。","自取夫岂过，外至良可恻。","?獍合族烹，枭鵙宜卵殈。","山林久秽荟，谁复继禹益。"]},{"t":"杂诗四十首 其二十五","f":"五言古诗","c":["殊俗甘朐䏰，比之刍牛腴。","殷勤奉宾客，自谓敬有馀。","鸱嚇虽异贯，赤惑谁能祛。","霾阴蔽玄象，清渭混污渠。","谁能继夏后，再分龙与鱼。"]},{"t":"杂诗四十首 其二十六","f":"五言律诗","c":["大星出西方，晱晱如明月。","儿童惊指示，草木见毫发。","夜久斗柄回，人静凉风发。","徙倚步中庭，空烟散成雪。"]},{"t":"杂诗四十首 其二十七","f":"五言古诗","c":["楚人将适蜀，扬帆信江水。","江阔多西风，帆逸行不止。","日暮入海涛，极目无涯涘。","鲸鱼吹高浪，舵折樯竿圮。","顿足空号呼，烟波千万里。"]},{"t":"杂诗四十首 其二十八","f":"五言古诗","c":["冲霄难为羽，泛海难为舟。","缚羊驾我辂，猛志空悠悠。","农时失耕耨，何以望有秋？","决藩盗菽粟，鹰隼不如鸠。","韶华不我与，去若川水流。","岁莫独彷徨，凛凛怀百忧。"]},{"t":"杂诗四十首 其二十九","f":"五言律诗","c":["爰居避风翔，岂冀粢牲祀。","臧孙强自用，取笑于君子。","拾虫养凤凰，将以为观美。","徒令翚翟畏，长逝深林里。"]},{"t":"杂诗四十首 其三十一","f":"五言古诗","c":["桓温一老兵，岂识扪虱士。","拥众临上流，竟作跋扈鬼。","符坚氐羌竖，何能作天子。","耽耽视中原，为有景略耳。","知人圣难之，求贤在虚己。","袁曹岂力敌，生死一弹指。","惆怅后来人，慷慨前车轨。"]},{"t":"杂诗四十首 其三十二","f":"五言古诗","c":["英英木槿花，振振蜉蝣羽。","乘彼三秋露，及此六月雨。","容好能几时，生成亦良苦。","十年搆阿房，一日化为土。","染须作童颜，于身竟何补。","不如顺天命，保己良多祜。"]},{"t":"杂诗四十首 其三十三","f":"五言古诗","c":["天地若大瓮，万物生其腹。","人犹腹中虫，蠢蠢随化育。","钻攻无时休，脏腑为翻覆。","帝青调元气，岂不畏戎毒。","皤然命涤荡，汗下兼涌衄。","蚩蚩自狂猘，涫沸交杀戮。","何当瞑眩定，风止水归渎。","铸铁作锄犁，春耕待秋熟。"]},{"t":"杂诗四十首 其三十四","f":"五言古诗","c":["二仪播元气，昼夜靡停机。","有生即有死，化工亦何私。","彼狂牵所欲，冥行失康逵。","无航思利涉，发此百祸机。","贼人还自贼，扰扰竟何为。"]},{"t":"杂诗四十首 其三十五","f":"五言古诗","c":["郭南有穷夫，黄发对老妻。","见人抱儿女，仰面看天啼。","郭北有宕子，鲜服明春闺。","累累倚门亲，疏茹乏盐醯。","盛年异欣戚，薄暮空噬脐。","达生贵知命，胡为苦悲悽。","咬咬水中凫，谷谷墙下鸡。","良无返哺望，乳抱何栖栖。","瞑目思此理，惆怅中自迷。"]},{"t":"杂诗四十首 其三十七","f":"五言律诗","c":["老眼眯昏夜，见萤以为灯。","灯萤何足辨，所悲老且瞢。","瞢老复何用，甘心就无能。","逍遥麋鹿愿，所得良巳弘。"]},{"t":"杂诗四十首 其三十九","f":"五言古诗","c":["海鲸乘扶摇，激水腾九旻。","退潮触泥沙，颅骨空嶙峋。","猛虎掉尾行，饮血不满唇。","跳哮逞雄攫，系首八尺缗。","赋命虽在天，成之亦由人。","嗟嗟灯上蛾，亦岂厌其身。"]},{"t":"杂诗四十首 其四十","f":"五言古诗","c":["夷齐值明时，饿死西山阳。","四老生乱世，采芝以徜徉。","李业遇公孙，欲盖反受殃。","严陵辞故人，万古清名扬。","性也实有命，君子顺其常。","漫漫云间鸟，冥冥随风翔。","海宇岂不宽，六翮有短长。","浩歌向日月，曲尽意茫茫。"]},{"t":"种蘹香","f":"五言古诗","c":["蘹香体虚柔，本自南土出。","毛芒散纤叶，旖旎怯朝日。","芳菲挺众卉，辛美更无匹。","况能已疝瘘，兼理肠胃疾。","种之近庭阶，离离看新茁。","驱童斩竹枝，扶植待秋实。","常恐风雨恶，摧折伤弱质。","蒺藜生道傍，延蔓何绵密。","岂无荷锄人，夕薙旦已出。","上天意何如，感叹靡终毕。","松柏多斧斤，山林日萧瑟。"]},{"t":"北上感怀","f":"五言古诗","c":["倦鸟思一枝，枥马志千里。","营营劳生心，出入靡定止。","伊余朽钝材，懒拙更无比。","才疏乏世用，嗜僻惟书史。","虽非济时具，颇识素餐耻。","既怀黎民忧，妄意古人企。","宁知乖圆方，举足辄伤趾。","尘埃百病侵，贫窭万感累。","艰难幸息肩，迟莫窃所喜。","明时登骥騄，驽马但垂耳。","自非冀北姿，莫羡追风驶。","便欲解衣冠，躬耕向桑梓。","终怀葵藿恋，不慕沮溺诡。","潜阳动原隰，白日暧兰芷。","埘鸡戒晨鸣，客子驾行李。","萦纡越巘崿，浩荡涉风水。","淹留具区北，信宿沧江圯。","维时连年歉，道路多流徙。","官司职抚字，黔首皆赤子。","陈红太仓米，丰年所储偫。","为民备乏困，朝廷岂私此。","推馀补不足，兹实王政始。","臣子宜奉承，天威不违咫。","柰何簿书曹，暴慢蔑至理。","苟云出纳吝，当闵觳觫死。","呜呼草莽露，惨恻沟渎委。","闻之犹鼻酸，见者宜颡泚。","踰淮入大河，凄凉更难视。","黄沙渺茫茫，白骨积荒藟。","哀哉耕食场，尽作狐兔垒。","太平戢干戈，景物未应尔。","意者斯人徒，纵欲扰天纪。","鬼神赫震怒，咎戾良有以。","去年人食人，不识弟与姊。","至今盗贼辈，啸聚如蜂蚁。","长戈耀白雪，健马突封豕。","岂惟横山泽，巳敢剽城市。","途行绝稀少，空车但墙倚。","身行须结集，一寐四五起。","牧民岂无人，司寇亦有氏。","阵车不驱驰，大田无耒耜。","邦家禄食恩，岂为臣奉己。","山东古要地，燕赵犹唇齿。","况兹南北冲，津梁通远迩。","属当全盛时，四海同一轨。","庙堂多稷契，振举无遗弛。","勿云疥癣微，不足成疮痏。","滔天起滥觞，炎冈发星炬。","虞朝有分北，汉庭烦直指。","农夫植嘉谷，所务诛稂秕。","耕耘苟失时，雨露空沾洒。","威怀岂异任，守令职非痹。","端能慎黜陟，此辈何足弭。","故乡隔山川，前途塞荆枳。","青徐气萧索，河济俱泥滓。","痛哭贾生狂，长叹漆室悝。","何当天门开，清问逮下俚。"]},{"t":"过东昌有感","f":"五言古诗","c":["夜发高唐湾，旦及东昌郭。","乔树拂疏星，霜飞月将落。","仰观天宇清，平见原野廓。","白杨号悲风，蔓草杳漠漠。","但见荆棘丛，白骨翳寒箨。","圣道县日月，斯人非虺蝁。","教养既迷方，欲炽性乃凿。","展季骨巳朽，清风散藜藿。","弦歌灭遗音，茧丝尽笼络。","鸱啸魍魉凭，螽鸣草虫跃。","遂令一变姿，化为蹠与蹻。","况闻太行东，水旱荐为虐。","饥氓与暴客，表里相倚著。","赈恤付群吏，所务惟刻削。","征讨乏良谋，乃反恣剽掠。","坐令参苓剂，翻成毒肠药。","今年秋租登，行止稍有托。","馀波尚披猖，未敢开一噱。","但恐习俗成，何由返初昨。","藩宣有重寄，胡不慎远略。","往者谅难追，来者犹可作。","歌诗附里谣，大猷希圣莫。"]},{"t":"晨诣祥符寺","f":"五言律诗","c":["上马鸡始鸣，入寺钟未歇。","草际起微风，林端淡斜月。","僧房湛幽寂，假寐待明发。","松径断无人，经声在清樾。"]},{"t":"发安仁驿","f":"五言律诗","c":["鸡鸣发山驿，天黑路弥险。","烟树出狷声，风枝落萤点。","江秋气转炎，嶂湿云难敛。","伫立山雨来，客愁纷冉冉。"]},{"t":"初食槟榔","f":"五言古诗","c":["槟榔红白文，包以青扶留。","驿吏劝我食，可巳瘴疠忧。","初惊刺生颊，渐若戟在喉。","纷纷花满眼，岑岑晕蒙头。","将疑误腊毒，复想致无由。","稍稍热上面，轻汗如珠流。","清凉彻肺腑，粗秽无纤留。","信知殷王语，瞑眩疾乃瘳。","三复增永叹，书之遗朋俦。"]},{"t":"早发建宁至兴田驿","f":"五言古诗","c":["鸡鸣戒晨装，上马见初日。","露泫叶尚俯，雾重山未出。","客途得霁景，缓步非纵佚。","矧兹岁有秋，高下俱颖栗。","牛羊散原野，鹅鸭满阡陌。","怀抱既夷旷，神情自清谧。","寒花蔓篱落，候虫响曚密。","霞标青枫林，雪绽乌桕实。","幽览虽云遽，佳趣领巳悉。","我行固无期，况乃尘事毕。"]},{"t":"题朱孟章虞学士送别图后","f":"五言律诗","c":["秋郊一杯酒，握手念将离。","落日照野水，凉风生树枝。","今朝重相忆，青山如旧时。","鬓毛非松柏，争得不成丝。"]},{"t":"在永嘉作","f":"五言古诗","c":["高屋集飞雨，萧条生早寒。","我来复几时？","明月缺巳团。","浮云蔽青天，山川杳漫漫。","狐狸啸悲风，鲸鲵喷重澜。","孤雁号南飞，音声悽以酸。","顾瞻望桑梓，慷慨起长叹。","愿欲凌风翔，惜哉无羽翰。","中夜百感生，展转不遑安。","枯荷响西池，槁叶鸣林端。","寥寥天宇空，冉冉时节阑。","举俗爱文身，谁识章甫冠？","河流未到海，平陆皆惊湍。","旗帜满山泽，呜呼行路难。"]},{"t":"癸巳正月在杭州作四首 其三","f":"五言律诗","c":["徘徊西湖上，怆悢有所思。","所思不可见，涕泪下沾衣。","死生一瞬息，逝者安可追。","狼曋信君子，李陵非男儿。"]},{"t":"癸巳正月在杭州作四首 其四","f":"五言律诗","c":["锻铁当用椎，析薪当用斧。","拔蓼而植荼，去辛还得苦。","峨峨九阳门，卫以豹与虎。","微微蝼蚁忱，郁郁不得吐。"]},{"t":"登卧龙山写怀二十八韵","f":"五言古诗","c":["暮春寺雨馀，原野皆秀色。","流云暧芳甸，惠风畅轻翼。","公崇冈低垂，崇冈缅登陟。","山川纠纷错，疆畎互纡直。","凄凉神禹穴，偪反句践国。","玉简閟玄缄，铜牛启雄德。","霸气浩江河，王风散荆棘。","感今情轸郁，怀古心怆恻。","东溟尚波涛，中原未耕织。","无能事萧曹，妄意追契稷。","蹇产魂屡迁，逶迟足犹侧。","良辰复几何，白日忽中昃。","周流睨圆方，俯仰观动植。","有水必趋东，无星不拱北。","宗社固神灵，至尊实恭默。","殷王伐鬼方，尚期三年克。","苗顽负险阻，终竟膺窜殛。","天戈向无前，况乃诛鬼蜮。","窃闻海滨民，决眦疾狂慝。","荷殳思一奋，所惧官未识。","朝廷鉴往辙，中道诛贪愎。","主将敦书诗，志士愿尽力。","诸公总英俊，矫矫百夫特。","愚生谅疏拙，千虑冀一得。","农人奉壶浆，迟尔殄蟊贼。","采薇戒怀归，伐檀惭素食。","白云在青天，可望不可即。","浩歌梁甫吟，忧来凭胸臆。"]},{"t":"赠柯遂卿一首","f":"五言古诗","c":["雷霆蛰神威，妖蜃跃海滨。","将军战败死，玉帐空无人。","腥涎之所被，蛭螾皆蛇鳞。","天弧不张弦，民情曷由申。","县讲亦令典，奉行在明仁。","谁令奸宄徒，并缘逞顽嚚。","俄然齿发躯，化作豺狼身。","剽金既无畏，况复枉平民。","壮哉柯夫子，义气冲九旻。","曳裾公府门，抗论回星辰。","坐令霜雪间，朽骨生阳春。","晲视夸毗儿，精魂散飞尘。","我忽耳闻之，肝胆张轮囷。","安得似卿辈，落落千百人。","出应休明时，翊赞皋陶臣。","旌别鸾与枭，再使权衡均。","上天意茫茫，感叹空悲辛！"]},{"t":"赠周宗道六十四韵","f":"五言古诗","c":["天弓拨其弦，平地跃虎狼。","腥风扇九泽，浊雾干太阳。","琐琐蚊与虻，亦沸如蜩螗。","帝阍隔蓬莱，弱水不可航。","蝼蚁有微忱，抑塞无由扬。","遥遥草茅臣，怒切忠愤肠。","披衣款军门，披腹陈否臧。","曰走居海隅，诗书传世芳。","感荷帝王恩，禄食厕朝行。","走身非己躯，安得缄其肮。","走有目击事，敢布之庙堂。","永嘉浙名郡，有州曰平阳。","面海负山林，实维瓯闽彊。","闽寇不到瓯，倚兹为保障。","官司职防虞，当念怀善良。","用民作手足，爱抚勿害伤。","所以获众心，即此是仞墙。","柰何纵毒淫，反肆其贪攘。","破廪取菽粟，夷垣劫牛羊。","朝出系空橐，暮归荷丰囊。","丁男跳上山，妻女不得将。","稍或违所求，便以贼见戕。","负屈无处诉，哀号动穹苍。","斩木为戈矛，染红作巾裳。","鸣锣撼岩谷，聚众守村乡。","官司大惊怕，弃鼓撇旗鎗。","窜伏草莽间，股慄面玄黄。","窥伺不见人，喘汗走伥伥。","可中得火伴，约束归营场。","顺途劫寡弱，又各夸身彊。","将吏悉有献，欢喜赐酒觞。","杀贼不计数，从横书荐章。","民情大不甘，怨气结肾肠。","遂令父子恩，化作虿与蝗。","恨不斩官头，剔骨取肉尝。","累累野田中，拜泣祷天皇。","愿得贤宰相，飞笺奏岩廊。","先封尚方剑，按法诛奸赃。","择用忠荩臣，俾之提纪纲。","弯弧落鸱枭，薙棘出凤凰。","尚可存孑遗，耕稼纳官仓。","失今不早计，如水决堤防。","而后事堙筑，劳费何可当。","走闻疽初生，灼艾最为良。","焮成施剜割，所忧动膏肓。","边戎大重寄，得人则金汤。","龚遂到渤海，盗贼还农桑。","张纲入广陵，健儿跪如羊。","苟能任仁智，勿使憸邪妨。","孟门虽崄艰，可使成康庄。","走非慕爵赏，自鬻求荐扬。","痛惜休明时，消患无其方。","又不忍乡里，鞠为狐兔场。","陈词未及终，涕泣下滂滂。","旁观发上指，侧听心中伤。","天路阻且脩，不得羽翼翔。","可怜涸辙鱼，待汲西江长。","况有蛟与虬，磨牙塞川梁。","旄丘靡与同，载驰徒慨慷。","严冬积玄阴，天色惨以凉。","众鸟各自飞，孤鸾独徬徨。","冥冥丽山云，木叶殷清霜。","子去慎所过，我亦行归藏。"]},{"t":"遣怀","f":"五言古诗","c":["鸿鹄会高风，拂翼凌云霓。","蛟龙不得水，葺鳞困涂泥。","惟昔望诸君，一战举彊齐。","秦穆伯西戎，能用百里奚。","传说筑商岩，太公钓磻溪。","韩信寄食饮，孔明躬耕犁。","立贤苟无方，曷问鹜与鹥。","驱车上太行，峻极不可跻。","重云蔽层岑，流潦绝荒蹊。","豺狼当我嗥，魑魅向我啼。","顾瞻望九州，欲去惑东西。","嘉谷委蔓草，良田养蒿藜。","乘黄避跛鳖，狐貉骄虎貔。","谁言纵壑鱼，竟为触藩羝。","长夜起啸叹，邪气凭我脐。","梦登舜苍梧，遥望禹会稽。","援琴奏将归，日暮增惨悽。","盲飙正滃勃，孤凤将安栖。"]},{"t":"四月二十二日郊外游得水字","f":"五言古诗","c":["草根蝼蝈鸣，湖上蒹葭靡。","繁林袅深绿，清池散圆紫。","离居昧节序，陶情赖佳士。","泛舟出郊甸，缓涉信所履。","壶觞展倡酬，及此晴日美。","啸歌望山川，慷慨集悲喜。","豺狼未鼎镬，郊野尚多垒。","铁衣挂儒冠，好爵建麻屣。","吾侪幸味苦，得似道傍李。","无思身外忧，适意聊复尔。","归云入禹穴，返照射宛委。","鸟蹄树有风，帆过烟生水。","兴尽各言还，月明城角起。"]},{"t":"遣兴六首 其二","f":"五言古诗","c":["积雨兼数旬，天气凉有馀。","青苔交户庭，始觉人迹疏。","地主多闲园，可以种我蔬。","儿童四五人，蔓草相与锄。","既倦则归休，卧阅床上书。","无事且为乐，何者为名誉。"]},{"t":"遣兴六首 其六","f":"五言古诗","c":["迂疏乏世用，矫情非所安。","投簪谢时辈，聊得心中宽。","回首望故乡，枳棘日以繁。","譬彼水上萍，随流且盘桓。","楼头好山色，晴雨皆可观。","未知明朝事，且尽今日欢。"]},{"t":"久雨坏墙园蔬尽压帐然成诗","f":"五言古诗","c":["晚岁逼豺狼，漂摇去乡土。","囊橐罄留储，釜甑恒若窳。","开畦种蔬菜，拨借荷地主。","晨兴率童稚，树艺躬伛偻。","瓠实正累离，茄花亦争吐。","鱼肉方绝交，恃此当醢脯。","悲风吹江干，浩荡十日雨。","幽泉涌阴窦，高墉坼脩堵。","苍蔓压泥沙，朱苞埋宿莽。","凄凉紫芝英，乃与朝菌腐。","数奇值时危，一饱不敢取。","天地有穷愁，每望贫家聚。","青苔满颓墙，日暮空倚柱。"]},{"t":"次韵和脱因宗道感兴三首 其二","f":"五言古诗","c":["松柏守孤直，不争桃李色。","明星在青天，有时化为石。","春风车马尘，竟日翳紫陌。","宁知禾黍地，旧是王侯宅。","蓬莱有仙药，求之不可得。","霜风吹林木，岁暮徒怆恻。"]},{"t":"次韵和脱因宗道感兴三首 其三","f":"五言古诗","c":["铅刀方用世，挂壁干将闲。","剪松养荆棘，匠石空悲酸。","驱车陟大行，日暮多险艰。","玄冰胶大谷，脱粟贵琅玕。","魑魅揽人魂，豺狼食人肝。","路远无羽翼，何由得飞还。"]},{"t":"渡江遣怀","f":"五言古诗","c":["东风吹沧江，白日照花柳。","山川半显晦，积雨晴未久。","青阳好气候，群物竞苞剖。","农夫荷锄犁，各自登陇亩。","鸤鸠鸣相应，陂水光浏浏。","天地起戈兵，荆榛塞原阜。","兹邦特按堵，庶足憩奔走。","故乡有园田，委弃没藜莠。","老母年八十，头童齿牙朽。","痴儿始垂髫，出入寡朋友。","衣衾杂絮毳，羹食乏菘韭。","傫然多病身，全家倚糊口。","那今更远去，忧念成疾首。","千金聘宿瘤，顾谓西施丑。","盬车摧太行，骅骝不如狗。","况我驽蹇质，困踣畏培塿。","济河须巨舫，将焉用罂缶。","朱弦絙琴瑟，曷中洪钟纽。","剡蒿射犀革，空贻养由咎。","巍巍神祖烈，乾坤壤高厚。","蠢兹蛇豕俦，乘间恣哮吼。","非无熊罴臣，土产分左右。","更张吾岂能，习惯彼巳狙。","鹿麋曾伤虎，宵迈詟狸蹂。","寤言乱心绪，忽若醉醇酒。","疏贱等蚍蜉，捐驱复何有。","夷吾匪每生，鞠育未宜负。","怆恨忆松楸，泪湿蓬鬓垢。","道途正艰阻，进退维窊臼。","向风一陈情，何由达南斗。"]},{"t":"若耶溪杳郭深居精舍","f":"五言古诗","c":["上人好山居，入山惟恐浅。","纡馀涉渊沄，结搆依㟞嵃。","冈峦外挺拔，水木终隐显。","其前对鹅鼻，突兀正冠冕。","其傍连木禾，积翠森偃蹇。","后有狮子岩，崷崒露龈齴。","春花炫阳林，秋草馥阴畎。","高通云雨过，侧见星斗转。","桃源不远求，箕颍安足践。","我来三伏凉，羁怀忽如展。","谈经道心融，听法俗虑剪。","疏窗夜深启，孤月挂遥岘。","空濛白毫光，闪铄动崖巘。","何当此卜邻，永用辞淟湎。"]},{"t":"大热遣怀","f":"古风","c":["盛夏火用事，长日不可堪。","热汗发我肤，如泉溢穹嵁。","清晨登楼望，四野皆红岚。","坡坨会稽山，缥缈浮郁蓝。","何由作雨泽，一洗暍与酣。","须臾玻瓈盘，涌出琉璃潭。","杂气若绛旂，飘飖散空㟏。","朱光熭九幽，天色熇以䣻。","树木首咸俯，鸟兽声尽韽。","玄冥将禺彊，侧身入埪龛。","渊蛇葺短鳞，山龟灼枯?。","悍熊伏朝鼢，困龙缩秋蚕。","蕉根裂埴断，毙鹬蚌脯含。","水井为汤池，冶容成病颔。","渡水翅帖帖，守门口舑舑。","蜩螗轻绡翼，依阴萃枫楠。","沸渭泊静寂，噪聒乱语谈。","苍蝇丹砂头，群飞逐烹腤。","拍之适污手，驱之死仍耽。","对食惮下肮，引饮辄倾甔。","抚几炎欲燎，披衣重犹函。","慨彼征戍卒，荷戟忘寝?。","弃绝骨肉爱，不得同苦甘。","但闻盗贼炽，未见王师戡。","郊原虏掠遍，馈饷那能覃。","况乃隆暑节，蒸郁非所谙。","用兵贵拙速，将帅当怀惭。","沈冥及暮鼓，两目脂流泔。","拂袖招远风，众星烂天南。","河汉上昭回，烟霞远䰐鬖。","且喜辰极明，愿睹戎马倓。","云门连镜湖，林壑清且涵。","岂惟隔埃壒，庶足憩负担。","惜无五亩宅，偃蹇投吾簪。"]},{"t":"题杂画卷子","f":"五言古诗","c":["山川出云霓，溪谷藏虎豹。","枯树缯绫身，怪石磈礨貌。","竹枝如琅玕，烟雨昏幕罩。","梅花雪中开，的砾珠磊疱。","兰独称国香，姱丽最可乐。","荑纤草堪籍，伤覃棘能抓。","宋公学元晖，骇兽见腾䶂。","老班性嗜酒，藻思发馀酵。","丹丘泣龙髯，零落江湖棹。","颠王食败笔，得米动盈窖。","僧明本静者，一艺起众闹。","展卷见历历，聊足解喧嗃。","裁诗慕韩豪，琐细非所较。"]},{"t":"题赵文敏公画松","f":"古风","c":["吴兴昔王孙，能画世莫及。","观其二松图，矫若龙出蛰。","蟠根破坤舆，拔萃滃原隰。","交加各轩翥，崱屴相倚立。","鼍鳞撑空青，豕鬣振飒飁。","高藏日月气，清滴云雾汁。","垂钓者何人，短棹非妄集。","五湖多风涛，蛟蜃头角?。","不如洿泽间，取足绩与鳛。","倦眠松影下，百窍清凉入。","慎勿惊松枝，天寒衣袂湿。"]},{"t":"感时述事十首 其一","f":"五言古诗","c":["天王有万国，抚治不能遍。","百僚分所司，控制倚方面。","旬宣贵浃洽，付托属隆眷。","易置苟无恒，勤怠朝夕变。","自非勃氏俦，何官匪邮传。","矧兹世多故，军府希閒宴。","戎机一以失，蚁穴偾台殿。","公庭委旧事，书牍呈新选。","来者且迟迟，在者同秋燕。","偷安待日至，退托从私便。","奸贪遂乘隙，民病孰与唁。","大臣国柱石，忧喜相连缠。","反躬既遗阙，何以率州县？","寄与要津人，有舌未宜咽。"]},{"t":"感时述事十首 其二","f":"五言古诗","c":["十羊烦九牧，自古贻笑嗤。","任贤苟不贰，焉用多人为。","师行仰供给，州县方告疲。","差徭逮所历，添官有权宜。","柰何乘此势，争先植其私。","百司并效尤，货贿从横飞。","列坐隘公堂，号令纷披离。","名称到舆隶，混杂无尊卑。","正官反差出，道路不停驰。","徇禄积日月，官吏之所希。","此辈欲何求，朘剥图身肥。","世皇一宇宙，四海均惠慈。","盗贼乘间发，咎实由官司。","云胡未悔祸，救焚用膏脂。","姻娅遂连茹，公介弃草茨。","农郊日增垒，良民死无期。","天关深虎豹，欲语当因谁。"]},{"t":"感时述事十首 其三","f":"古风","c":["先王制民产，曷分兵与农。","三时事耕稼，阅武在严冬。","乱略齐愤疾，战伐厥有庸。","那令异编籍，自使殊心胸。","坐食不知恩，怙势含威凶。","将官用世袭，生长值时雍。","岂惟昧韬略，且不习击?。","悍卒等骄子，有令亦无从。","跳踉恣豪横，鼓气陵愚惷。","所以丧纪律，安能当贼锋。","崩腾去部曲，蚁合寻归踪。","时方务姑息，枉法称宽容。","宁知养豺虎，反噬中自钟。","国家立制度，恃此为垣墉。","积弊有根源，终成肠肺痈。","何由复古道，一视均尧封。"]},{"t":"感时述事十首 其四","f":"五言古诗","c":["豢狗不噬禦，星驰募民兵。","民兵尽乌合，何以壮干城。","百姓虽云庶，教养素无行。","譬彼原上草，自死还自生。","安知徇大义，捐命为父兄。","利财来应召，早怀逃窜情。","出门即剽掠，所过沸如羹。","总戎无节制，颠倒迷章程。","威权付便嬖，赏罚昧公平。","饥寒莫与恤，锐挫怨乃萌。","见贼不须多，奔溃土瓦倾。","旌旗委曲野，鸟雀噪空营。","将军与左右，相顾目但瞠。","此事巳习惯，智巧莫能争。","庙堂忽远算，胸次猜疑并。","岂乏计策士，用之非至诚。","德威两不立，何以御群氓。","慷慨思古人，恻怆泪沾缨。"]},{"t":"感时述事十首 其五","f":"五言古诗","c":["古人有战伐，诛暴以安民。","今人尚杀戮，无问豺与麟。","滥官舞国法，致乱有其因。","何为昧自反，一体含怒瞋。","斩艾若草芥，虏掠无涯津。","况乃多横敛，殃祸动辄臻。","人情各畏死，谁能坐捐身。","所以生念虑，啸聚依荆榛。","暴寡惮强梁，官政惟因循。","将帅各有心，邈若越与秦。","迁延相顾望，退托文移频。","坐食挫戎机，养虺交蛇鳞。","遂令耕桑子，尽化为顽嚚。","大权付非类，重以贻笑颦。","鼠璞方取贵，和璧非所珍。","但恐胥及溺，是用怀悲辛。"]},{"t":"感时述事十首 其六","f":"五言古诗","c":["五溪旧三苗，蛇蚓相杂处。","其人近禽兽，巢穴依险阻。","起居任情欲，斗狠竞爪距。","况能识君臣，且不顾子父。","所以称为凶，分北劳舜禹。","先朝慎羁縻，罔俾来中土。","胡为倏而至，驰骤如风雨。","见贼但趑趄，逢民辄俘虏。","腰缠皆金银，衣被俱绣组。","所过恶少年，改服投其伍。","农家劫掠尽，何人种禾黍。","盗贼有根源，厥咎由官府。","任将匪能贤，败衄乃自取。","奇材何代无，推诚即心膂。","谁哉倡此计，延寇入堂宇。","割鼻救眼睛，于身竟奚补。","浙西耕桑地，百载安生聚。","自从甲兵兴，徵敛空轴杼。","疲氓真可怜，忍令饲豺虎。","追忆至元年，忧来伤肺腑。"]},{"t":"感时述事十首 其七","f":"五言古诗","c":["虞刑论小故，夏誓殄渠魁。","好生虽大德，纵恶非圣裁。","官吏逞贪婪，树怨结祸胎。","法当究其源，剪锄去根荄。","蒙茏曲全宥，驾患于后来。","滥觞不堙塞，滔天谷陵颓。","总戎用高官，沐猴戴母頧。","玉帐饫酒肉，士卒食菜薹。","未战巳离心，望风遂崩摧。","招安乃倡议，和者声如雷。","天高豹关远，日月照不该。","俱曰贼有神，讨之则蒙灾。","大臣恐及己，相视若衔枚。","阿谀就姑息，华绂被死灰。","奸宄争效尤，无风自扬埃。","啸聚逞强力，谓是爵禄媒。","黎民亦何辜，骨肉散草莱。","倾家事守禦，反以结嫌猜。","恸哭浮云黑，悲风为徘徊。","赤子母不怜，不如绝其胚。","养枭逐凤凰，此事天所哀。","胡为尚靡定，颠倒陛与颏。","春秋戒肆眚，念此良悠哉。"]},{"t":"感时述事十首 其八","f":"五言古诗","c":["八政首食货，钱币通有无。","国朝币用楮，流行比金珠。","至今垂百年，转布弥寰区。","此物岂足贵，实由威令敷。","庙堂喜新政，躁议违老夫。","悠悠祖宗训，变之在朝晡。","瞿然骇群目，疑怪仍揶揄。","至宝惟艰得，韫椟斯藏诸。","假令多若土，贱弃复谁沽。","钱币相比较，好丑天然殊。","譬彼絺与绤，长短价相如。","互市从所取，孰肯要其觕。","此理实易解，无用论智愚。","矧兹四海内，五载横戈殳。","赤子投枳棘，不知所归途。","一口当万喙，唇缩舌亦瘏。","导水必寻源，源达流乃疏。","艺木必培根，根固叶不枯。","慎勿庸迩言，扬火自焚躯。","尚克诘戎兵，丕显厥祖谟。"]},{"t":"感时述事十首 其九","f":"五言古诗","c":["惟民食为命，王政之所先。","海鹾实天物，厥利何可专。","贪臣务聚财，张罗密于毡。","厉禁及鱼虾，卤水不得煎。","出门即陷阱，举足遭缠牵。","炰炰用鞭箠，冤痛声相连。","高牙开怨府，积货重奸权。","分摊算户口，渗漉尽微涓。","官征势既迫，私贩理则然。","遂令无赖儿，睚眦操戈鋋。","出没山谷里，陆梁江海边。","横行荷䉂笼，方驾列船舷。","拒捕斥后懦，争彊夸直前。","盗贼由此起，狼藉成蔓延。","先王务广德，如川出深渊。","外本而内末，民俗随之迁。","自从甲兵兴，奄忽五六年。","借筹计得丧，耗费倍万千。","回忆至元初，禁网疏且平。","家家有衣食，畏刑思保全。","后来法转细，百体皆拘挛。","厚利入私家，官府任其愆。","大哉乃祖训，典章尚流传。","有举斯可复，庶用康迍邅。"]},{"t":"感时述事十首 其十","f":"五言古诗","c":["秦皇县九宇，三代法乃变。","汉祖都咸阳，一统制荒甸。","豪雄既铲削，疮痍获休宴。","文皇继鸿业，垂拱未央殿。","累岁减田租，频年赐缣绢。","太仓积陈红，圜府朽贯线。","是时江南粟，未尽输赤县。","方今贡赋区，两际日月竁。","胡为倚东吴，转饷给丰膳。","径危冒不测，势与蛟龙战。","遂令鲇与鲵，掉尾乘利便。","扼肮要国宠，金紫被下贱。","忠良怒切齿，奸宄竞攀援。","包羞屈政典，尾大不可转。","圣人别九州，田赋杨为殿。","中原一何膴，所务非所先。","豳风重稼穑，王业丘山奠。","夫征厉末习，孰敢事游燕。","哀哉罔稽古，生齿徒蕃羡。","一耕而十食，何以奉征缮。","长歌寄愁思，涕泪如流霰。"]},{"t":"丙申二月别绍兴诸公","f":"五言古诗","c":["劳生属时艰，将老萃忧戚。","风尘隘九野，何土为乐国？","兹邦控吴越，名胜闻自昔。","湖山竞奇丽，物产亦充斥。","交游尚质俭，而不事华饰。","况有良友朋，时来慰岑寂。","全家免寒饿，几欲忘旅客。","胡为复舍此，僶俛就行役。","轩车远追送，酒至泪辄滴。","还乡人所乐，我独愁苦剧。","故山有松柏，摧折为荆棘。","岂无骨肉亲，太半生死隔。","此语不可闻，此景那堪觌。","愁情如波涛，澒洞胸与臆。","伫立向穹苍，一叹双鬓白。"]},{"t":"雨中杂诗四首 其一","f":"五言古诗","c":["久晴思得雨，既雨久复厌。","广庭屯阴气，平陆就昏垫。","凄风吹人寒，朱火黯无燄。","水衣上高墉，泉溜发枯堑。","青泥没逵道，寸步不可觇。","慷慨成感伤，缠绵积忧念。"]},{"t":"雨中杂诗四首 其二","f":"五言古诗","c":["首夏凉风生，朝树结晚色。","濛濛细雨交，惨惨原野黑。","衡门长藜莠，坏壁穿荆棘。","念彼征戍儿，沾湿荷戈戟。","囊橐罄留赀，藿菽难充食。","供输既乏绝，战斗何时息。","巢居者谁子，鼠窜延晷刻。","田畴没蓬蒿，无处勤尔力。","旻天高寥寥，仰视不可极。"]},{"t":"雨中杂诗四首 其三","f":"五言古诗","c":["多雨损万物，草烂麦生耳。","青苔独得时，延蔓及堂戺。","晨兴视天宇，滴沥殊未已。","君子惧陆沉，小人忧饿死。","凄凉大将营，鼓缦弧弓弛。","朝廷竟知否，盗贼如流水。"]},{"t":"雨中杂诗四首 其四","f":"五言古诗","c":["离居感时节，寤寐不遑安。","青灯晦壁角，檐溜如崩湍。","屈指计日月，殷忧集多端。","蛙黾尔何知，叫噪喧草莞。","中夜揽衾裯，凄凄阴气寒。","凤凰铩羽翼，卑飞避鸱鸢。","抚几一长叹，声出心巳酸。"]},{"t":"次胡元望郊行诗韵","f":"五言古诗","c":["谁言公馆清，晨气晚未散。","岂乏树葱芊，尚有花烂熳。","美人隔巷陌，可念不可唤。","温温夜光璧，幽丱潜璀璨。","鄙夫竞喧哗，达士善大观。","世情如秋莲，零落风中瓣。","少年喜纷纭，谈笑轻绛灌。","进取务出奇，周虑非习惯。","逝水难重回，芳时愁坐换。","元臣镇方面，边戎仰成算。","应怜四郊外，荆棘满耕畔。","悽悽忧葵女，恻恻抚床瓘。","兴怀增感伤，展转过夜半。","起行视青天，星河色凌乱。","安能作野马，脱略谢羁绊。"]},{"t":"夏中病疟戏作呈石末公","f":"五言古诗","c":["晚浴烝骨毛，蹭蹬张万孔。","不虞小人风，堀堁触埲塕。","长驱毒暑气，熇若燎发照。","钻肤入经络，键钥砉冲捅。","蚩蚩水帝子，鼠伏伺腥絜。","痴琚与狡瓆，并出助摧挏。","天君赫斯怒，六军躬自董。","丹元将爽灵，逆击阚哮唝。","主客相批亢，乾坤为摇动。","初交且躇躇，再接遂咏咏。","翛翛螽股切，嗅嗅鵙翅翪。","萧飕叶鸣軿，釐辘车转□。","惊沙走窸窣，落雪旋蠛蠓。","凌竞剥床辨，敲琢摇佩琫。","玄冰结太阴，河海溢银汞。","俄然一阳复，日脚舒暡曚。","微微细泉涌，拂拂轻烟翁。","柔枝披婀娜，弱叶散萋菶。","值如九乌焰，炽烈昧窥祼。","炎炎祝融火，焮灼炀巃嵷。","龙奔归大漠，虎逝蛰空巃。","烘惔熟金石，闪烁歊螮蝀。","肆伐殄嚚嚚，止齐安懵懵。","岑头释戴压，雨汗涣流滃。","黑酆群丑馘，黄庭百神总。","颇怪天地气，去来何倥偬。","集如蚁赴膻，散若蜂辞桶。","弃置且勿思，宵鼓听谨谨。"]},{"t":"秋夜感怀柬石末公申之","f":"古风","c":["不寐知夜长，起视天宇阔。","散漫草上风，朦胧云间月。","寒禽鸣疏树，黄叶堕阶闼。","俛仰观群物，惆怅不敢发。","谁云蝼蚁壤，能使泰山?。","苍鹰铩六翮，狡兔营三窟。","何当威弧正，王旅得肆伐。","箘簬虽微材，尚可施羽筈。","岂意风浪舟，心犹隔胡越。","士生非金玉，有足难自达。","周嫠不恤纬，楚放常怀阙。","平生葵藿情，忍与霜露歇。","玄冰胶坤轴，非君孰能斡？","申章匪繁辞，悲愤不可遏。"]},{"t":"次韵和石末公用元望韵遣兴见寄","f":"五言古诗","c":["鹁鸠劝春耕，桴鼓帖宵逻。","抚循馀暇日，珠玉生咳唾。","时维青阳初，天子在左个。","布德顺木令，万国罔不和。","禄食自纷纭，抚字谁最课。","幅员若金瓯，丝发无璺破。","涓溜可摧山，机祸不在大。","中夜登高楼，遥瞻太微座。","乾坤漭寥落，日月飞鸟过。","愤惋空有心，盛时嗟巳蹉。"]},{"t":"以野狸饷石末公因侑以诗","f":"古风","c":["野狸性狡猾，夜动昼则潜。","絷之笼槛中，耳弭口不呥。","当其得意时，足爪长且铦。","跳踉逞俊捷，攫噬靡有餍。","贫家养一鸡，冀用易米盐。","尔黠弗自食，寻声窃窥觇。","破栅舔肉血，淋漓汗毛髯。","老幼起顿足，心如刺刀镰。","东邻借筌蹄，西邻呼?猃。","系饵翳丛灌，设伏抽阴钤。","彼机歘巳发，此欲方未欦。","丝绳急缠绕，四体如黐黏。","野人大喜慰，不敢私烹燖。","持来请科断，数罪施剜?。","使君镇方面，残贼职所歼。","械送致麾下，束缚仍加钳。","腥膏忝污钺，膻胔或可腌。","芼芳和糟酱，颁赐警不廉。","黄雀利螳螂，碎首泥涂沾。","乌鸦殉腐肉，喷墨身受淹。","此物亦足戒，申章匪虚䛁。"]},{"t":"和石末公种棘用胡元望韵","f":"五言古诗","c":["力役困年侵，种棘代遮逻。","豫防苟无失，有地孰敢唾。","风条曲抽乙，雨叶细垂个。","是时春载阳，土脉如膏和。","分疆督艺植，勤惰各有课。","挥锄绿烟披，转石苍藓破。","稍看萌蘖长，渐睹根株大。","结荫冒长堤，开花映高座。","猿公不敢窥，貉子那得过。","慨慕陶公言，罔俾分阴蹉。"]},{"t":"得令字","f":"五言古诗","c":["勾芒发陈根，北斗转东柄。","众星各参差，威弧何时正。","好生虽圣心，明刑亦王政。","哲人慎谋始，斯焉获终庆。","徒言两阶舞，可以怀逆命。","不见三危山，万里窜枭獍。","世德异唐虞，民情好争竞。","那无跗扁医，而有膏肓病。","波涛地轴臲，虎豹天关夐。","雨露当春滋，风霜及秋劲。","谁能奉明主，顺天行号令。"]},{"t":"正月廿三日得台州黄元徽书有感 其一","f":"五言古诗","c":["世乱网恢恢，斯人亦沦翳。","数奇当何如，穷途难为计。","盲风振乔木，硕果失其蒂。","虎豹落机槛，坐服舆皂制。","玄珠迷罔象，白日惨阴曀。","涉水水有蛟，入山山有彘。","弃马感须无，直道怀柳惠。","青冥无羽翼，悲来夜迢递。"]},{"t":"正月廿三日得台州黄元徽书有感 其二","f":"五言古诗","c":["结交无疏戚，艰难见平生。","金石苟不渝，万里如两楹。","重山非云远，邈若辽与荆。","嬿婉岂不怀，蛇虺正骄狞。","手持故人书，心念故人情。","开书问故人，泪下如雨倾。"]},{"t":"正月廿三日得台州黄元徽书有感 其三","f":"五言古诗","c":["客从何乡来，遗我尺素书。","道路险且艰，故人情有馀。","妖气晦斗极，黄浊混龙鱼。","何荃不为莸，何麟不为貙。","殷勤故人心，炯若明月珠。","投之千丈泥，万古光不渝。","安得致阊阖，以照君王车。"]},{"t":"次韵和石末公春雨见寄","f":"五言古诗","c":["愁阴沴阳景，孟春犹苦寒。","腾云涌岩岫，落雪蔽江干。","街衢溢黄潦，井谷生狂澜。","误疑蛙黾窟，中有蛟龙蟠。","复忧扶乘日，坐为黄浊漫。","顾瞻望四郊，侧足不遑安。","却秦慕鲁连，存齐想田单。","玄发虽向改，壮心终靡殚。","小人务苟且，君子惭素餐。","高牙对多垒，肉食徒王官。","周纲虽云弛，一匡赖齐桓。","莫惊沟浍盈，雨息当自乾。"]},{"t":"次韵和石末公春日感怀","f":"五言古诗","c":["下泽潢潦集，幽林光景迟。","羁禽有哀响，槁叶无丰姿。","粱稊不同亩，世事久当遗。","便欲驾扁舟，泛彼湖上漪。","慨怀祈招赋，怆恻感遐思。","流光逐飘风，去若六马驰。","干戈尚杂遝，举目多可悲。","步登西城楼，还望东城陴。","近悼舂陵吟，远伤鸿雁诗。","未能巳怨怒，矧暇防笑嗤。","赖有贤大夫，直道人不欺。","相期各努力，共济艰难时。"]},{"t":"偶兴","f":"五言律诗","c":["劳人怨长途，壮士悲老别。","那将望乡心，对此伤神月。","凄凉寒风至，惆怅芳草歇。","瑶琴无子期，丝弦为君绝。"]},{"t":"黄慎之自闽见访夜坐对酌怅然有感四首 其一","f":"五言律诗","c":["故人一为别，七见秋夕月。","今日见故人，故人须发新。","世情如须发，故人当识察。","车轮东北驰，车毂终不移。"]},{"t":"郑同夫饯别图诗","f":"五言律诗","c":["江上潮始白，林端霞半紫。","微风飏归帆，红叶映行子。","芳醪耻金樽，清歌犹在耳。","马鸣不见人，愁来若流水。"]},{"t":"为本大师题唐临晋帖","f":"古风","c":["乾符天子万机暇，宫中扈从多儒冠。","玉堂开宴出晋帖，翠气荡摇山雪寒。","侍臣模写各臻妙，碧树琼柯相照耀。","令孜嗟叹至尊喜，内官拜舞宫娥笑。","日斜宴罢归内园，外门有事人不言。","君不见关东夜飞赤白丸，昭陵玉匣秋风酸。"]},{"t":"题钟馗役鬼移家图","f":"七言律诗","c":["髯夫当前黧妇后，腊鬼作粮驱鬼负。","虹霓可驾雷可车，胡为役鬼来肩舆？","乃知老馗未公正，怙威植私干律令。","玄云沈阴鬼怪多，馗乎馗乎奈尔何！"]},{"t":"为王辅卿郎中题雪滩寒雁图","f":"古风","c":["云茫茫，水浪浪，林木脱叶无稻粮。","乌啼雁叫天苍凉，岁云莫矣江山长。","有竹有竹在高冈，三株冻折两复僵，小禽悲飞不能扬。","苍梧悠悠隔沅湘，欲往从之川无梁。","愿披寒霄见朝阳，勿令嗷嗷伤我肠。"]},{"t":"画竹歌为道士詹明德赋","f":"楚辞体","c":["我所思兮在潇湘，苍梧九疑渺无际，但见绿竹参天长。","上有寒烟凝不飞，下有流水声琅琅。","中有万古不尽离别泪，化作五色丹霞浆。","穿崖贯石出厚地，风吹露涤宵有光。","我欲因之邀凤凰，天路脩阻川无梁。","孰知画史解人意，能以造化归毫芒。","虚堂无人白日静，使我顾盼增慨慷。","玄霜惨烈岁将宴，鼪啼鼯叫天悲凉。","我所思兮杳茫茫，山中紫笋春可茹，归来无使遥相望。"]},{"t":"辛卯仲冬雨中作二首 其一","f":"七言律诗","c":["江城积阴愁玄冬，千家万家云水中。","乌啼黄昏雁叫夜，鼓角惨澹愁悲风。","青灯无光掩关坐，饥鼠相衔啼过我。","读罢残书有所思，冻雨霏霏泪交堕。"]},{"t":"辛卯仲冬雨中作二首 其二","f":"七言律诗","c":["岁云暮矣风萧萧，木叶脱落惟空条。","云浓雨细白日短，惨惨不辨昏与朝。","雨中行人足斛觫，去与公家制戎服。","中原豺虎正横戈，天寒风急柰尔何。"]},{"t":"悲杭城","f":"七言古诗","c":["观音渡头天狗落，北关门外尘沙恶。","健儿披发走如风，女哭男啼撼城郭。","忆昔江南十五州，钱塘富庶称第一。","高门画戟拥雄藩，艳舞清歌乐终日。","割膻进酒皆俊郎，呵叱闲人气骄逸。","一朝奔迸各西东，玉斝金杯散蓬荜。","清都太微天听高，虎略龙韬缄石室。","长夜风吹血腥入，吴山浙河惨萧瑟。","城上阵云凝不飞，独客无声泪交溢。"]},{"t":"夏夜台州城中作","f":"七言古诗","c":["江上火云蒸热风，欲雨不雨天瞢瞢。","良田半作龟兆坼，粳稻日夕成蒿蓬。","去年海贼杀元帅，黎民星散劫火红。","耕牛剥皮作战具，锄犁化尽刀剑锋。","农夫有田不得种，白日惨淡衡茅空。","将军虎毛深玉帐，野哭不入辕门中。","健儿斗死乌自食，何人幕下矜奇功。","今年大军荡淮甸，分命上宰麾元戎。","舞干再见有苗格，山川鬼神当效忠。","胡为旱魃还肆虐，坐令毒沴伤和冲。","传闻逆党尚攻剽，所过丘垄皆成童。","阃司恐畏破和议，斥堠悉罢云边烽。","杀降共说有大禁，无人更敢弯弧弓。","山中悲啼海中笑，蜃气绕日生长虹。","古时东海辟孝妇，草木枯瘁连三冬。","六月降霜良有以，天公未必长瘖聋。","只今幅员广无外，东至日出西太蒙。","一民一物吾肺腑，仁者自是哀鳏恫。","养枭殈凤天所厌，谁能抗疏回宸衷。","夜凉木末挂河汉，海峤月出光玲珑。","仰视皇天转北斗，呜呼愁叹何时终。"]},{"t":"题释骖图","f":"古风","c":["关中小儿勇而竞，玉帐貔貅三百乘。","焉知道上十二牛，皇天默佑周同姓。","绛宫大厉吼如雷，墨车载甲光照䋿。","鹰腾二陵间，剑锋白皑皑。","壮士百战脑涂地，元帅束缚坐草莱。","俘囚有血堪衅鼓，自分残膏染齐斧。","万死一生直望外，岂意片言由内主。","鸿雁曾伤弓，尚为空弮愁。","犀兕脱匣出，闻呼肯回头。","河边解骖徒谫谋，舟中稽首心悠悠。","济河封尸勿云晚，此事终作晋国羞。","君不见夫差违子胥，空洒姑苏泣。","丈夫深戒妇人仁，养虎遗患悔莫及。"]},{"t":"题钱舜举马图","f":"古风","c":["吴兴公子雅好奇，欲把丹青竞天巧。","花蜂柳莺看巳足，貌得骅骝图更好。","浪花满身蹄削諲，两耳抽出春笋尖。","风鬉欲拂九霄雾，隅目似挂高秋蟾。","昨者王良失鞿鞚，封狼咆哮蛇豕閧。","天闲乘黄越在野，出车未见歌南仲。","呜呼，安得此马背负郭令公，扫清四海归奏明光宫。"]},{"t":"题陆放翁卖花叟诗后","f":"古风","c":["君不见会稽山阴卖花叟，卖花得钱即买酒。","东方日出照紫陌，此叟巳作醉乡客。","破屋含星席作门，湿萤生灶花满园。","五更风颠雨声恶，不忧屋倒忧花落。","卖花叟，但愿四海无尘沙，有人卖酒仍卖花。"]},{"t":"为包与直题太一真人图","f":"古风","c":["太一真人庞眉须，不知所持何代书。","既不学昴星，降精下辅隆准公。","又不学傅说，请帝通梦寐左右。","商王陈范谟，眇然一叶莲花荂。","清秋风吹落泥涂，红凋粉瘵不可扶。","君何为乎以为桴，荡漾九河凌五湖。","誇耀水伯惊天吴，坐令文成五利之辈假借神圣欺庸愚。","灵旗风翻壮荆符，獐鹿无鬼夫何辜。","汉宫天禄连石渠，金釭衔璧丽绮疏。","青藜有燄如美蕖，何不分饷依光夜绩之徐吾？","高堂耽耽县画图，作歌一笑骇里闾。"]},{"t":"为戴起之题猿鸟图","f":"古风","c":["巴东之西巫山高，连峰插天关健牢。","中有怀陵簸谷之波涛，藤萝杳冥风怒号。","人迹不到神鬼逃，但见野猿沙鸟群相嘈，聱耴百窍摇岩嶅。","此景可闻不可遭，尔何为乎貌以毫毛，嗟哉用心无乃劳。","江盘峡束雷雨昏，崩崖死树缠古根。","玄猿抱儿随白猿，长臂婹袅相攀援。","舔睒谲诡趠腾骞，县柯攫石坠且掀。","上有满月如赪盆，筼筜桃枝寒自蕃。","嘉实不食凤高翻，但见娥皇女英之泪痕。","势穷险尽原野辟，落日乌鸦绕云黑。","荻花茫茫芦叶赤，前飞鸹鸧后凫鹢。","潇湘洞庭烟水碧，驺虞鸑鷟无颜色。","还君此画长太息，独立看天泪沾臆。"]},{"t":"题群龙图","f":"七言古诗","c":["世间万类皆可睹，茫昧独有鬼与龙。","此图画龙二十四，状貌诡谲各不同。","得非物产有异种，或曰神变无常踪。","一龙揵尾欲上木，足爪犹在奫沄中。","一龙出穴饮涧底，头上飞瀑泻白虹。","前有一龙巳在云，顾视厥子扬双瞳。","浪波鱼鳞沓谾豅，日车坱圠天无风。","中庭两龙忽相逢，须眉葩髿如老翁，便欲角抵争雌雄。","西望积石接崆峒，白龙擘石窥流潨。","河伯远遁虚其宫，屈蟠睡者何龙钟，老物用亢时当终。","峡外六龙狞以凶，矜牙舞爪起战攻。","咬鳞嚼甲含剑锋，陷胸折尾波血红，之死弗悟人谁恫？","一龙引吭将欲从，回环睢盱未敢通。","最后一龙藏于埪，睥睨胜败非愚蒙，无乃有意收全功。","云中弄珠劳尔躬，不如卧沙之从容。","龙子学飞力未充，母在下视心憧憧。","何物一角额准隆，觓然出洞若蛇虫。","有龙接之自巃嵷，恐是巩穴王鲔公，皮骨始蜕形犹蒙。","两龙归来倦不翀，痴龙攀石身巳癃。","蚴蚪偃蹇歘腾冲，蜿蟺攫跃鬐发茸，呿呀奔拿曲如弓。","百态并作何纷庞，是耶非耶孰能穷。","画师昔有僧繇工，能令真龙下虚空。","安得伶伦截竹筒，吹之呼龙出石谼，使我一见开昏瞢。"]},{"t":"为丘彦良题牧溪和尚千雁图","f":"七言古诗","c":["往时惠崇画芦雁，对之如在江湖游。","只今此图又精妙，中有千里潇湘秋。","乃知浮屠性多巧，意匠不与凡夫俦。","吴松江长具区阔，天目虎丘青一发。","西风九月粳稻黄，朔雁飞来翼相戛。","农夫苦饥雁独饱，此意画师应识察。","近者分明辨羽毛，远者缥缈瞻秋毫。","或乘飘风入烟霄，或翳落日沉隍濠。","起如武侯布八阵，集如万舞回旌旄。","眠沙卧草鸣且翱，喋呷藻荇乱蓬蒿。","禾空穗尽却归去，紫塞漠漠春云高。","我家南山限苍岭，雁飞不到川路永。","深林大谷蛇豕盛，愁向他乡抚虚景。","人言鸿雁比弟兄，我有兄弟隔两城。","题诗卷画谢客去，无使感怆伤中情。"]},{"t":"雨中寄用章上人","f":"七言古诗","c":["月盈复魄巳过五，不见白日长见雨。","美人娟娟隔巷陌，会面不得徒延伫。","若邪当门泉涌础，仲蔚蓬蒿塞环堵。","阴风向人作秋气，芳草日夕成宿莽。","玄圭上天禹穴闭，苍水使者今何许？","玉京群仙翳烟雾，弱水西流隔玄圃。","女夷鼓歌不自觉，朱凤翅湿那能举。","自从干戈起淮甸，天下无处无豺虎。","徵敛频烦转输急，更有何乡为乐土。","翳桑饿人谁复数，思家远客空悽楚。","半生身世付浮云，独立看云百忧聚。","晚来天南横绛虹，雨势未已愁雷公。","井蛙谷鲋俱得意，泛滥潢潦登穹隆。","方外文章谁最好，后有懒公前笑老。","裁诗忽漫寄中情，万事茫茫听苍昊。"]},{"t":"玉涧和尚西湖图","f":"七言古诗","c":["大江之南风景殊，杭州西湖天下无。","浮光吐景十里外，叠嶂涌出青芙蕖。","百年玉气散荆棘，惟有歌舞留欢娱。","重楼峻阁竞铅黛，媚柳娇花使人爱。","老僧不善儿女情，故作觕豪见真态。","想其泚笔欲画时，高视画工如小儿。","千岩万壑吾意匠，夸娥巨灵吾指麾。","却忆往年秋雨夕，画舫冲烟度空碧。","苍茫不辨云与山，但觉微风响芦荻。","须臾冷月迸深雾，时见松杉半昏黑。","开尊命客弹焦桐，扣舷大笑惊海童。","鲛人唱歌鱼鳖应，水底影动双高峰。","只今倏忽成老翁，可怜此乐难再逢。","愁来看画欲自适，谁知感生愁转剧。"]},{"t":"题富好礼所畜村乐图","f":"七言古诗","c":["我昔住在南山头，连山下带清溪幽。","山巅出泉宜种稻，绕屋尽是良田畴。","家家种田耻商贩，有足懒踏县与州。","西风八月淋潦尽，稻穗栉比无蝗蟊。","黄鸡长大白鸭重，瓦瓮琥珀香新篘。","芋魁如拳栗壳赤，献罢地主还相酬。","东邻西舍迭宾主，老幼合坐意绸缪。","山花野叶插巾帽，竹箸漆椀蒹瓷瓯。","酒酣大笑杂语话，跪拜交错礼数稠。","或起顿足舞侏儒，或坐拍手歌瓯篓。","倾盆倒榼混醯酱，烂熳沾渍方未休。","儿童跳跃助諠噪，执遁逐走同俘囚。","出门不记舍前路，颠倒扶掖迷去留。","朝阳照屋且熟睡，官府亦简少所求。","宁知宴安含酖毒，耒耜一变成戈矛。","高门大宅化灰烬，蓬蒿瓦砾塞道周。","春燕营巢在林木，深山露宿随猿猴。","三年避乱客异县，侧身天地如浮沤。","亲朋阻隔童仆散，疏食水饮不自谋。","有时惝恍梦闾里，惊觉五内攒百忧。","君家画图称绝妙，鉴别曾遇柯丹丘。","想应临榻出秘府，笔意精到世罕俦。","村歌社舞自真率，何用广乐张公侯。","太平气象忽在眼，令我感怆涕泪流。","近者乡人来报喜，今岁高下俱有秋。","豺狼食饱卧窟穴，军师巳运招安筹。","人情自古共怀土，况乃霜雨凄松楸。","神龟且被预且困，予所弗念天我尤。","积薪厝火非远计，谁能献纳陈嘉猷。","长江波浪接淮泗，白日惨澹腾蛟虬。","天下农夫总供给，陇亩不得安锄耰。","市中食物贵百倍，一豕之价过于牛。","鱼盐菜果悉卖米，官币束阁若赘瘤。","朝餐仅了愁夕膳，谁复有酒浇其喉。","循环天运往必复，邪气暂至不远瘳。","此生此景须再睹，引领怅望心悠悠。"]},{"t":"为启初门和尚题山水图","f":"七言古诗","c":["天下名山随处有，画图流传亦良久。","祗园道人展横幅，观者称誇同一口。","苍梧九疑高插天，卷而怀之不盈手。","巨灵惊呼盘古怒，地轴坱圠昆仑剖。","太阳出海开杳冥，嶓冢岷峨大如斗。","华轩无人清昼闲，恍然置我匡庐间。","金轮迥出牛女上，远近罗列千云鬟。","江花野竹青锦斑，嵌岩断石蛟鼍颜。","冈盘谷转绝径路，但见湖水回琼环。","白沙洲暖春风起，南船挂帆北船舣。","吴波不尽芳草外，楚岫半入长烟里。","夜深小龙行雨归，宫亭月落彭郎矶。","旌阳步虚卢老和，杂佩散作虹蜺飞。","百年尘世真梦寐，回首旌旗塞天地。","旧游何处成渺茫，一曲狂歌数行泪。","青丘弱水迷方壶，武陵桃源今有无？","瑶台三岛消息断，安得羽翼归清都。"]},{"t":"题赵学士松图","f":"七言律诗","c":["赵公拈笔作古松，平地跃出三青龙。","蜿蜒不上霄汉去，爽飒长留烟雨浓。","前朝美人斗草处，犹有当时数株树。","江亭六月凉如秋，应与此图相对愁。"]},{"t":"题李陵见苏武图","f":"七言律诗","c":["中原无书羝不乳，狐裘蒙茸柰何许。","老身汉节死生俱，地角天涯见明主。","金鞍骏马空故人，相看一笑增悲辛。","悲来风沙吹上马，河水东流日西下。"]},{"t":"长平戈头歌","f":"古风","c":["长平战骨烟尘飘，岁久遗戈金不销。","野人耕地初拾得，土花渍出珊瑚色。","邯郸小儿强解事，枉使泥沙埋利器。","四十万人非少弱，勇怯贤愚一朝弃。","阴坑血冷秋复春，朽壤食尽苍蛇鳞。","湮沦长愧杜邮剑，废坠空忆桩喉人。","故垒中宵鬼神入，云愁月暗戈应泣。","呜呼，当时岂无牧与颇，戈乎不遇可柰何！"]},{"t":"钱王箭头篇","f":"七言古诗","c":["鸱夷遗魂拗馀怒，欲取吴山入江去。","雷霆劈地水群飞，海门扶胥没氛雾。","英雄一怒天可回，肯使赤子随鲛鲐。","指挥五丁发神弩，鬼物辟易腥风开。","三百年来人事改，涛落沙平箭空在。","石梁饮羽未足誇，蜀国三犀漫欺绐。","近闻黄河水乱流，青徐一半悲鱼头。","安得壮士斡地轴，为拯斯民涂炭忧。"]},{"t":"次韵和石末公七月十五夜月蚀诗","f":"七言古诗","c":["招摇指坤月望日，大月如盘海中出。","不知妖怪从何来，惝恍初惊天眼昳。","儿童走报开户看，城角咿呜声未卒。","蟾逃兔遁漠无踪，璧陨珠沉一何疾。","丈夫愕视隘街巷，妇女喧呼动圭筚。","辉辉稍辨河汉沬，耿耿渐明荒冢漆。","百官袍笏群吏趋，伐鼓撞钲仍设韠。","赤水难令罔象求，渑池莫效相如叱。","升檐变阁到空旷，瓂掩氛祲殊靡毕。","广寒桂树劫火烬，借问嫦娥有何术。","今年下土困炎沴，草木焦枯野萧瑟。","蓱号暍死龙甲焮，赤熛当衢挂萍实。","光芒照灼玄武烂，谁复琐琐怜蚌鹬。","今夜慝作最差异，天道幽微孰能诘。","太阴配日宰臣象，无乃常刑多纵轶。","近来营垒遍宇内，羽林惨澹空铁锧。","荒郊废市何所见，夔罔蛟蛇兼蚤虱。","此皆在地不在天，未若虾蟆狡而獝。","黄文结邻上诉帝，赐以小戎骖牡骘。","剖蟆洗魄还月光，再起咎繇明典秩。","返蟾归兔复纤阿，万古游尘避清跸。"]},{"t":"再用前韵","f":"七言古诗","c":["虞渊谽谺纳归日，金枢吐月相承出。","初离积水看若飞，稍映微云盼犹眣。","是时蓐收肇视政，莎鸡振羽鸣蜩卒。","姮娥靓妆觐玉帝，坎轲中途婴祸疾。","旅人苦热爱清凉，快睹光辉满蓬荜。","愿开宝鉴照覆盆，岂拟瘴尘昏点漆。","隋珠惭固重革匮，和璧嗟蒙韎韦韠。","吴罡树折不自谋，纤阿马弱无人叱。","三足蟾惊入坎洼，八窍兔走罹罝毕。","围灰破晕谩传方，屑玉补凹空著术。","雷公骇惧罢灵鼓，湘女幽忧舍鸣瑟。","故老谓是虾蟆精，潜伏奸妖营口实。","羲和尸位罔闻知，可以人而不如鹬。","往岁威弧弛其彀，蛇豕陆梁谁复诘。","高牙大纛拥藩垣，肠断吞声受陵轶。","江淮汹涌湖浙沸，骸骨成山连鬼锧。","万姓喁喁釜里鱼，百官蠢蠢裈中虱。","黄茅白苇弃贤良，赤绂玄裳宠狞獝。","昊穹示变盍警畏，惟德动天天有骘。","况今旱魃又为厉，东作西成不平秩。","安得缄辞伏阊阖，圣主如闻应驻跸。"]},{"t":"泾县柬宋二编修长歌","f":"古风","c":["浙东行人过江左，正值蕤宾之管吹轻葭。","阴气黯黕天地闭，仰面不见扶桑鸦。","谷风哀鸣灌木应，雨脚四垂如乱麻。","崩湍涌溜汩奔会，平地碾齧作臼洼。","便疑桑田变沧海，流水荧眼无津涯。","菅茅披猖黄竹拜，蛙黾狼籍助喧哗。","满路青泥杂陨箨，局缩畏触蛭与蛇。","破瓦荒畦旧市井，荆榛秽奥巢麇䴥。","翠眉蝉鬓转蓬去，颓墙缺甃劫火煆。","善淫祸福不可料，韶艳夭阏令人嗟。","丛祠佛殿总销歇，但见木偶眠泥苴。","前度长洲绝短涧，舆从沾湿水没胯。","寒飔瘆瑟透衣袖，虽有毡盖那能遮。","水边老鹳学人立，鹭鸶侍傍如小婐。","废田蔓草结旌旆，农夫尽化为虫沙。","布谷不知时事异，劝耕终日声查查。","晚来雨歇到泾县，只有蒿荻无人家。","县官趋迎入公廨，筋挛骨解肉半麻。","萧条破灶冷灰灺，饥童冻口张唅呀。","滹沱麦饭那能致，新丰酒醪何处赊。","古称悲歌可当哭，莫怪笑谑同儿哇。","夜深月出照庭树，鬼燐一似青莲华。","惊魂遁魄稍归舍，收入志虑无令邪。","愁云苦雾子规叫，起坐更盼羲和车。"]},{"t":"听蛙","f":"古风","c":["绕舍荒池底且■，蛰蛙齐候鸣雷社。","已知地气上如炊，更觉石泉流若泻。","举头玉烛焕阳明，?足污泥悲土苴。","半夜条风入绮窗，清晨细雨霏檐瓦。","梁间紫燕舞参差，枝上黄莺语悲姹。","播形肖貌均有生，感气伤情孰瘖哑。","初聆衙衙杂更鼓，渐听嘈嘈成侈哆。","犹持坚白较同异，似坐狙丘谈稷下。","村童叫噪聋学究，悍妇勃溪喧娣姐。","西域胡僧弹般若，齐东老生矜炙輠。","逸帆触岸靡蒹葭，醉客骂筵投盏斝。","呦咬谁辨骠儿哇，虩砉乍开賨叟呵。","怒牙嚼齧悸罗吞，寤言诘屈惊宜?。","徒夸楚使能詈齐，未让秦巫工诅芋。","兜离僸佅纷覼缕，帝乐虚张洞庭野。","虞夔奚暇调笙磬，周瞽曷由分郑雅。","旅人怀忧实无寐，遭此彊聒胡为者。","得非作奸谋蚀月，无柰聚讼腾欢谩。","昔闻周公立典教，蝈氏专司鞠灰洒。","常疑圣人茂育物，独向微虫少宽假。","乃今知其非琐屑，欲问官司乞馀灺。","凤皇鸑鷟声苦希，白雪阳春和偏寡。","蚊蝇蚤虱多于沙，钻咂喑鸣纷丑䰩。","虾蟆幸不含毒螫，何苦呶号争跁跒。","乌鸢逐响蛇听音，宁顾入腹生症瘕。","赋诗却笑柳柳州，忍使腥臊辱俎鲊。"]},{"t":"赠道士蒋玉壶长歌","f":"古风","c":["先生清如玉壶冰，神闲志一精粹凝。","玄黄健顺六子承，和气坱圠粗秽澄。","冲虚澹澹廓以弘，冥茫沕穆恬无能。","火乌入海阴液升，鹑蛇受约不敢腾。","束缚龙虎如寒绳，虚无黄堂帝所凭。","四方上下齐钩绳，北幽罗酆对朱陵。","女夷鼓歌王母应，琼宫夜半张华灯。","金葩碧叶红毾㲪，素霞郁滃玄云烝。","沆瀣厌浥沦泉兴，牵牛织女来相仍。","用之不减亦不增，地官锡福天官徵。","老蚌迸壳骊珠升，太一象舆骖八鹏。","翼以六蜺前五腾，风轮萧萧生夏凌。","参旗九斿茷绲縢，二八青蛾美目膡。","翠蕤交翟翱翪?，属车九九如连绳。","最后雷轺子所乘，流苏勃窣垂镂膺。","斑斓驳马骝骆驓，蹴霞踏雾碎绮绫。","天津阁道轥輷輘，归来瑶台十二层。","月光照耀玻瓈棚，下视瀛海波涛砅。","龙宫蜃窟寒兢兢，归塘旸谷清可凭。","鳞甲镜瑩鳄与鲮，湘妃鼓瑟冰丝縆。","摐金戛玉万穴?，琅玕风吹殷崚嶒。","琉璃云母龟贝朋，琳房璧甓珵阶升。","素鸾振迅霜女扔，璇题琐窗肃蕄蕄。","洞晃曭朗眩遥瞪，瘁肌砭髓魂欲殑。","忽然浮空堕杳瞢，飙驰电㸌羽脱肱。","天衢阻遐世网罾，昏昏日月敲炎蒸。","句曲之山崒硱磳，枫杉桧柏槠桂㭁。","蘅兰杜若蕙茝䔷，缘冈被岭羃涧膛。","大地浪井瀑练漰，萍濒绣绘芙蓉菱。","鼍虬蚴蚪千年藤，缠络薜荔县鬅鬙。","敷芳发馥菲芬艿，獑猢?蜼雕苍鹰。","攀援歘砉岩崿崩，寒螀蛇蛄䗿犯?。","岚餐霭饮喧岌峘，先生皮冠衣绛缯。","桃枝七尺穿虺螣，三茅真君共嗟称。","星根绝顶时同登，黄斑黑虎陟降凭。","石罅甘浆溢若渑，神芝吐燄如筼簦。","食时动机保不薨，驱斥琚瓆除瘕症。","眸光照座生紫棱，举觞引满鲸喉㵗。","解后见之喜莫胜，扬眉抵掌开蒙?。","人生嘉会安得恒，靖恭止直天所仍，作诗持赠匪妄譝。"]},{"t":"二鬼","f":"古风","c":["忆昔盘古初开天地时，以土为肉石为骨，水为血脉天为皮，昆崙为头颅，江海为胃肠，嵩岳为背膂，其外四岳为四肢。","四肢百体咸定位，乃以日月为两眼，循环照烛三百六十骨节，八万四千毛窍，勿使淫邪发泄生疮痍。","两眼相逐走不歇，天帝悯其劳逸不调生病患，申命守以两鬼，名曰结璘与郁仪。","郁仪手捉三足老鸦脚，脚踏火轮蟠九螭。","咀嚼五色若木英，身上五色光陆离。","朝发旸谷暮金枢，清晨还上扶桑枝。","扬鞭驱龙扶海若，蒸霞沸浪煎鱼龟。","煇煌焜耀启幽暗，燠煦草木生芳蕤。","结璘坐在广寒桂树根，漱咽桂露芬柏菲。","啖服白兔所捣之灵药，跳上蟾蜍背脊骑。","播光弄影荡云汉，闪奎烁璧葩花摛。","手摘桂树子，撒入大海中，散与蚌蛤为珠玑。","或落岩谷间，化作珣玕琪。","人拾得吃者，胸臆生明翚。","内外星官各职职，惟有两鬼两眼昼夜长相追。","有物来掩犯，两鬼随即挥刀鉟。","禁制虾蟆与老鸦，低头屏气服役使，不敢起意为奸欺。","天帝怜两鬼，暂放两鬼人间娭。","一鬼乘白狗，走向织女黄姑矶。","槌河鼓，褰两旗，跳下皇初平牧羊群，烹羊食肉口吻流膏脂。","却入天台山，呼龙唤虎听指麾。","东岩凿石取金卯，西岩掘土求琼葳。","岩訇洞砉石梁折，惊起五百罗汉半夜拨剌冲天飞。","一鬼乘白豕，从以青羊青兔赤鼠儿。","便从阁道出西清，入少微，浴咸池。","身骑青田鹤，去采青田芝。","仙都赤城三十六，洞主骑鸾翳凤来陪随。","神鬼清唱毛女和，长烟袅袅飘熊旂。","蜚廉吹笙虎击筑，罔象出舞奔冯夷。","两鬼自从天上别，别后道路阻隔，不得相闻知。","忽闻韩山子，往来说因依。","两鬼各借问，始知相去近不远，何得不一相见叙情词。","情词不得叙，焉得不相思。","相思人间五十年，未抵天上五十炊。","忽然宇宙变差异，六月落雪冰天逵。","鼋鼍上山作窟穴，蛇头生角角有歧。","鳄鱼掉尾斫折巨鳌脚，蓬莱宫倒水没楣。","搀枪枉矢争出逞妖怪，或大如瓮盎，或长如蜲蛇。","光烁烁，形躨躨。","叫鹿豕，呼熊罴。","煽吴回，翔魌魑。","天帝左右无扶持，蚊虻蚤虱蝇蚋蜞，噆肤咂血图饱肥，扰扰不可挥筋节。","解折两眼眵，不辨妍与媸。","两鬼大惕伤，身如受榜笞，便欲相约讨药与天帝医。","先去两眼翳，使识青黄红白黑。","便下天潢天一水，洗涤盘古肠胃心肾肝肺脾。","却取女娲所抟黄土块，改换耳目口鼻牙舌眉。","然后请轩辕，邀伏羲、风后、力牧、老龙告泰山稽。","命鲁般，诏工倕，使丰隆，役黔羸，砺斧凿，具炉锤，取金蓐，收伐材尾箕。","修理南极北极枢，斡运太阴太阳机。","檄召皇地示部署，岳渎神受约天皇墀。","生鸟必凤凰，勿生枭与鸱。","生兽必麒麟，勿生豺与狸。","生鳞必龙鲤，勿生蛇与?。","生甲必龟贝，勿生蝓与蜞。","生木必松楠，生草必荠葵，勿生钩吻含毒断人肠，勿生枳棘覃利伤人肌。","螟蝗害禾稼，必绝其蝝蚳。","虎狼妨畜牧，必遏其孕孽。","启迪天下蠢蠢氓，悉蹈礼义尊父师。","奉事周文公、鲁仲尼、曾子舆、孔子思，启习书易礼乐春秋诗。","履正直，屏邪欹，引顽嚚，入规矩。","雍雍熙熙，不冻不饥，避刑远罪趋祥祺。","谋之不能行，不意天帝错怪恚，谓此是我所当为，眇眇末两鬼，何敢越分生思惟。","呶呶向瘖盲，泄漏造化微。","急诏飞天神王与我捉此两鬼拘囚之，勿使在人寰做出妖怪奇。","飞天神王得天帝诏，立召五百夜叉带金绳将铁网，寻踪逐迹莫放两鬼走逸入崄巇。","五百夜叉个个口吐火，搜天刮地走不疲。","吹风放火烈山谷，不问杉柏樗栎兰艾蒿芷蘅茅茨，燔焱熨灼无馀遗。","搜到九万九千九百九十九仞幽谷底，捉住两鬼，眼睛光活如琉璃。","养在剑丝铁栅内，衣以文采食以麋。","莫教突出笼络外，踏折地轴倾天维。","两鬼亦自相顾笑，但得不寒不馁长乐无忧悲。","自可等待天帝息怒解猜惑，依旧天上作伴同游戏。"]},{"t":"艾如张","f":"古风","c":["有菀者林，众鸟萃之。","我欲张罗，榛楛翳之。","既砺我斧，又饬我徒。","孰是奥秽，而不剪除。","爰升于虚，以相乃麓。","有条我纲，载秩我目。","有鸟有鸟，五采其章。","??喈喈，率彼高冈。","张之弗获，忧心且伤。","寤寐怀思，曷云能忘。","有鸟五采，亦既来止。","昭其德音，以相君子。","君子岂弟，其仪是若。","艾而张矣，云胡不乐！"]},{"t":"芳树","f":"古风","c":["蔚彼芳树，生于兰池。","景风昼拂，荣泉夜滋。","烨如其光，炫于朱曦。","含华吐芬，嘤鸣满枝。","君子有酒，以遨以嬉。","羽觞交横，吹竹弹丝。","相彼草木，允惟厥时。","良辰易徂，能不怀思。","沛其迈矣，其谁女悲？"]},{"t":"上陵","f":"古风","c":["零雨霏霏，亦降于桑。","怆悢中怀，念昔先皇。","惟昔先皇，创业孔艰。","寤寐兴怀，能不永叹。","精灵安所，体魄焉依？","幽明隔绝，曷巳其思。","堂堂梓宫，在彼高冈。","霜露是萃，能不慨伤。","礼起由情，将情繄物。","溥斯索矣，庶其罔阙。","郊社既虔，宗庙孔威。","上陵是申，式昭孝思。"]},{"t":"将进酒","f":"古风","c":["有酒湛湛，亦盈于觞。","酌言进之，思心洋洋。","亦有兄弟，在天一方。","安得致之，乐以徜徉。","有酒在尊，既旨且清。","何以酌之，有觓其觥。","岂不欲饮，惜无友生。","怆悢伤怀，曷云其平。","兄弟之合，如埙如篪。","朋友既比，如纲如维。","死丧急难，是责是庇。","今日有酒，如何勿思。","人亦有言，解忧惟酒。","载惛载呶，亦孔之咎。","我觞维琼，我斝维玖。","以乐兄弟，以宴朋友。"]},{"t":"巫山高","f":"古风","c":["巫山高哉郁崔嵬，下有江汉浮天回。","深林日月照不到，洞谷阖辟生风雷。","危峰半出赤道上，落日猿狖鸣声哀。","虎牙赤甲斗雄壮，风气以之而隔阂。","楚王遗迹安在哉？","但见麋鹿跳蒿莱。","当时忠臣放泽畔，乃与靳尚相徘徊。","山中妖狐老不死，化作妇女莲花腮。","潜形谲迹托梦寐，变幻涕泪成琼瑰。","神灵震怒不可祷，云雾惨淡昏阳台。","猛风吹雨洗不尽，假手秦炬歊飞灰。","精诚感应各以类，世间妖孽匪自来。","君不见商王梦中得良弼，傅岩之美今安匹。","巫山何事近楚宫，终古怨恨流无穷。"]},{"t":"战城南","f":"古风","c":["朝战城南门，暮战城北郭。","杀气高冲白日昏，剑光直射旄头落。","圣人以五服限夷夏，射猎耕织各自安土风。","胡为彼狂不自顾，而与大国争长雄？","高帝定天下，遗此平城忧。","陛下宵旰不遑食，拥旄仗钺臣不羞。","登南城，望北土。","云茫茫，土膴膴，蚩尤祃牙雷击鼓。","举长戟，挥天狼。","休屠日逐浑邪王，毡车尾尾连马羊。","橐驼载金人，照耀红日光，逍遥而来归帝乡。","归帝乡，乐熙熙，际天所覆罔不来。","小臣献凯未央殿，陛下垂拱安无为。"]},{"t":"思悲翁","f":"五言古诗","c":["弱龄轻日月，迈景想神仙。","顾往谅无及，待来徒自怜。","黄金弃砂砾，劬心鍊丹铅。","凿石不得水，沉剑徒窥渊。","流光不我与，白发盈华颠。","杖策出门去，十步九不前。","归来对妻子，尘灶午未烟。","干时乏计策，退耕无园田。","霜蒲怨青松，逝矢恨惊弦。","巳矣复何道，吞声赴黄泉。"]},{"t":"圣人出","f":"古风","c":["圣人出，临万方，赤若白日登扶桑。","阴灵韬精星灭芒，群氛辟易归大荒。","晻暧寒谷熙春阳，枯根发茁畅幽藏。","潜鱼跃波谷鸟翔，花明草暖青天长。","青天长，圣人寿，北斗轩辕调气候。","北辰中居环列宿，八风应律九歌奏，圆方交格神灵辏。","圣人出，阳道开。","亿万年，歌康哉。"]},{"t":"钓竿","f":"古风","c":["斫竹作钓竿，抽茧作钓丝。","沧洲日暖波涟漪，绿蒲茸茸柳叶垂，钩纤饵香鱼不知。","石鳞激水溪毛动，玉燕回翔竿尾重。","大鱼入馔腮颊红，小鱼却放渊沄中。","更祝小鱼知我意，长逝深潭莫贪饵。"]},{"t":"思美人","f":"古风","c":["雨欲来，风萧萧。","披桂枝，拂陵苕。","繁英陨，鲜叶飘。","扬烟埃，靡招摇。","激房帷，发绮绡。","中发肤，憯寂寥。","思美人，隔青霄。","水渺茫，山岧峣。","云中鸟，何翛翛。","欲寄书，天路遥。","东逝川，不可邀。","芳兰花，日夜凋。","掩瑶琴，闲玉箫。","魂睘睘，心摇摇。","望明月，歌且谣。","聊逍遥，永今宵。"]},{"t":"楚妃叹","f":"七言古诗","c":["江汉扬波六千里，上有巫山矗天起。","锦衾一夕梦行云，万户千门冷如水。","闻道秦兵下武关，君王留连犹未还。","山深不见章台殿，汨罗冤泪空潺湲。","尚忆前王好驰逐，宫中美人不食肉。","回狂作哲须臾间，至今相业归孙叔。","楚宫无复如昔人，况有神女如花新。","悲来恨新还忆故，谁能断却巫山路？"]},{"t":"王子乔","f":"古风","c":["王子乔，乃是髭王之子，皇王之孙。","深宫洞房不称意，却驾白鹤寻轩辕。","虹蜺为旆云为幡，飘然乘风上昆崙。","王子乔，去何之？","朝发旸谷暮崦嵫，六龙九凤相追随。","穆王西上不得王母诀，胡为元气独尔私？","王子乔，去不还。","后稷功业委如山，犹有九鼎知神奸。","王城日夕生茆菅，尔独胡为白云间？","王子乔，空长叹！"]},{"t":"走马引","f":"古风","c":["天冥冥，云濛濛，当天白日中贯虹。","壮士拔剑出门去，手提仇头掷草中。","掷草中，血漉漉，追兵夜至深谷伏。","精诚感天天心哀，太一乃遣天马从天来，挥霍雷电扬风埃。","壮士呼，天马驰，横行白昼，吏不敢窥。","戴天之耻自古有必报，天地亦与相扶持。","夫差徒能不忘而报越，栖于会稽又纵之。","始知壮士独无愧，鲁庄嵇绍何以为人为！"]},{"t":"梁甫吟","f":"古风","c":["谁谓秋月明，蔽之不必一尺翳。","谁谓江水清，淆之不必一斗泥。","人情旦暮有翻覆，平地倏忽成山溪。","君不见桓公相仲父，竖刁终乱齐，秦穆信逢孙，遂违百里奚。","赤符天子明见万里外，乃以薏苡为文犀。","停婚仆碑何震怒，青天白日生虹蜺。","明良际会有如此，而况童角不辨粟与稊。","外间皇父中艳妻，马角突兀连牝鸡。","以聪为聋狂作圣，颠倒衣裳行蒺藜。","屈原怀沙子胥弃，魑魅叫啸风凄凄。","梁甫吟，悲以悽。","岐山竹实日稀少，凤皇憔悴将安栖？"]},{"t":"墙上难为趋行","f":"古风","c":["弱水不可以航，石林不可以车。","人生贵守分，墙上难为趋。","茫茫八极内，狭径交通衢。","纷纷皆辙迹，扰扰论锱铢。","焦原诧齐踵，龙颔夸探珠。","片言取卿相，杯酒兴剪屠。","机事一朝露，妻子化为鱼。","林间有一士，蓬蒿翳穷庐。","种稻十数亩，种桑八九株。","有酒且饮之，无事即安居。","孰知五鼎食，聊保百年躯。","悠悠身后事，汲汲复何如。"]},{"t":"少年行","f":"五言古诗","c":["骏马狐白裘，玉勒黄金羁。","宾从如浮云，顾盼生光辉。","朝驱紫陌尘，暮醉青楼姬。","但见花月好，宁知霜雪飞。","荏苒世途异，凄凉瑶草衰。","园田皆易主，亲友尽暌违。","学书时既晚，躬稼力巳微。","岁晏寒风生，倚墙听邻机。","逝水不可挽，枯蓬安所依。","伫立为尔叹，感我泪沾衣。"]},{"t":"独漉篇","f":"古风","c":["独漉复独漉，月明江水浊。","水浊迷龙鱼，月明复何如。","楚国皆浊，屈原独清。","行吟泽畔，哀哉不平。","上山采荼，下山采蘖。","心在腹中，何由可白？","豺狼在后，虎豹在前。","四顾无人，魂飞上天。","珠玉委弃，不如泥沙。","蹑冠戴履，万古悲嗟。"]},{"t":"懊憹歌 其一","f":"五言绝句","c":["白鸦养雏时，夜夜啼达曙。","如何羽翼成，各自东西去。"]},{"t":"懊憹歌 其二","f":"五言绝句","c":["昨夜霜风起，入户复吹帷。","儿啼母心酸，母愁儿不知。"]},{"t":"懊憹歌 其三","f":"五言绝句","c":["养儿图养老，无儿生烦恼。","临老不见儿，不如无儿好。"]},{"t":"懊憹歌 其四","f":"五言绝句","c":["食蘖苦在口，食莲苦在心。","苦心无人知，苦口泪沾襟。"]},{"t":"懊憹歌 其五","f":"五言绝句","c":["男儿初生时，蓬矢桑弧弓。","老大却思家，懊恼无终穷。"]},{"t":"君子有所思","f":"五言古诗","c":["晨上龙首山，徘徊望咸京。","交衢错万井，甲第连公卿。","鞍马相照曜，冠盖如云行。","扈从金宫归，赐酒银瓮盈。","前庭列驺骑，后苑罗倾城。","宠极妒心起，欢馀骄气生。","田窦巧相夺，萧韩互摧倾。","快意在一时，报复延戈兵。","范雎掉柔舌，穰侯去彊嬴。","宁知幽燕客，接踵夸雄鸣。","茫茫前车辙，遗迹犹未平。","胡为不自悟，坐使忧患并。","二疏独何人，千载垂令名？"]},{"t":"上山采蘼芜","f":"五言古诗","c":["上山采蘼芜，山峻路迢递。","下山逄故夫，悲风生罗袂。","忆昔结发时，愿得终百年。","变故不可期，中道相弃捐。","莲实生水中，石榴生路侧。","未尝挂齿牙，中心岂能识。","上山采蘼芜，罗袖生芳菲。","因君赠新人，莫遣秋霜霏。","落叶辞故枝，不寄别条上。","白日无回光，谁能不惆怅。"]},{"t":"双桐生空井","f":"五言律诗","c":["双桐生空井，井空桐叶稀。","叶稀不自蔽，凤鸟将安归。","双桐生空井，井泥泉不出。","桐根日夜枯，何由伐琴瑟。"]},{"t":"玉阶怨","f":"五言绝句","c":["长门灯下泪，滴作玉阶苔。","年年傍春雨，一上苑墙来。"]},{"t":"秋思","f":"五言绝句","c":["梧桐生碧砌，密叶暗金井。","惊心昨夜月，照见栖禽影。"]},{"t":"长门怨","f":"五言绝句","c":["白露下玉除，风清月如练。","坐看池上萤，飞入昭阳殿。"]},{"t":"长相思","f":"古风","c":["长相思，在沅湘，九疑之山郁苍苍。","青天荡荡林木暗，落日虎啸风飞扬，欲往从之水无航。","仲尼有德而不用，孟轲竟死于齐梁。","松柏摧折桂生蠹，但见荆棘如山长。","长相思，断人肠。"]},{"t":"大墙上蒿行","f":"古风","c":["墙上蒿，方春擢秀何芃芃。","炎天六月旱无雨，枝叶枯死随飘风。","世情翻覆不可拟，人生有身莫依倚。","君不见樊将军，一朝函首西入秦。","又不见刘越石，仰天长歌握中璧。","三士自残因二桃，子胥终弃吴江涛。","世人见机苦不蚤，何不看取墙上蒿。"]},{"t":"鸡鸣曲","f":"古风","c":["日将出，鸡先鸣，千门万户听鸡声。","美人锦帐愁欲曙，壮士苦心煎百虑。","人间百年能几日，日日鸡鸣催日出。","一朝过了复一朝，白发萧萧此生毕。","齐妃播淑德，感彼虫薨薨。","周宣悟姜后，功业光中兴。","亦知国家共如此，莫怪鸡鸣催早起。"]},{"t":"邯郸才人嫁为厮养卒妇","f":"古风","c":["邯郸有才人，艳色如朝霞。","嫁作厮养妇，云鬓埋泥沙。","忆昔赵王全盛日，夜夜绮筵张宝瑟。","中山美酒盈羽觞，一笑黄金满千镒。","繁华过眼如转蓬，故宫禾黍秋芃芃。","明珠白璧走函谷，坠簪遗珥空悲风。","人生最苦是衰老，白首无归向谁道。","荜门夜永月光寒，卧听驽骀龁枯草。"]},{"t":"孤儿行","f":"七言古诗","c":["蓬头皲足谁家儿，满面尘埃双泪垂。","爷娘弃我不待老，骨肉无人但兄嫂。","两身一气不相知，陌路茫茫向谁道。","清晨采薪日入归，残羹冷饭难充饥。","欲言问兄兄不顾，嫂是他人更奚诉。","人生一世为弟兄，同根自合同枯荣。","爷娘在日曾眷恋，愿兄回看死人面。"]},{"t":"病妇行","f":"古风","c":["夫妻结发期百年，何言中路相弃捐。","小儿未识死别苦，哑哑向人犹索乳。","箱中探出黄金珥，付与孤儿买?饵。","不辞瞑目归黄泥，泉下常闻儿夜啼。","低声语郎情不了，愿郎早娶怜儿小。"]},{"t":"淮南王","f":"古风","c":["淮南王，好神仙。","澄心鍊气守自然，收拾真一归中圆。","化为五色黄金丸，乘风驾景飞上天。","飞上天，逍遥游，八鸾捧毂龙翼辀。","虹蜺演纷夹綵斿，上窥九阳下六幽。","回头大笑武皇帝，柏梁桂馆空清秋。"]},{"t":"东飞伯劳歌","f":"七言律诗","c":["南飞鹧鸪北飞鹄，黄昏鸣鸡白日烛。","珊瑚石上栽兔丝，鸳鸯独宿枯桑枝。","永夜凉蟾入罗幕，蝉翼不如秋鬓薄。","寒塘露莲千叶红，可怜零露空随风。"]},{"t":"双燕离","f":"五言古诗","c":["双燕营巢时，双飞复双语。","轻盈柳陌风，振迅芹塘雨。","巢成近绣帏，双宿更双飞。","为蒙主人爱，不信有暌违。","四月温风起，榴花发红蕊。","拾虫还哺雏，出入无停觜。","五月教雏飞，绕巢舞乌衣。","侧避蛛丝过，斜萦柳线归。","六月雏翼老，分飞各相保。","脉脉傍珠帘，依依集兰橑。","世事有转旋，陵谷一朝迁。","昆明延劫火，甲第化歊烟。","带睡惊飞出，风沙两相失。","死生不得知，嬿婉从兹毕。","回看旧主人，粉黛成灰尘。","天高云渺渺，海阔波鳞鳞。","荏苒朝还暮，茕茕向何处。","毛凋半夜霜，泪滴三春露。","露寒霜又浓，憔悴不成容。","同心谅难隔，魂魄终相从。"]},{"t":"远如期","f":"古风","c":["远如期，近别尚云可，远期能不悲？","忆昔辞君出门去，手种庭前松柏树。","树今成器人未归，洞房白发秋霏霏。","高原有梧隰有槚，待君北邙山石下。"]},{"t":"大堤曲","f":"古风","c":["大堤女儿颜如花，大堤堤上无豪家。","东家女作西家妇，夫能棹船女沽酒。","春去秋来年复年，生歌死哭长相守。","君不见襄阳女儿嫁荆州，撞钟击鼓烹肥牛。","楼船一去无回日，红泪空随江水流。"]},{"t":"白苧词 其一","f":"古风","c":["铿华钟，伐灵鼓，青娥弹丝白苧舞。","文竿迎风雉振羽，长袖奋迅若云举。","博山雾合春濛濛，玉缸摇火生长虹，翠荡红翻如梦中。"]},{"t":"白苧词 其二","f":"七言古诗","c":["暖香结暝娇青春，翠钗珠压光照人。","凤箫十二烟雾匀，鸿惊燕娇波龙鳞。","玉觞交飞酒如沼，门外斜阳在林杪，宫中沉沉天未晓。"]},{"t":"钧天乐","f":"楚辞体","c":["君不见天穆之山二千仞，天帝所以觞百灵。","三嫔不下两龙去，九歌九辩归杳冥。","我忽乘云梦轻举，身骑二虹臂六羽。","指挥开明辟帝关，环佩泠泠曳风雨。","明月照我足，倒影摇云端。","参差紫鸾笙，响震瑶台寒。","我欲听之未敢前，空中接引皆神仙。","烟挥雾霍不可测，翠葩金叶光相射。","鲸钟虎簴铿鸿濛，撼昆崙兮殷崆峒。","扬天桴兮伐河鼓，咸池波兮析木风。","遂升泰阶朝玉帝，侧身俯伏当琼陛。","讯曰太极拆裂为乾坤，纷纷枝叶皆同根。","胡为妄生水火金木土，自使激搏相熬煎？","臣闻三皇前，群物咸熙熙，众子戴一父，皞皞无偏私。","忽然元气自荡潏，变换白黑分贤痴。","蚩尤与黄帝，从此兴戈矛。","流毒万万古，争夺无时休。","骨肉自残贼，帝心至仁能不忧？","帝不答，臣心迷。","风师咆哮虎豹怒，银汉汹涌天鸡啼。","飙轮撇捩三岛过，海水尽是青玻璃。","神奔鬼怪惕惊起，遗音沨沨犹在耳。","梦耶游耶不可知，但见愁云漠漠横九疑。"]},{"t":"从军五更转 其一","f":"五言绝句","c":["一更戍鼓鸣，市上断人声。","风吹鸿雁过，忆弟复思兄。"]},{"t":"从军五更转 其二","f":"五言绝句","c":["二更月上城，照见兜鍪光。","侧身望山川，泪落百千行。"]},{"t":"从军五更转 其三","f":"五言绝句","c":["三更悲风起，树上乌鹊鸣。","枕戈不能眠，荷戈绕城行。"]},{"t":"从军五更转 其四","f":"五言绝句","c":["四更城上寒，刁斗鸣不歇。","披衣出户视，太白光如月。"]},{"t":"从军五更转 其五","f":"五言绝句","c":["五更星斗稀，霜叶光烂烂。","健儿争先起，拂拭宝刀看。"]},{"t":"前有尊酒行","f":"古风","c":["前有尊酒芳以饴，举杯欲饮且置之。","丈夫有志可帅气，胡为受此曲糵欺？","禹恶旨酒，而玄德上达。","桀作酒池，而南巢是蔡。","商辛恶来以白日为夜，糟丘肉林相枕藉。","瑶台倏忽成灰尘，流毒犹且迁殷民。","夫差酗而纳施，楚国酣而放屈。","姑苏台上麋鹿游，鄢郢宫中狐兔出。","灌夫骂坐，祸延魏其。","竹林称贤，神州蒺藜。","亡家破国有如此，酒有何好而嗜之！","前有尊酒醲以清，酌之白日成晦冥。","眼花耳热乱言语，元气耗斁肝胆倾。","乃知酒是丧身物，卫武之戒所以垂休声。"]},{"t":"隔谷歌","f":"古风","c":["战鼓咽悲风，弓折不可把。","弟兄隔谷不相闻，咫尺人间与泉下。","丈夫誓许国，杀身非所怜。","两心本一气，何能坐相捐。","登埤四顾望，慨慷肝胆裂。","不见救兵来，但见绕城铁甲光如雪。","飞禽在罗网，尚或念其饥。","身为高官马食粟，忍见手足居重围？","相彼鸿与雁，亦各顾匹俦。","挽弓射一猿，群猿拔箭声啾啾。","鸟兽且有情，人心独何尤。","呜呼，田家紫荆虽微木，不忍听君歌隔谷。"]},{"t":"气出唱","f":"古风","c":["今日不乐，振策远游。","东上泰山，巍何脩脩。","道逢仙人，要我同仇。","蒸霞为粮，烹玉为羞。","玄英素蕤，光华蔓流。","日观菡萏，葩华九州。","令我从之，身轻若浮。","道以五鸾，翼以两虬。","朝翔玄圃，夕止蓬丘。","谒见王母，云眉月眸。","青娥三千，或舞或讴。","风吹琅玕，声如鸣球。","杂花并开，莫知春秋。","洪崖先生，劝我此留。","自揣凡骨，非仙者俦。","七情交煎，一触百抽。","又病戆僻，无药可瘳。","崇崇清宫，荡无涯陬。","列仙如沙，不少一沤。","王母笑听，拜谢扣头。","归来山林，曷标曷钩。","熙熙泰和，长乐无忧。"]},{"t":"班婕妤","f":"七言律诗","c":["昭阳秋清月如练，笙歌嘈嘈夜开宴。","长信宫中辞辇人，独倚西风咏纨扇。","倾城自古有褒妲，红颜失宠何须怨。","泠泠玉漏掩重门，一点金釭照书卷。"]},{"t":"短歌行","f":"七言古诗","c":["凉风西来天气清，云飞水落山峥嵘。","发肤剥削棱骨生，鲜芳烟悒成枯茎。","百虫哀号百窍鸣，凡有形色皆不平。","成之孔艰坏厥轻，羁人含愁起夜行。","列星满天河汉横，繁思攒心剧五兵。","天高何由达其情，归来托梦通精诚。"]},{"t":"燕歌行","f":"七言古诗","c":["霜飞动地燕草凋，沙飞石走天萧条。","江河倒影陵谷摇，白日惨淡昼为宵。","美人迢迢隔云霄，青冥无梯海无桥。","鱼枯雁死星芒消，沉沉思君不自憀。","愁如惊风鼓春潮，岁云暮矣山寂寥，梧桐叶落空乾条。","昆崙层城阻且辽，苍梧九疑烟雾遥。","琼田瑶草芟刍荛，江蓠泽兰成艾萧。","登高望远肝肺焦，安得羽翼抟长飙？"]},{"t":"苦哉行","f":"古风","c":["鸡不可使守门，狗不可使司晨。","驱车梁弱水，日暮空悲辛。","我欲乘风谒阊阖，虹蜺弥天云雾合。","九关虎豹森骇人，长跪陈辞阍不荅。","错石作玙璠，鬼神惊见欺。","截梁为欂栌，般垂拊膺泪交颐。","冲风结玄冰，道恶不可履。","巫咸上天去，泽冻神蓍死。","我欲竟此曲，此曲多苦声。","鸿雁向天北，因之寄遐情。"]},{"t":"起夜来","f":"七言律诗","c":["微月就没银河烂，城乌哑哑夜将半。","忧愁不寐揽衣起，仰看明星坐待旦。","威弧历落连天狼，两旗欲动风不扬。","槐根王侯梦未觉，岂知鸡声堪断肠。"]},{"t":"无愁果有愁曲","f":"古风","c":["君不见陈家天子春茫茫，后庭玉树凝冷光。","楼船江上走龙阵，宫中只报平安信。","酒波滟滟蒸粉香，暖翠烘烟妒娇鬓。","无愁老夫貂鼠裘，降旗摇动台城秋。","生绡束缚槛车去，始信人间果有愁。"]},{"t":"放歌行","f":"五言古诗","c":["鸿鹄抟紫霄，鹁鸠守苞桑。","岂惟异所志，羽翼有短长。","玄阴变白昼，闇虚侵太阳。","一鹿走中原，熊虎竞腾骧。","植竿成垒壁，举袂为搀枪。","叱咤倒江河，蹴蹋摧山冈。","犬牙据险要，瓜瓣割土疆。","六奇誇曲逆，三略称子房。","磨牙各有伺，裂眦遥相望。","龙蛇未分明，智力正争强。","孔明鱼得水，毛遂锥脱囊。","雾晦豹始变，海激鹏乃翔。","嗟尔独何为，抱己自摧藏。"]},{"t":"艳歌行","f":"五言古诗","c":["亭亭松柏树，结根幽涧隈。","高标拂云日，直干排风雷。","曾经匠石顾，谓是梁栋材。","明堂未构架，厚地深栽培。","荧星入天阙，武库一朝灾。","搜求到栎朴，谷赤山城垓。","般尔死无人，钩绳付舆台。","路阻莫自致，弃之于草莱。","天寒斧斤集，岁莫空摧颓。","三光无偏照，四气有还回。","斲丧在须臾，成长何艰哉。","孰知真宰意，怅望使心哀。"]},{"t":"门有车马客行","f":"五言古诗","c":["门有车马客，云是故乡人。","执手前借问，乡语知情真。","自云别故乡，观光京国尘。","经商涉代北，薄宦往西秦。","绣凤锦鸳鸯，金鞍紫骐驎。","结交贵公卿，出入拥众宾。","剧孟气方锐，郭解家不贫。","但见三春花，宁思秋露晨。","断蓬失其根，风沙歘漂沦。","前途塞虎狼，故里荒荆榛。","昔为横海鲸，今为涸辙鳞。","话言未及竟，涕泪各盈巾。","居家倚骨肉，出家倚交亲。","何当在异县，见此旧里邻。","园蔬如蜜甘，市酒若醴醇。","悲欢且弃置，生死同苦辛。","短歌有深情，情深难具陈。"]},{"t":"煌煌京洛行","f":"五言古诗","c":["齐讴且辍唱，吴趍亦停声。","请君倾耳听，听我歌洛京。","京洛何煌煌，卜宅自周王。","五服画九州，兹惟土中央。","用文四战地，恃德不恃强。","叔世道虽微，灵源泻流长。","汉祖殪秦项，定都由子房。","马上得天下，继周焉敢当。","光武起白水，龙飞扫搀抢。","应天顺民心，戡暴安痍伤。","冕旒正宸极，圭组崇俊良。","功臣列爵土，循吏劝耕桑。","诏书报臧马，玉关闭西羌。","周严播高风，卓鲁树甘棠。","廷无乳虎伏，邑有驯雉翔。","涓涓醴泉液，烨烨朱草芳。","继体更贤能，守成不踰常。","南郊尊上帝，宗祀亲明堂。","辟雍养耆德，灵台观祲祥。","南宫画元勋，东观昭文章。","诗书母后训，淫侈蕃封防。","百年天再辟，四帝日重光。","倾昃自满盈，宴安生怠荒。","刑官窃威柄，义士死道旁。","衅积千里草，祸成一星黄。","大命始不挚，馀晖尚悠扬。","典午亦有初，言治称太康。","用人混哲否，孽芽出萧墙。","兄弟相啖食，同气成豺狼。","金墉岂不固，清谈漫洋洋。","妖星入太极，胡雏登御床。","铜驼荆棘没，寝庙狐狸藏。","落日照西城，寒云归北邙。","轘辕无人行，伊洛广且长。","衰荣若旦暮，道德信金汤。","殷勤京洛篇，厥鉴不可忘。"]},{"t":"静夜思","f":"古风","c":["静夜思，一思肠百转。","啼螀当户听不闻，明月在庭看不见。","方将入海剸猛蛟，复欲度岭邀飞猱。","胸中倏忽乱忧喜，得丧纷纷竟何是。","静夜思，思无穷。","天鸡一声海日红，满头白发吹秋风。"]},{"t":"冬暖行","f":"古风","c":["孟冬十月暖，桃李花盛开。","胡蝶草间出，飞上花枝来。","蝶知爱花为花出，不知冬暖无多日。","霜风一夕花作尘，坠粉飘黄愁杀人。"]},{"t":"节妇吟","f":"古风","c":["凄切复凄切，绿萍初生池水竭。","兰根压霜芽不茁，春风泠泠逐秋月。","蓼虫食苦甘如酒，卷葹虽生心巳朽。","扬州青镜蚀土花，玉匣琼台复何有？","君不见人间日月如飞梭，地下相从应始多。"]},{"t":"登高丘而望远海","f":"古风","c":["登高丘，望远海。","长风簸浪高于山，蓬莱宫阙无光采。","云雾翳阳谷，羲和安所之？","鲸鲵作队行，鳞鬣如朱旗。","精卫衔石空有心，口角流血天不知。","登高丘，望远海。","弱水浩荡不可航，一望令人玄发改。"]},{"t":"江上曲","f":"七言绝句","c":["江上风吹沙石走，江中涛浪如牛吼。","鄂君绣被寒无香，江水不如残夜长。"]},{"t":"薤露歌","f":"五言古诗","c":["蜀琴且勿弹，齐竽且莫吹。","四筵并寂听，听我薤露诗。","昨日七尺躯，今日为死尸。","亲戚空满堂，魂气安所之。","金玉素所爱，弃捐箧笥中。","佩服素所爱，凄凉挂悲风。","妻妾素所爱，洒泪空房栊。","宾客素所爱，分散各西东。","雠者自相快，亲者自相悲。","有耳不复闻，有目不复窥。","譬彼烛上火，一灭无光辉。","譬彼空中云，散去绝馀姿。","人生无百岁，百岁复如何。","谁能将两手，挽彼东逝波。","古来英雄士，俱巳归山阿。","有酒且尽欢，听我薤露歌。"]},{"t":"莲塘曲","f":"五言绝句","c":["落日下莲塘，轻舟赴晚凉。","偶然花片落，飞出两鸳鸯。"]},{"t":"蒿里曲 其一","f":"七言绝句","c":["涧草萋萋泉汩汩，紫兰香老棠梨发。","山中无人松柏寒，卧听狐狸啸明月。"]},{"t":"蒿里曲 其二","f":"七言绝句","c":["白杨树头风恻恻，寡乌悲啼山月黑。","殡宫冷落清夜长，银鸭金凫不堪食。"]},{"t":"蒿里曲 其三","f":"七言绝句","c":["山花冥冥啼子规，鸟衔纸钱挂花枝。","山中游人莫相笑，君到此中当自知。"]},{"t":"古镜词","f":"七言古诗","c":["百鍊青铜曾照胆，千年土蚀萍花黡。","想得玄宫初闭时，金精夜哭黄鸟悲。","鱼灯引魂开地府，夜夜晶光射幽户。","盘龙隐见自有神，神物岂肯长湮沦。","愿借蟾蜍骑入月，将与嫦娥照华发。"]},{"t":"远游篇","f":"五言古诗","c":["三山六鳌背，翠水扶桑东。","鸡鸣上海日，海面玻瓈红。","仙人骑鸾凤，呼我游云中。","云中有金阙，谓是天帝宫。","明星列两藩，琪树光玲珑。","太一坐端门，白发映青瞳。","授我玉篆文，赤蛇蟠九虹。","出入元化先，寿命齐老童。","因逢青鸟使，遂造东王公。","素女如莲华，歌喉弦管同。","顾盼动环佩，振迅若轻鸿。","化为五色光，倏然随长风。"]},{"t":"神祠曲","f":"七言古诗","c":["路傍古庙壁半斜，雨滴香案堆坭沙。","槎牙死树当道卧，树上纸钱犹未化。","春秋祭祀知几时，乌鸦得食号相随。","人人欢喜得好珓，低昂拜跪山花飞。","宁知祸发在旦夕，空村无烟唯瓦砾。","庙傍乌鸦亦不来，独留土偶眠苍苔。"]},{"t":"巴陵女子行","f":"古风","c":["巴陵女子天下奇，石作心肝冰作脾。","生平见义不见巳，抆泪恨杀襄阳儿。","临终裂素写怨语，生气犹能起风雨。","君不见虎符系颈东海樯，令人愧死巴陵女。"]},{"t":"秦女休行","f":"古风","c":["秦家女儿美且都，齿如编贝唇如朱。","有生不幸遭乱世，弱肉强食官无诛。","兄朝出门暮不返，家人怅望空倚闾。","女休闻之肝胆裂，奋臂不惜千金躯。","援矛一掷白日撼，仇血上溅天模糊。","市人惊噪尘土沸，逻卒奔走驰金吾。","有心杀人宁惜死，顾谓女吏何其愚。","嫚法长奸谁所致，舍生得义吾何逋。","精诚通天天为恻，赦书一夕来宸极。","路旁观者咸叹嗟，女休出门无喜色。","君不见景升本初之子空是男，亡家破国令人惭。"]},{"t":"闺词 其一","f":"五言绝句","c":["戎马关山隔，空闺鬓发华。","将何寄消息，江树总无花。"]},{"t":"闺词 其四","f":"五言绝句","c":["剔却灯花蕊，从教污翠钿。","几回虚报喜，误妾不成眠。"]},{"t":"上云乐","f":"古风","c":["混沌结，玄黄开，人生其中，称为三才。","一人身有一天地，形质虽异众理该。","欲淫物诱滋巧伪，遂使真淳耗斁玄风颓。","乃有朝生而暮死者，本根浅短无栽培。","惟有西天老胡名文康，自从盘古到今日，不老不少，气体充实如婴孩。","性情和易颜色好，恰似初酿匐萄醅。","激之而不见其怒，挠之而不见其咍，甘之而不见其喜，苦之而不见其款。","所以于物无所忤，于人无所猜，于事无所碍，于艺无所能。","不生不死在人世，借问老胡何修得此哉？","老胡答言我亦不自解，请说伏羲神农皇帝在日一二事，不知得失汝自挨。","伏羲始画八八六十有四卦，罗天网地括五材。","老胡不识单与耦，谓是乌曹重叠堆砖坯。","仓颉制文字，鬼母夜哭声哀哀。","老胡不识点与画，谓是蜗牛之泪萦莓苔。","容成隶首造历数，上收坤灵之精爽，下掇乾象之根荄。","大挠作甲子，编户星宿来当差。","老胡不识一二三四五，但见暖则出，寒则伏，一似虫豸听命霜与雷。","羲和常仪占日月，拘束乌飞兔走、翼足相排挼。","鬼臾区占星气，指斥王蓬絮，周伯老子、无所藏匿其祥灾。","老胡不识金木水火土，但见昊天森列众光怪，大者如缶小者如杯。","伶伦截竹作律吕，中间实以葭莩灰。","玄问老鬼二十四，俯首受命同舆佁。","又用子谷秬黍起度量，教得蠢动狡猾而不呆。","老胡不识轻重长短多与寡，但觉饥则食，饱则止，明则起，暗则卧，有力即往倦即回。","轩辕黄帝与岐伯，口尝毒药一日生死八九遍，皮肉黑瘦生烟煤。","老胡但见颜色差异即不吃，牙齿牢，硬无龇。","九天玄女说兵法，风云鸟蛇掌上排。","教人斗阋逞雄杰，致使阪泉涿鹿之野，它它藉藉撑枯骸。","尔时众贤圣，尾尾相继轰轳濆。","雕肝琢肾镂心肺，倾泻精髓通脊脢。","攘攘扰扰竞神知，虚名不朽身先隤。","惟有老胡混沌无孔窍，不与人世分仇侪。","尧舜相传授，四海玉烛无氛埃。","老胡随众歌击壤，帝力于我何有哉？","汤武行放伐，鹰化为雀驹为裛。","龙逢被杀夷叔饿，何如老胡终日瞑坐山之隈。","五伯与七国，角力争喧豗。","谋臣辨士神出而鬼没，口乾舌拔眉眼。","到头毕竟成就者，土坟三尺埋蒿莱。","老胡万事皆不理，厓厓坐得四肢百骨如乾柴。","所以天地鬼神不怪怒，容得老胡永远在世上，时复一出歌笑呈诙谐。","况遇天子圣，德泽浃九垓。","青云应吕风应律，遐方感化神民怀。","老胡再拜稽首、献天子寿，愿天子与天地相似，老胡岁岁舞蹈玉墀下，跪进玻璃杯。"]},{"t":"仙人词 其一","f":"七言绝句","c":["玉府仙人冰雪姿，生来即遣侍瑶池。","五云隔断尘凡路，说著人间总不知。"]},{"t":"仙人词 其二","f":"七言绝句","c":["上帝宸居俨肃森，九关虎豹立崟崟。","群龙自有三珠树，不见扶桑水浅深。"]},{"t":"仙人词 其三","f":"七言绝句","c":["东海鲸鲵白昼游，南溟风浪涌吞舟。","三山亦在沧波里，自是神仙未解愁。"]},{"t":"吴歌 其一","f":"七言绝句","c":["侬做春花正少年，郎做白日在青天。","白日在天光在地，百花谁不愿郎怜。"]},{"t":"吴歌 其四","f":"七言绝句","c":["蛾眉二八不曾愁，有色无媒郎不留。","月里蟾蜍推落地，几时再得广寒游。"]},{"t":"吴歌 其五","f":"七言绝句","c":["栽花图作看花人，谁料花开不及春。","昨夜狂风今夜雨，为花落得两眉颦。"]},{"t":"吴歌 其六","f":"七言绝句","c":["莫信登天不要梯，莫信筑雪可成堤。","五更老鸦树上叫，有人则道是鸡啼。"]},{"t":"吴歌 其七","f":"七言绝句","c":["树头挂网枉求虾，泥里无金空拨沙。","刺漆树边栽枸橘，几时开得牡丹花。"]},{"t":"吴歌 其八","f":"七言绝句","c":["六月栽禾未是迟，死中求活是高棋。","夕阳若有回头照，遮莫黄昏一饷时。"]},{"t":"采莲歌 其三","f":"七言绝句","c":["采得红莲爱白莲，双桡快转怕人先。","争知要紧翻成慢，菱叶中间绊却船。"]},{"t":"竹枝歌 其二","f":"七言绝句","c":["相思无益莫相思，赢得霜髯换黑髭。","明月自圆还自缺，蚌胎瘦减有谁知。"]},{"t":"竹枝歌 其五","f":"七言绝句","c":["荣华未必是荣华，园里甜瓜生苦瓜。","记得水边枯楠树，也曾发叶吐鲜花。"]},{"t":"竹枝歌 其十一","f":"七言绝句","c":["鼋鼍在水虎在山，登山入木早防闲。","别有一般真叵耐，虾蟆生在月中间。"]},{"t":"江南曲 其一","f":"七言绝句","c":["江北垂杨未爆芽，江南水绿万重花。","北人尽道江南好，江南才到便为家。"]},{"t":"江南曲 其二","f":"七言绝句","c":["金陵好是帝王州，城下秦淮水北流。","惆怅江南旧花月，女儿尽作北歌讴。"]},{"t":"江南曲 其四","f":"七言绝句","c":["钱塘胜地作南都，纨绮如云隘广途。","想得燕山风雪夜，断魂相语怨西湖。"]},{"t":"江南曲 其五","f":"七言绝句","c":["桃叶渡头春水平，莫教城上哓莺声。","中原无限英雄泪，并入江南送别情。"]},{"t":"江南曲 其七","f":"七言绝句","c":["生长吴侬不记春，乡音旋改踏京尘。","丫头小妓相偎坐，众里矜誇是北人。"]},{"t":"山鹧鸪 其四","f":"七言绝句","c":["黄茅垄上雨和泥，苦竹冈头日色低。","自是行人行不得，莫教空恨鹧鸪啼。"]},{"t":"山鹧鸪 其五","f":"七言绝句","c":["鹧鸪元是岭南音，岭北无人识此禽。","南人唱歌过岭去，北人相向泪沾襟。"]},{"t":"山鹧鸪 其六","f":"七言绝句","c":["山禽一处一般声，不是乡音便动情。","多是江南子规鸟，天津桥上对人鸣。"]},{"t":"杨柳枝词 其一","f":"七言绝句","c":["多事垂杨管送迎，长条折尽短条生。","不知几许东风里，犹带轻烟罥晚晴。"]},{"t":"宫怨 其二","f":"七言绝句","c":["何处春风拂苑墙，飞花片片入昭阳。","多情尚有池边柳，留得啼莺伴日长。"]},{"t":"秋怀 其一","f":"古风","c":["凉夜悠悠，华灯有辉。","凄风动林，明月在帷。","山川迢迢，游子无衣。","瞻彼原隰，零露溰溰。","靡草不凋，无木不稀。","不睹逝波，焉知昨非。","亭亭南山，有蕨有薇。","黄华晚荣，紫芝秋肥。","岁云莫矣，胡宁不归。"]},{"t":"秋怀 其二","f":"古风","c":["陟彼高原，望美中陵。","玄商夕振，白露宵零。","蔚彼茂草，化为枯莛。","我有素琴，玉轸朱绳。","弹为阳春，旭日满庭。","怆悢兴怀，悲来填膺。","子期逝矣，其谁汝听。"]},{"t":"秋怀 其三","f":"古风","c":["喓喓草虫，剽剽其股。","岁莫如何，尔独良苦。","瞻望日月，绵绵我愁。","如彼逝矢，一往不留。","嗟尔小子，时不再得。","匪缗曷鱼，不艺胡稷。","萧萧草虫，烈烈其音。","岁莫何为，秖觉我心。"]},{"t":"秋怀 其四","f":"古风","c":["中庭有枣，累累其实。","零露既降，岁事孔疾。","循彼阶轩，有鸣蟋蟀。","岂其觱发，而不栗烈。","南山崒嵂，松柏萧瑟。","彼兰斯莸，彼枳斯橘。","安得羽翼，载飞载鸣。","泛滥八荒，以终永日。"]},{"t":"秋怀 其五","f":"古风","c":["有爝者萤，载飞载扬。","有倬云汉，载炳其章。","白日易徂，玄夜何长。","繁思交横，浮念无方。","慨怀古人，中心怛伤。","离娄冥行，历坎而僵。","循墙以趍，虽瞽不伥。","猛虎雷咆，斑文在床。","妖狐鬼潜，毳裘黄黄。","悠悠多岐，荡荡周行。","慎尔驰驱，天命有常。"]},{"t":"秋怀 其六","f":"古风","c":["夕簟既清，瓶水既寒。","浩歌临风，忧来多端。","悬崖而栖，瞽以为安。","菅茅在门，蒙以为兰。","黍稷弗膳，腐鲍是餐。","干将挂壁，敝履加冠。","宛其悲矣，能不永叹。"]},{"t":"秋怀 其七","f":"古风","c":["郁彼晨烟，亦曼于楚。","瑟彼枯杨，策策其语。","良辰几何，亦既徂暑。","溥彼郊原，有禾有黍。","凄风夕兴，雁鹜如雨。"]},{"t":"秋怀 其八","f":"古风","c":["今日何日，岁聿其秋。","候雁北来，星火西流。","怀我故乡，道阻且脩。","俯察渊潜，仰睇天游。","孰翱匪鸢，孰跃匪虬。","瞻望日月，中心如抽。","岂无美酒，焉得良俦。","矢诗不多，聊以解忧。"]},{"t":"有鸟一首赠袁尚志","f":"古风","c":["有鸟有鸟，薄言激之。","君子至止，何以乐之。","有酒湑湑，亦盈于觞。","明月照帷，清风满堂。","我酒既旨，我仪有秩。","言念君子，温如其日。","有鸟有鸟，载好其音。","君子之洽，如瑟如琴。","有棐有翼，有劝有饬。","古训是式，大猷是九。","有栗者璧，瑕则磨之。","有紑者丝，色以讹之。","如彼织纴，君子维经。","如彼锋刃，君子为硎。","无为夸毗，无为戚施。","伊我之偾，亦子之痍。","此令朋友，交相为助。","匪中式孚，俾好作恶。","有酒在觞，有琴在堂。","酌言鼓之，心焉孔臧。","有鸟有鸟，载翾载飞。","岂弟君子，式昭令仪。","业不厌脩，学不厌多。","既酌以酒，复相以歌。"]},{"t":"擢彼乔松一首","f":"古风","c":["擢彼乔松，在彼丘阿。","岁莫凄风，飒为枯柯。","忧来伤心，云如之何。","瞻彼昊天，曷其有宜。","天降淫德，痡于下国。","稻粱黍稷，暨于螟蜮。","不稼不穑，寇攘以食。","哀此下民，曷其有极。","心之忧矣，如烹如煎。","丧乱靡底，如渊如泉。","如彼奥草，孔蔓以延。","呜呼昊天，伊谁之愆。","有罻者罿，曷施于宇。","胡罾于林，觊彼鲂鱮。","小人所怃，君子所与。","弗询弗犹，曷其有愈。","君子不畏，乱日以炽。","君子不忧，乱日以悠。","正言谔谔，謟言诺诺。","欢言孔怡，丧乱所基。","邦家维车，庶民维舆。","庶僚维服，大臣维御。","慎尔驱驰，俾险作夷。","无然汶汶，无俾车偾。","无曰予知，民各有思。","无曰予圣，庶民孔竞。","无竞维德，四方之则。","无为回遹，以纵枉慝。","瞻彼高原，翳翳其云。","眄彼大水，浩矣无津。","嗷嗷飞雁，各念尔群。","哀我人斯，胡胥以沦。","莫高匪天，莫明匪日。","何纤勿冒，何昧勿晢。","维此圣人，庶民是葵。","维彼愚人，则各有谋。","原隰之瘁，夫妇云之。","闾巷之呻，君子闻之。","弗闻弗惟，则各有思。","式谤式詈，腑肠以离。","谷斯之秕，农以为殃。","匪鹰匪隼，曷云能翔。","维天有船，不可以航。","眷言顾之，心焉恻伤。","相彼茂草，飞鸟依之。","淠彼深渊，鲂鲤归之。","靡依靡归，胡能勿悲。","我有隐忧，人莫之知。","中途有棘，庶民伐之。","执讯弗笃，君子堲之。","不瞆不聋，孰填尔聪。","靡瞻靡顾，自贻伊瞽。","如彼沸鼎，无增尔薪。","无从尔言，以逖远人。","迩人营营，远人兢兢。","弗讹尔心，曷其有惩。","嗟尔君子，戒慎尔止。","靡谦不光，靡盈不毁。","维山有杞，维泽有芷。","庶民所履，维君子使。","陟彼高原，维风飗飗。","靡草不凋，无木不刘。","忧来伤心，如焚如抽。","瞻仰昊天，曷其有瘳。"]},{"t":"感怀三十一首 其三","f":"五言古诗","c":["谁云鲁酒薄，邯郸被戈矛。","楚馆困两君，乃为马与裘。","举世共如此，太息复何尤。","振衣箕山顶，引领望许由。","终然不可见，涕泪交膺流。"]},{"t":"感怀三十一首 其四","f":"五言古诗","c":["古人盗天地，利源不可穷。","今人盗农夫，岁莫山泽空。","纷纷九衢内，连袖如长虹。","共笑沮溺鄙，各事游冶雄。","悠悠方自此，衮衮何时终。"]},{"t":"感怀三十一首 其五","f":"五言古诗","c":["啾啾草间雀，日随黄鸟飞。","争先赴稻粱，宁顾野人机。","便便善柔子，怀利近相依。","但慕春荑好，不见秋霜霏。","驱车逐走鹿，中路忘所归。","岂不爱其躬，天命与心违。","古道今巳矣，感悟空涕欷。"]},{"t":"感怀三十一首 其六","f":"五言古诗","c":["柔桑生中园，婀娜当阳春。","下滋灵泉液，上承膏露津。","美人望蚕月，倾筐竞明晨。","荣盛方及时，采捋一何频。","枯根不盈拱，何以禦霜辰。","复闻刍荛子，磨砺待为薪。","冥观成感激，踯躅含酸辛。"]},{"t":"感怀三十一首 其八","f":"五言古诗","c":["伏枕候明发，梦游沧海中。","中有万斛船，荡漾随天风。","舵师兀昏睡，环视立众工。","波涛正汹涌，欲往迷西东。","寤寐惕惊起，魂魄犹忡忡。"]},{"t":"感怀三十一首 其九","f":"五言律诗","c":["苏秦佩六印，宾从何纵横。","当时机中妇，倩笑远相迎。","黄金生意气，蚕蠋见人情。","岂无箪瓢士，今为时所轻。"]},{"t":"感怀三十一首 其十","f":"五言古诗","c":["种树当中庭，不识美与恶。","微阴未盈户，枝叶犹荏弱。","一朝根柢成，延蔓蔽楼阁。","离披引剌蚝，蒙昧喧鸟雀。","毁垣施斧斤，得丧亦相若。","万事不早谋，日暮徒骇愕。"]},{"t":"感怀三十一首 其十一","f":"五言律诗","c":["东园多桃李，擢干何交加。","春秋互递代，衰荣竞相夸。","槭槭去故物，英英发新花。","花谢叶复作，空令人叹嗟。"]},{"t":"感怀三十一首 其十二","f":"五言古诗","c":["翡翠翔江湖，亡身为毛羽。","不如道傍李，尚得滋味苦。","驱车上太行，还顾望梁甫。","高冈多烈风，茂林化为岵。","空馀涧底藤，蒙茏蔓烟雨。"]},{"t":"感怀三十一首 其十五","f":"五言古诗","c":["峨峨蓬莱山，渺渺大瀛水。","神仙有窟宅，亦在玄黄里。","大壑多惊风，不辨龙与鲤。","吹沙乘波出，汹若鲸鲵起。","阳侯贯深渊，海若汩泥滓。","马衔恣馋食，罔象潜谲诡。","谁能报王母，弱水不可履。","羲和近虞渊，日暮空巳矣。"]},{"t":"感怀三十一首 其十七","f":"五言律诗","c":["射干生曾崖，不识寒涧阴。","池鱼贯安流，宁知江海深。","殷王相版筑，垂名耀来今。","后世重阀阅，田野多呻吟。"]},{"t":"感怀三十一首 其十八","f":"五言古诗","c":["虾鱼涌姑射，月晕沧海风。","鲸鲵吐高浪，白日寒曈昽。","神仙下天阙，左右翳玉虹。","金盘荐麟脯，翠蕤拥青童。","酣歌殷溟徼，鱼鳖相噞喁。","忽然乘云去，寥落寒江空。"]},{"t":"感怀三十一首 其十九","f":"五言古诗","c":["朝登会稽山，逍遥望南讹。","禹穴巳芜没，禹功长不磨。","惆怅感往昔，沉吟发新歌。","谁言专车骨，冠弁高嵯峨。","为虺且复尔，为蛇当奈何。","天门隔虎豹，空悲涕滂沱。"]},{"t":"感怀三十一首 其二十一","f":"五言古诗","c":["芳树生丹崖，绿叶如云烟。","上枝蔽光景，下根蟠九泉。","朝凉聒众鸟，夕阴萃鸣蝉。","岂不盛容色，及此阳春年。","西风吹白露，点缀庭阶前。","繁华坐销歇，枝叶空相捐。","世情多反覆，天道有推迁。","金屋擅娇宠，长门闭神仙。","献赋亦巳晚，徒悲泪如泉。"]},{"t":"感怀三十一首 其二十二","f":"五言古诗","c":["我有绿绮琴，其材出空桑。","金徽映玉轸，音韵锵琳琅。","上弦感薰风，下弦来凤皇。","世耳不欲闻，子期今则亡。","愿持献重华，路阻川无梁。"]},{"t":"感怀三十一首 其二十三","f":"五言律诗","c":["孟轲去齐魏，贾谊之长沙。","圣贤良巳矣，吾道空咨嗟。","徒言青松枝，不如桃李花。","太息安陵子，知时为世誇。"]},{"t":"感怀三十一首 其二十四","f":"五言古诗","c":["客有持六经，翩翩西入秦。","衣冠独异状，谈舌空轮囷。","献纳竟何补，焚坑祸谁因。","昂昂采芝士，矫矫蹈海人。","龙骧九渊外，岂复叹获麟。"]},{"t":"感怀三十一首 其二十五","f":"五言古诗","c":["白璧閟顽矿，沦晦同泥沙。","朽壤生夜光，见者咸惊嗟。","君子分寂寞，小人互矜誇。","枯瘁若秋蓬，鲜艳如春华。","狂风忽簸荡，飘落归谁家。"]},{"t":"感怀三十一首 其二十七","f":"五言律诗","c":["象以齿自伐，煚以能受羁。","猛虎恃强力，而不卫其皮。","世人任巧智，天道善盈亏。","不见瑶台死，永为天下嗤。"]},{"t":"感怀三十一首 其二十九","f":"五言古诗","c":["晨登吴山上，四望长叹嗟。","借问胡叹嗟？","狭路险且邪。","子胥竭忠谏，抉目为夫差。","宰嚭善逢迎，越刃复相加。","守正累则多，从人祸亦奢。","遭逢贵明良，不尔俱泥沙。"]},{"t":"感怀三十一首 其三十","f":"五言古诗","c":["壶公下天阙，聊以观世纷。","卖药汝南市，时人俱不闻。","顾此非我徒，飘然乘白云。","方驾双虬龙，被服九霞文。","但见北邙阪，岧峣尽高坟。"]},{"t":"感怀三十一首 其三十一","f":"五言古诗","c":["种苗甫田中，其叶何离离。","上天降膏泽，溥博无偏私。","人力苟不至，不如茅与茨。","常恐嘉实晚，坐伤零露滋。","徘徊感节序，太息秋风时。"]},{"t":"咏史二十一首 其一","f":"五言古诗","c":["凯风扇朱夏，草木生清凉。","卧疾澹幽旷，白日悠且长。","散帙观古人，喟焉想虞唐。","阳春能几何，阴气多繁霜。","天道谅悠悠，人理亦茫茫。","咏歌寄深情，歌罢增慨慷。"]},{"t":"咏史二十一首 其二","f":"五言古诗","c":["神枢干元化，循环运阴阳。","善恶随气异，祸福竟何常。","朱均继尧舜，时事巳抢攘。","至人妙转移，霾曀回晶光。","祥麟踣大野，君子徒慨慷。","黄星照中原，天道遂披猖。","汗漫千百年，流潦浩滂滂。","否泰有倾覆，霖雨见朝阳。","惜无风与牧，乘时佐羲皇。","熙熙返大朴，济济垂衣裳。","鼎湖去不复，叹息空哀伤。"]},{"t":"咏史二十一首 其三","f":"五言古诗","c":["野马不豢食，疆受组与羁。","低头衡轨下，各自东西驰。","秦人任法令，斩艾尊君师。","六合始一家，恩爱巳乖离。","一旦山东客，揭竿以为旗。","叫呼骊山徒，天下响应之。","素车拜轵道，谁复为嗟咨。"]},{"t":"咏史二十一首 其四","f":"五言古诗","c":["周昌勇廷诤，子房善奇谋。","王陵抗高议，平勃终安刘。","经权两不废，道立知亦周。","煌煌东都士，节义明清秋。","孰知谗佞巧，举足触戈矛。","顾此悲世运，泫然涕交流。"]},{"t":"咏史二十一首 其五","f":"五言古诗","c":["食毒偶不死，谓言堇可餐。","堕河偶不溺，谓是天所完。","侈心不自顾，利欲纷多端。","百胜困一踬，名灭躯体残。","君子戒徼幸，小人乐灾患。","不见瑶与羽，千载遗悲酸。"]},{"t":"咏史二十一首 其六","f":"五言古诗","c":["燕昭志报复，金台求俊贤。","下齐如破竹，大耻雪九泉。","六王死灰人，安可与比肩。","奈何骄气盈，妄想彼神仙。","安期不可致，即墨火巳然。","煌煌召公业，委弃如浮烟。"]},{"t":"咏史二十一首 其七","f":"五言古诗","c":["天狗吠梁野，七雄扇妖氛。","吴徒二十万，剽若狼虎群。","鼓行破棘壁，长驱似轻云。","汉将三十六，朱旗耀天垠。","救梁不奉诏，太尉真将军。","遂令千载下，知人称孝文。","哀哉潼关战，百万徒纷纭。"]},{"t":"咏史二十一首 其八","f":"五言古诗","c":["平居观群物，纷纷争朵颐。","口舌不能胜，兵戈遂相随。","古来豪杰士，于今安所之。","大运一朝至，孰分贤与蚩。","所以四老人，去采商山芝。","清风扇六合，百世真吾师。"]},{"t":"咏史二十一首 其九","f":"五言律诗","c":["景公返雀鷇，晏子称其仁。","鳏寡既有室，长年不负薪。","焉知子玉节，遗祸逮天伦。","推恩限目见，太息此君臣。"]},{"t":"咏史二十一首 其十","f":"五言古诗","c":["田横不事汉，刎颈送咸阳。","二客既穿冢，岛中皆自戕。","虽非中庸道，要亦有耿光。","英雄久沦没，世俗但炎凉。","嗟嗟翟廷尉，慷慨令人伤。"]},{"t":"咏史二十一首 其十一","f":"五言律诗","c":["吾闻共工台，乃在昆崙北。","长蛇戴九头，利吻错戈戟。","呿呀恣啖食，抵厥成溪泽。","呜呼三仞沮，可以警贪得。"]},{"t":"咏史二十一首 其十二","f":"五言古诗","c":["四七续炎运，渐台殪狂新。","建侯首褒德，拳拳念生民。","富春有遗老，终竟不为臣。","遂令节义士，视身若埃尘。","前车屡折轴，后驾无回轮。","不有锢党禁，何由起黄巾。","为邦贵知本，明主宜书绅。"]},{"t":"咏史二十一首 其十三","f":"五言古诗","c":["建光悖祖德，封爵逮阉竖。","忠良坐荼毒，陨涕盈道路。","南巡既不返，狡窟宁久固。","功成十九侯，事巳非细故。","况闻用骨鲠，乃以浮阳疏。","中官既世袭，山阳更娇妒。","时事亦可知，君子独未寤。","美哉吴长史，衡门掩秋露。"]},{"t":"咏史二十一首 其十四","f":"五言古诗","c":["当途乱天纪，赤帝悬空名。","宁知辟掾日，祸机巳潜萌。","晋主念私劳，荀冯巧相迎。","抚床竟不寤，骨肉成鲵鲸。","好还实天道，狙诈徒人情。"]},{"t":"咏史二十一首 其十五","f":"五言律诗","c":["香饵获死鱼，重赏致死士。","自古以为训，世俗宁知此。","陈汤困刀笔，壮夫皆切齿。","如何中兴主，终竟惑薏苡。"]},{"t":"咏史二十一首 其十六","f":"五言律诗","c":["隋帝易广勇，天命以不长。","唐宗昧治恪，本支竟摧戕。","圣人有达节，变通亦何常。","禹汤不同迹，万古皆明王。"]},{"t":"咏史二十一首 其十七","f":"五言古诗","c":["永嘉昔溃乱，南渡驰五马。","长江画天堑，九庙扇灰灺。","岂无运甓人，亦有誓江者。","眢池不扬波，灵物栖旷野。","哀哀黍离泪，空向新亭洒。"]},{"t":"咏史二十一首 其十八","f":"五言古诗","c":["荜门翳蓬蒿，穷巷绝马迹。","中有抱膝人，疏粝不充食。","荣华过浮埃，敝服无愠色。","献玉鄙卞和，扣角羞宁戚。","天潢不垂云，中夜起叹息。"]},{"t":"咏史二十一首 其十九","f":"五言律诗","c":["吾爱闵仲叔，幽居翳茆茨。","应辟思济世，利禄岂其私。","进当致尧舜，退则老蒿藜。","焉能犬马豢，以为天下嗤。"]},{"t":"咏史二十一首 其二十","f":"五言古诗","c":["美人皎如玉，挟瑟升高堂。","泠泠向长风，操作孤凤凰。","曲度未终竟，玄云蔽穹苍。","走兽骇赴林，飞鸟号且翔。","高山与流水，日莫空凄凉。"]},{"t":"咏史二十一首 其二十一","f":"五言律诗","c":["夫差卧薪日，勾践尝胆时。","人生各有志，况乃身践之。","宁知姑苏鹿，巳与西施期。","空令千载下，痛恨于鸱夷。"]},{"t":"游仙九首 其一","f":"五言古诗","c":["日月如过翼，瞬息春巳秋。","何不学神仙，缥缈凌虚游。","雷霆以为舆，虹蜺以为辀。","清晨登阆风，薄暮宿不周。","长啸层城巅，濯足翠水流。","俯视八极内，扰扰飞蜉蝣。"]},{"t":"游仙九首 其二","f":"五言古诗","c":["今日何不乐，振策登高山。","深林仰无见，藤蔓阴以繁。","鼪鼯绕树啼，黄鹄空飞翻。","揽辔向西北，思欲赴昆崙。","琼楼十二重，豹虎夹陛阍。","青鸟去何之，谁向王母言。","徘徊岁华晚，感激生愁怨。"]},{"t":"游仙九首 其三","f":"五言古诗","c":["岐阳隐孤凤，寰海腾蛟蛇。","不食松柏实，而采日及花。","翩翩柱下史，望望之流沙。","麻姑何为者，乃降蔡经家。","神龙集洿泽，取笑于鱼虾。"]},{"t":"游仙九首 其七","f":"五言古诗","c":["费生市井儿，未尝识神仙。","偶然壶中去，谓是别有天。","幻化且不解，真诀安能传。","那将食色身，妄弄刑赏权。","果然失符后，众鬼不见怜。"]},{"t":"游仙九首 其八","f":"五言古诗","c":["天高河汉清，露白秋宵永。","朝华炫红芳，蟪蛄吊驰景。","繁思靡志帅，内疚积心梗。","涉江无方舟，汲井悲短绠。","岁莫霜雪寒，泣涕沾项领。"]},{"t":"游仙九首 其九","f":"五言古诗","c":["秦皇煽虐燄，烈烈燔九州。","平原旷如赭，鸿鹄安所投。","所以避世士，慨想乘桴浮。","楼船载侲子，去作汗漫游。","何必蓬莱山，远人即瀛洲。","虎视徒逐逐，竟死于沙丘。"]},{"t":"游仙九首 其四","f":"五言律诗","c":["娟娟姮娥女，灼灼芙蓉姿。","一入月宫去，千秋闭蛾眉。","凉风清玉除，碧云生桂枝。","凤歌不可听，长夜有馀悲。"]},{"t":"游仙九首 其五","f":"五言古诗","c":["晨登女床山，西北望昆崙。","楼台似霄汉，金碧气魂魂。","素女三千人，灼若扶桑暾。","鸾笙引凤舞，云旆随霓幡。","老童发清歌，昌容戏紫鹓。","神荼献丹桃，洪崖开玉尊。","蜚廉漫崔嵬，建章空千门。"]},{"t":"游仙九首 其六","f":"五言律诗","c":["大道久巳晦，谁能识仙真。","如何卖药翁，怪语惊市人。","日月空明照，朝菌非大椿。","巳矣复何道，去去生愁辛。"]},{"t":"感寓六首 其一","f":"五言古诗","c":["暑退生夕凉，褰衣步微月。","风来竹阴动，草暗萤光发。","伫立忽怀人，江河渺难越。"]},{"t":"感寓六首 其二","f":"五言古诗","c":["庭前金凤花，向晚争媚妩。","但见白露滋，岂知繁霜苦。","芳时良可惜，此物何足数。"]},{"t":"感寓六首 其三","f":"五言古诗","c":["白露下木叶，凄凉江海秋。","江皋有鸣雁，噭噭安所求。","稻粱日萧索，风雨徒离忧。"]},{"t":"感寓六首 其四","f":"五言古诗","c":["一日复一夕，一夕复一朝。","青灯向暗壁，光燄坐自消。","鞲鹰铩六翮，绝意于云霄。"]},{"t":"感寓六首 其五","f":"五言古诗","c":["严霜陨奥草，蛇虺去所依。","可惜蕙兰花，与之共颓萎。","顾此悲世运，泫然涕交颐。"]},{"t":"感寓六首 其六","f":"五言古诗","c":["凄凄素秋霜，苒苒高原草。","运穷相值遇，黝颜就枯槁。","浩叹采薇歌，惭愧商山老。"]},{"t":"招隐五首 其一","f":"五言古诗","c":["浮景无根株，逝川不可留。","昨日瑶草春，今朝蓬梗秋。","鼎食岂不美，酖毒潜戈矛。","华轩岂不贵，长路能摧辀。","子胥弃吴江，屈原赴湘流。","韩彭竟菹醢，萧樊亦累囚。","何如张子房，脱屣万户侯。","深韬黄石略，去从赤松游。"]},{"t":"招隐五首 其二","f":"五言古诗","c":["秦皇火六籍，黄绮之商山。","汉帝握乾符，羊裘竟不还。","古来遁世士，冥心丘壑间。","于时苟无用，安事空摧颜。","石泉清以芳，白云寒更闲。","春蔬杂甘辛，秋果罗青殷。","浊酒晚自酌，柴扉昼恒关。","啸歌陟崇冈，濯足临潺湲。","金马我何荣，羊肠我何艰。","鸿鹄翔九霄，邈然不可攀。"]},{"t":"招隐五首 其三","f":"五言古诗","c":["豫章长千仞，挺生崇崖阴。","布叶连青云，交柯蔽层岑。","结根岂不固，斤斧将见寻。","有柏生石间，屈曲丛灌林。","古根齧飞溜，电火焚中心。","大不中梁柱，小不堪瑟琴。","风霜自摇落，偃蹇独至今。"]},{"t":"招隐五首 其四","f":"五言古诗","c":["流水千百折，白云三四峰。","上有喷壑泉，下有凌霜松。","中有一老人，坐啸岩间风。","素发垂两肩，朱颜映青瞳。","年纪将百龄，容貌如孩童。","长跪前致辞，子非列仙翁。","笑谓汝孺子，语汝使心通。","我生不偶俗，遗身在蒿蓬。","结庐白水边，采药青林中。","世语我不接，世士我不逢。","箪瓢我不忧，轩盖我不崇。","自耕足我食，自息安我躬。","冥冥绝思虑，默默全和冲。","持此摄吾生，仰荷元化功。","何必插羽翰，远逐浮丘公。","再拜受斯言，廓然如发蒙。","投簪谢知己，一去无回踪。"]},{"t":"招隐五首 其五","f":"五言古诗","c":["有客款我庐，身披紫云袍。","鸣驺列前后，从者皆俊髦。","坐我蓬筚下，向我谈伊皋。","手斡北斗魁，足踏东海鳌。","高视六合内，泰山等毫毛。","挥袂起谢客，且还饮我醪。","醉卧不知晓，衡门塞蓬蒿。"]},{"t":"浣溪沙 处州叶叔安溪南草堂","f":"七言古诗","c":["细草垂杨村巷幽，白沙素石引溪流。","青苔矶上有扁舟。","门外好山开罨画，屋头新月学帘钩。","窗风一榻似清秋。"]},{"t":"眼儿媚","f":"古风","c":["烟草萋萋小楼西，云压雁声低。","两行疏柳，一丝残照，数点鸦栖。","春山碧树秋重绿，人在武陵溪。","无情明月，有情归梦，同到幽闺。"]},{"t":"少年游","f":"古风","c":["清风收雨，轻云漏月，凉气入幽窗。","乱叶吟朝，饥虫啼夜，各自奏新腔。","孤鸿又向天边落，归梦阻苍江。","百结愁肠，两行丝鬓，寂寞对清缸。"]},{"t":"小重山","f":"古风","c":["月满江城秋夜长，西风吹不断、桂花香。","碧天如水露华凉，人不见，有泪在罗裳。","何许雁南翔。","堪怜一片影、落孤房。","百年浮世事难量。","空回首，天阔海茫茫。"]},{"t":"临江仙","f":"古风","c":["街鼓无声更漏咽，不知残夜如何。","玉绳历落耿银河。","鹊惊穿暗树，露坠滴寒莎。","梦里相逢还共说，五湖烟水渔蓑。","镜中绿发渐无多。","泪如霜后叶，摵摵下庭柯。"]},{"t":"千秋岁 送别","f":"古风","c":["淡烟平楚，又送王孙去。","花有泪，莺无语。","芭蕉心一寸，杨柳丝千缕。","今夜雨，定应化作相思树。","忆昔欢游处。","触目成前古。","良宵会，知何许。","百杯桑落酒，三叠阳关句。","情未了，月明潮上迷津渚。"]},{"t":"瑞龙吟","f":"古风","c":["秋光好，无柰锦帐香销，绣帏寒早。","钩帘人立西风，送书过雁，依然又到。","故乡杳，空把泪随江水，梦萦池草。","何时赋得归来，倚松对柳，开尊醉倒。","衰鬓不堪临镜，镜中愁见，蓬飞丝绕。","门外远山青青，长带斜照。","石泉涧月，辜负夜猿啸。","伤心处，枫凋露渚，荷枯烟沼，燕去玄蝉老。","满天细雨鸣羁鸟，花蔓当檐袅。","庭院静，遥闻清砧声捣。","拥衾背壁，一灯红小。"]},{"t":"九叹九首 其二","f":"楚辞体","c":["我发种种兮飒如其稀。","我心伥伥兮忽若有遗。","过吾不能改兮德吾不能知。","往者不可悔兮来者不可期。","进无益于世兮退将安归。","呜呼巳矣兮吾宁不悲。"]},{"t":"九叹九首 其三","f":"楚辞体","c":["天有田兮不可以耕。","山有龟兮不可以知咎徵。","剡蒿以为梁兮削菌以居楹。","匠石却走兮工垂拊膺。","登高望远兮观四瀛。","水东流兮日西倾。","般纷纷兮各有营。","我独展转兮从夜达明。"]},{"t":"九叹九首 其四","f":"楚辞体","c":["风飘飘兮扬尘。","野寂寞兮无人。","舟何为兮山阿，车何为兮水滨。","北望楚兮东望秦。","倒江河兮乱星辰。","天门窈窕兮重九闉。","愿有言兮远莫陈。","虎豹颬颬兮为喜为瞋。","横流涕兮瞻苍旻。","心冯噫兮不能伸。","麋有角兮龙有鳞。","空山寂寥兮吾谁与邻。"]},{"t":"九叹九首 其五","f":"楚辞体","c":["江无舟兮河无梁。","隰有荆棘兮而无稻粱。","鹰化鸠兮雀变隼。","狸为貙兮龙为蚓。","眷长顾兮情纡轸。","九疑高兮禹穴幽。","梧桐枯兮凤不留。","山木惨惨兮叫鸺鹠。","鸿鹄飞兮无所投。","云沓沓兮雨悠悠。","孰怀情兮知此愁。"]},{"t":"九叹九首 其六","f":"楚辞体","c":["虎厌肉兮驺虞苦饥。","獭升堂兮麒麟受羁。","黄彝荐滫兮章甫承綦。","箾韶屏弃兮弦筦兜离。","指玉以为石兮削方以为规。","天不可问兮神不可咨。","繄彼之是兮而此之非。","有樗在林兮有栎在馗。","蓍龟孔昭兮勿远余思。"]},{"t":"九叹九首 其七","f":"楚辞体","c":["今夕何夕兮天宇清。","步逍遥兮仰观列星。","河汉皎兮北斗横。","悲风发兮候虫鸣。","林鸟起兮沙鸨惊。","长夜寥寥兮何人哭声。","怆恍悢兮不忍听。","回身入房兮泪沾缨。","蛟虬偃蹇兮射虎狞。","弧无弦兮车说其衡。","知不可虑兮谁女令。","謇淹留兮难为情。"]},{"t":"九叹九首 其八","f":"楚辞体","c":["履霜思裘兮燠则弃之，临河号舟兮济而置之。","不网胡鱼兮不弋胡鹄。","剪薙杞梓兮索灌莽以取木。","捕猫乳鼠兮佥以为仁。","吠笱宵警兮行者怒瞋。","弹鸾养枭兮莫知其咎。","斲冰以承宫兮曷云能又。","长太息兮有所思。","林木动兮巢鸟悲。","山有藿兮园有葵。","心怀君兮君不知。"]},{"t":"九叹九首 其九","f":"楚辞体","c":["秋天泬漻兮百草黄。","蟪蛄悲吟兮朝荣有芳。","屣履起兮独彷徨。","心悠悠兮怀故乡。","原有粟兮隰有禾。","桂花红兮兰紫芽。","凉风动兮松柏馨。","流潦落兮水泉清。","蔬可茹兮秫可酒。","集乡里兮会亲友。","坐白石兮荫苍筠。","玩明月兮思古人。","鱼韪渊兮狐首丘。","终余生兮安所求。"]},{"t":"秋日惨淡","f":"楚辞体","c":["秋日惨淡兮秋风其飔。","白露既下兮繁霜继之。","檗离其根兮叶脱其枝。","丰者黝颜兮柔者就萎，登高望远兮涕泗滂沱。","松柏稀少兮蒲柳何多。","露不盈条兮霜晨以晞，岁晏玄冰兮知将奈何。"]},{"t":"思归引","f":"楚辞体","c":["山高高兮可以望四荒。","胡跻尔颠兮而不见我故乡。","岁云莫兮无衣裳。","车罢马羸兮仆夫顿僵。","水有蛟鳄兮陆有虎狼。","于嗟柸何兮惟怀永伤。"]},{"t":"松筠轩歌","f":"楚辞体","c":["彼松之高兮，矫吾以其操兮。","此竹之节兮，耿吾以其洁兮。","露漙漙兮宵明，烟霏霏兮晓清。","风声我琴兮鸣鸐我笙。","淄胡为兮我衣，尘胡为兮我缨。","飕兮飗兮窈以幽，骖青鸾兮服苍虬。","吾与元气兮升降，与云霞兮绸缪。","逍遥兮相羊，终吾生兮乐以忘忧。"]},{"t":"渔父歌","f":"楚辞体","c":["江之水兮悠悠，深有鰋鲤兮浅有鲨与鯈。","桧为楫兮松为舟，其钓伊缗兮人谁女尤。","江之水兮娟娟，并葭吟风柳含兮扬烟。","有鲔在穴兮有鲂在渊，其钓伊丝兮人谁女愆。","江之水兮浪浪，泳之沄沄兮浮之洋洋。","有鱼与虾兮可钓以纲，无遐尔思兮人谁女伤。"]},{"t":"麦舟图歌","f":"楚辞体","c":["我马饱粟兮彼食不詜秕糠。","我麦满舟兮彼无以送其死亡。","我忽见兮哀不能忘。","推以与之兮我心乃康。","我闻在昔兮有虞夏商。","一夫百亩兮家有稻与梁。","生不饿殍兮死有藏。","呜呼今不得见兮使我心伤。"]},{"t":"山阴王景回友樵斋辞","f":"楚辞体","c":["稻粱离离兮稂莠骄骄。","麒不可以偶狼兮凤不可以侣枭。","求羊无人兮钟子寂寥。","哀风觱发兮原野萧条。","四顾彷徨兮忧心且焦。","若有人兮在山椒。","携粮负薪兮啸歌以遨。","黜陟无闻兮宠辱不摇。","呜呼吾尔群兮去无待子招。","临流泉兮倚逍遥。","无斤我松兮无使柏也凋。"]},{"t":"柳桥渔唱二首为黄中立作 其一","f":"楚辞体","c":["春风淡淡兮湖水波。","柳乘桥兮青烟满莎。","扣予舷兮发长歌。","靡曰蘋兮乱鴐鹅。","前有蛟兮后有鼍。","予往予还兮吁予奈何。"]},{"t":"柳桥渔唱二首为黄中立作 其二","f":"楚辞体","c":["彼湖有波兮此栯有柳。","我维我舟兮聊以搔我首。","放歌逍遥兮哀莫予偶。","有箨住罾兮有沙在罶。","逝者滔滔兮羌不可以久。","绿蘋兮菲菲。","落花兮点衣。","江无津兮海无涯。","呜呼寂寥兮吾谁与归。"]},{"t":"获麟操","f":"楚辞体","c":["有兽维麟兮猎者获之。","折肢毁肤兮曾不如鹿与麋。","呜呼哀哉兮尔何生于此时。","周公巳矣兮吾能不悲。"]},{"t":"在陈操","f":"楚辞体","c":["彼山有杨兮彼隰有栩。","彼路斯何兮孔棘且阻。","玄云杳冥兮不日以雨。","重华寂寥兮谁与晤语。","茫茫九州兮孰为予所。","龟蒙无人兮驾予归处。"]},{"t":"白云歌为良上人作","f":"楚辞体","c":["青山兮翠微。","白云兮孤飞。","怀游子兮远于离。","不如云兮倏往而韪。","白云兮容与。","青山兮欲雨。","怀予亲兮在云之下。","云兮云兮归予从女。"]},{"t":"秋山图歌","f":"楚辞体","c":["秋风起兮萧萧。","望青山兮寂寥。","水泠泠兮出石，叶槭槭兮辞条。","气悽悽兮就寒，夜耿耿兮不朝。","凤凰兮安之，梧桐兮早凋。","思美人兮隔江河，玄云冥兮天路遥。","托宵梦兮远狙征，款扶桑兮倚消遥。","盼青鵻兮不来，怆恍悢兮魂屡飘。","愿乘风兮绝浮云，要洪崖兮访子乔。","高无梯兮深无航，鼋鼍陆梁兮虎豹骄。","归来兮归来，紫芝有荑兮黄精有苗。"]},{"t":"梁孝子庐墓词","f":"楚辞体","c":["陟彼岵兮望父，陟彼屺兮望母。","若仪容兮在前，恍音声兮在后。","陟彼屺兮望母，陟彼岵兮望父。","惝恍惘兮无闻，心摇摇兮愁苦。","闻空庐兮山之巅，朝松有岚兮暮萝有烟。","其下维地兮其上维天，食思寝思兮以日以年。","呜呼魂乎其有知兮矢相从于九泉。"]},{"t":"送龙门子入仙华山辞","f":"楚辞体","c":["青山崔嵬兮烟云杳冥，回溪郁纡兮岩谷晦明。","脩篁杂树兮相蔽亏，洞壑窈窕兮人不知。","清猿警夜兮鹤报晨，花开鸟啼兮长如春。","隰有芷兮陵有苕，美人不来兮山寂寥。","琼芝兮玉华，丹荑兮翠葩。","紫葛兮黄精，礧碨兮鬖髿。","蜚梁连蜷兮登降峛崺，幽漻阒碌兮敞晃谲诡。","芳兰桂椒兮或红或紫。","松风涧泉兮金石盈耳。","梧柤萋萋兮竹实蕊蕊，凤凰翔鸣兮五色卉炜。","望美人兮翠微，空山寂寥兮迟尔来归。","霓为衣兮霞为裳，饮沆瀣兮食瑶浆。","睎正阳兮澡沦阴，精神完兮毛发香。","握六符兮蹑九灵，被矞云兮歌洞章。","御扶摇兮款天门，诣北斗兮觐虚皇。","超鸿濛兮轶布夷，造无始兮逍遥娭。","召秦女兮吹箫，使湘娥兮弹丝。","洪崖啸歌兮王母启齿，万舞齐进兮襟佩飒纚。","长离前驱兮鸾鸟为使，苍龙騑騑兮白虎豸豸。","雷公磅硠兮列缺旭虺。","登明堂兮绝河津，上阁道兮攀勾陈。","过三危兮绕玄冥，出太微兮入西清。","憩牛渚兮泛灵槎，乘回飙兮以还家。","美人兮归来，山中兮其乐无涯。"]},{"t":"王彦中哀辞","f":"楚辞体","c":["朝士兮雁行，暮归兮相将。","联綵服兮上高堂，棣华茂兮亲乐康。","忽秋霜兮夏零，凄风发兮凋紫荆。","同气两身兮一死一生，车只其轮兮嗟何以行。","窈窈兮愔愔，想形容兮不可寻。","饮泣兮吞声，恐慈亲兮伤心。","俯重泉兮永隔，掩此哀兮何极。","尽礼事生兮恪恭子职，是谓孝友兮死者瞑目。"]},{"t":"上之回","f":"古风","c":["上之回，六龙矫；","揵光耀，拂鹥鸟。","轥石关，匝棠梨。","扬灵旗，县月支。","天马来，宛居劙。","穆上玄，釐穰穰。","坐明堂，朝万方。","翕披离，王烛光。","于亿年，乐未央。"]},{"t":"朱鹭","f":"古风","c":["朱鹭来，玉山巅。","赪翁引，熛臆延。","朱鹭来，赩流霞。","饮赤水，食丹砂。","朱鹭来，炎德加。","威昆明，滇僰讹。","朱鹭来，集太液。","帝锡祐，荒广斥。","朱鹭来，烨煌煌。","挟鹪雕，媒凤凰。","朱鹭来，皇之辉。","神筴滨，无穷期。"]},{"t":"君马黄","f":"古风","c":["君马黄，我马骊，二马八足争驱驰。","回头顾影双骄嘶，尾端散作赪虹飞。","黄马曜日黄金晶，骊马谓是玄天精，眼前好丑那能明。","吾闻良骥称以德，不闻矜此骊黄色。","世无伯乐识者谁，有德无色空自知。"]},{"t":"关山月","f":"古风","c":["关山月明风恻恻，万里黄云杂沙砾。","夜深羌笛吹一声，征人相看泪沾臆。","古人以绥服奋武卫，耕战守禦不外求。","何人倡此戍边策，千载以贻中国忧。","关山月，圆复缺，何忍年年照离别。","愿得驰光照明主，莫遣边人望乡苦。"]},{"t":"上清词三首 其一","f":"古风","c":["王子晋，好吹笙，吹得神仙下玉京。","一朝羽化随风去，回首故宫芳草生。"]},{"t":"上清词三首 其二","f":"古风","c":["天上月，影悠悠，似镜看看又似钩。","自是嫦娥甘寂寞，桂华相对度千秋。"]},{"t":"上清词三首 其三","f":"古风","c":["河汉水，九秋清，凉月满空闻雁声。","雁声不到梦先到，白露湿衣天未明。"]},{"t":"江上曲八首 其一","f":"七言绝句","c":["数树垂杨绿水边，问郎何不系兰船？","浦沙新涨青山远，半夜月明无杜鹃。"]},{"t":"江上曲八首 其二","f":"七言绝句","c":["曾记楼船夜泊时，家家弦管斗腰肢。","于今弦管归何处，绾束枯蒲当酒旗。"]},{"t":"江上曲八首 其三","f":"七言绝句","c":["昨夜月明天似水，今晨月落水如天。","天长水远人何处，芦苇萧萧一抹烟。"]},{"t":"江上曲八首 其七","f":"七言绝句","c":["忆见垂杨缒绿丝，陟看秋菊映疏篱。","柳花作絮随风去，菊绽金葩欲似谁。"]},{"t":"夜夜曲","f":"古风","c":["冬夜恒苦长，夏夜恒苦短。","短长相蔽亏，殷勤望推挽。","纫茅作绳绳易断，汲水作池池易旱。","故镜尘昏难远照，故衣絮敝无新暖。","西风袅袅吹桂枝，白露点苔黄叶满。"]},{"t":"秋夜曲","f":"五言古诗","c":["木落霜露繁，乌啼夜方永。","起行望明月，西风吹雁影。","雁飞一何急，乌啼安所集。","徘徊不能寐，望月空伫立。","伫立河汉倾，谁家砧杵声。","关山渺千里，何处不伤情。"]},{"t":"墙头花","f":"古风","c":["墙头花，红锦妒。","美人抱瑟倚高楼，只恐花飞逐风去。","荧荧绛蜡送残宵，燕语莺啼斜日暮。"]},{"t":"长松梢","f":"古风","c":["长松梢，青拂天。","岁暮商飙急，寒苦令人怜。","阴崖有朴樕，生在荆棘下。","霜凋荆棘叶，网缀如檐瓦。","春风破冰冻，劲绿不曾赭。","祸福相倚伏，岂不在所招。","宁为朴樕茎，莫作长松梢。"]},{"t":"折杨柳","f":"七言古诗","c":["东风二月春如酒，不见百花惟见柳。","柳丝绾烟留暝鸦，柳花荡漾迷羲和。","美人捲帘看不足，柳色萋萋妒娥绿。","夜来微雨清郊圻，莺黄相应鸣埙篪。","欲寄柔条无信使，空将泪染回文字。"]},{"t":"结交行","f":"古风","c":["朋友以义合，久要贵不忘。","结交或匪人，驺虞化为狼。","君不见市井人，杯酒忽相得，倾肝泻胆无所惜。","一朝需求不称意，口里驱蛩心上蚝。","更闻背语触疑心，墙角车轮亦生趐。","君不见耳与馀，又不见田与窦，当其得意时，刎颈以相就。","宁知嫌隙反掌成，坐令衽席生戎兵。","古人重结交，晏子真其人。","伾文执谊，羊豕之合，死生弃置安足陈。"]},{"t":"春日行","f":"古风","c":["白日出东陆，垂光曜中天。","大哉至阳德，荡萡无颇偏。","坐令惨烈化滋润，顷刻枯槁回鲜妍。","圣人法天道，神化参玄微。","春朝著典礼，上下同光晖。","垂衣向明物自育，帝力皞皞无人知。","春天和，春日丽，但愿宇宙长如春，圣明天子千万岁！"]},{"t":"王昭君","f":"七言古诗","c":["汉庭不赏徼功士，昭君却向胡中死。","昭君辞汉入胡中，胡女悲愁汉嫔喜。","含情欲怨当语谁，手弹琵琶泪沾衣。","掖庭望幸从此绝，巫山有路他生归。","殷勤说与上林雁，好在月年再相见。","汉恩如海长自深，妾自生来命如线。","贱妾一身何足惜，可惜当年刘敬策。","遂令上策重和亲，欲倚红颜清塞尘。","只恐妾身先草露，汉宫无复如花人。"]},{"t":"塘上行","f":"古风","c":["塘上何所有，有蒲与荷花。","蒲花难开荷易落，使我叹恨长咨嗟。","鸳鸯戏我后，鸧鸹翔我前。","四顾不见人，泪下如流泉。","浮萍违渌井，寄身沧江渚。","沧江不应竭，是妾命如许。","朝泪洒玉台，夕泪沾罗衾。","采荷得见莲，中复怀苦心。","广筵列肴蔬，好者即美味。","荼蓼有时甘，菘葵有时弃。","严风吹秋林，蕙兰化为草。","于悒今可憎，芳菲故尝好。","行亦私自怜，坐亦私自怜。","愿为天边月，流影玉阶前。"]},{"t":"美女篇","f":"五言古诗","c":["南国有美女，粲粲玉雪颜。","眉目艳华月，色映清秋寒。","粉黛不敢涴，佩服惟幽兰。","一朝备选择，得厕金宫班。","贞心耻自衒，望幸良独难。","况蒙众女妒，倩笑谁为欢。","恒恐芳桂枝，寂寞零露漙。","素手发瑶琴，泠泠奏孤鸾。","宫商合要妙，遗响风珊珊。","大音世罕识，日暮空盘桓。","安得托宵梦，集君瑶台端。","相思不可极，踯躅起长叹。"]},{"t":"宛转歌","f":"七言古诗","c":["星稀月白河阑干，饥虫吁号莎草寒。","美人望月歌宛转，潇湘水碧苍梧远。","愁魂一夜不得归，化作断云天际飞。"]},{"t":"雉子班","f":"古风","c":["雉子班，飞翛翛，鸣鷕鷕。","踉蹡出没灌莽中，衮裳焕烂赪瞳瞭。","野人拄翳潜置媒，和声相应无惊猜。","黄间一发激流电，锦绣披裂委草莱。","林栖野啄本无累，嗜欲沉溺祸所胎。","君不见天池凤凰食竹实，逍遥至和永终日。"]},{"t":"朗月行","f":"古风","c":["朗月何胧胧，照我绮窗中。","窗中美人不能寐，起看玉宇生秋风。","秋风飘飖吹木末，纤云卷尽悬明月。","明月随风出海来，海水荡漾龙鳞开。","寒光喷浸碧落外，白浪涌作金银台。","何处悲风怨羌管，谁家舞榭笙箕暖。","长信宫中漏水长，昭阳殿里更筹短。","漏长更短总含情，开窗坐视河汉倾。","广寒宫，在何处，欲往从之渺烟雾。","青鵻汗漫不可期，桂华如雪东方曙。"]},{"t":"出塞","f":"七言古诗","c":["居延风高检叶空，狼烟夜照甘泉宫。","将军授金虎士怒，蚩尤亘天旗尾红。","麒麟前殿催赐酒，巳觉此身非己有。","猛气遥将日逐吞，壮心肯落嫖姚后。","雁门城外沙如雪，玉帐霜浓铁衣折。","长剑须披瀚海云，哀笳莫怨天边月。","北风烈烈刁斗鸣，回看北斗南方明。","惊箭离弦车在坂，不勒燕然终不返。"]},{"t":"入塞","f":"七言律诗","c":["狐裘蒙茸沙碛里，望见玉关惊且喜。","关门候吏记曾逄，白发相看泪如水。","归来放马咸阳原，旧游今有几人存。","斜阳惨淡照篱落，闲看邻翁戏子孙。"]},{"t":"蜀国弦","f":"七言古诗","c":["胡笳拍断玄冰结，湘灵曲终斑竹裂。","为君更奏蜀国弦，一弹一声飞上天。","蜀国周遭五千里，峨眉岧岧连玉垒。","岷嶓出水作大江，地砉天浮戒南纪。","舒为五色朝霞晖，惨为虎豹嗥阴霏。","翕为千嶂云雨入，嘘为百里雷霆飞。","白盐雪消春水满，谷鸟相呼锦城暖。","巴姬倚歌汉女和，杨柳压桥花纂纂。","铜梁翠气通青蛉，碧鸡啼落天上星。","山都号风寡狐泣，杜鹃呜咽愁幽冥。","商悲羽怒听未了，穷猿三声巫峡晓。","瞿塘喷浪翻九渊，倒泻流泉喧木杪。","楼头仲宣羁旅客，故乡渺渺音尘隔。","含悽更听蜀国音，不待天明头尽白。"]},{"t":"昔昔盐","f":"五言古诗","c":["杨柳正萋萋，门前碧草齐。","别离如昨日，白发满春闺。","飘花兼泪落，行云逐望迷。","绿苔凝履迹，粉汗浥书题。","梦到龙沙北，魂销马邑西。","卷帘双燕入，开镜一莺啼。","肠共吴江绕，眉将楚岫低。","攀枝怜并蒂，窥沼妒双栖。","跃水宁无剑，通天亦有犀。","那看明月夜，登楼惑马蹄。"]},{"t":"乌栖曲 其一","f":"七言绝句","c":["霜华著树成秋蕊，树头栖乌惊夜起。","起向幽闺啼数声，闺中美人泣到明。"]},{"t":"乌栖曲 其二","f":"七言绝句","c":["吴宫乌啼夜巳分，宫中不闻人尽闻。","夜深风落茱萸子，沉沉漏断啼乌死。"]},{"t":"三洲曲 其一","f":"七言绝句","c":["三洲洲上花柳春，三洲浦里多商人。","酒旗红袖明江阁，客船只望洲边泊。"]},{"t":"三洲曲 其二","f":"七言绝句","c":["八月风吹洲上树，楼船却向江西去。","红妆送别各沾巾，惊动新米江北人。"]},{"t":"武陵深行","f":"古风","c":["武陵溪，一何深。","水有射工射人影。","陆有丹蛇长百寻，嗟哉武溪不可临。","溪之水深且阔乌，不敢飞龙不敢越。","海气连天日月昏，茵露著人肌肉裂。","呜呼，丈夫宁能沙场百战死，有骨莫葬武溪水。"]},{"t":"明月子","f":"七言律诗","c":["朱阁绮疏琼作户，明月照人秋独苦。","桂花吹冷眠不成，谁家高楼弦管声？","倚楼空望别离处，唯有清光自来去。","月圆正好缺复催，人生见月能几回。"]},{"t":"短歌行","f":"古风","c":["来日苦短，去日苦长。","日长不自觉，日短令人伤。","君不见望后月又不见霜中蕊，清光纵好魄巳亏。","芳心欲动根先死，少年不知老可悲，衰老却忆少年时。"]},{"t":"长安道","f":"古风","c":["长安道，送尽芳菲到枯槁。","人生衰盛苦不常，何异长安道傍草。","汉家将军初拜官，门前上客车班班。","一朝世衰烟燄歇，车轮无声马蹄绝。","明年有诏封冠军，依旧车马来如云。"]},{"t":"陇头水","f":"古风","c":["陇头水，征夫泪，征夫之泪滴陇头，化为水入秦川流。","水流向秦川，呜咽鸣不巳。","何因得天风，吹入君王耳。"]},{"t":"秋宵吟","f":"七言律诗","c":["玄蝉催秋入湘潭，芙蓉露浴胭脂淡。","铜乌吻水添夜长，碧草敛愁归寒螀。","罗帐无人五更雨，梧桐惊啼白杨语。","春光烂熳不得知，霜露凄凉奈何汝。"]},{"t":"车遥遥","f":"古风","c":["车遥遥，马朅朅。","不知何人始作车，长与人间载离别。","回风吹起罗帐尘，低头旨杀作车人。"]},{"t":"阳春歌","f":"七言古诗","c":["帝车东指淑景昭，冶容冉冉生寒条。","枯根相顾一时起，阳春只在霜雪里。","枝头候禽鸣滑滑，暖烟火夜催花发。","蜂喧蝶竞方及时，风雨宿昔成离披。","人间但见阳春好，未识春阳有枯槁。"]},{"t":"鸣雁行","f":"古风","c":["??鸣雁鸣达旦，举翼相连拂云汉。","平原漠漠生野烟，雁飞只向江南天。","江南十月多禾黍，一半轮官半供汝。","明年二月归养雏，雏成又望江南去。"]},{"t":"独不见","f":"七言律诗","c":["暖烟漾春林色紫，腻雨摧红出花蕊。","蝶飞撩乱燕飞轻，嘤鸣相应俱有情。","有人抱瑟上高阔，坐对妆台弹别鹤。","曲终顾影还徘徊，东风自吹罗帐开。"]},{"t":"梅花落","f":"古风","c":["种梅长江边，岁冕花始发。","东风为爱桃与李，却使孤芳坐销歇。","美人高楼深紫霞，捲帘一见长叹嗟。","世间有荣即有悴，君不见海中碧树终无花。"]},{"t":"折杨柳","f":"七言古诗","c":["去年送君杨柳青，暖风晴日花冥冥。","今日思君琐窗绿，柳条又缀黄金粟。","君心却似条上花，随风飘荡不思家。","妾心巳作科上槁，纵得春光为谁好。","折取长条寄远人，人生四十无青春。"]},{"t":"秋夜月","f":"古风","c":["秋夜月，黄金波，照人哭，照人歌。","人歌人哭月长好，月缺月圆人自老。"]},{"t":"枣下何纂纂行","f":"古风","c":["枣初作花时，纂纂临路岐。","八月枣成实，累累曜朝日。","枣花纂纂蜂蝶翻，枣实累累人满园。","严风萧瑟枯叶飞，蜂蝶不来人亦稀。"]},{"t":"蛱蝶行","f":"七言律诗","c":["软芳晞露春鲜妍，上有蛱蝶飞翩翩。","暖风扶暝扑天起，翠重红轻迷欲死。","东园无花留不住，相随又过西园去。","沉沉断梦失韩凭，却抱霜华怨秋曙。"]},{"t":"周小史","f":"五言古诗","c":["婉娈周小童，洽容敌花红。","鲜云委绿发，明星烱双瞳。","禾兰澧水湄，挟弹长陵东。","掷果閧春市，卷衣娇金宫。","流盼溢华彩，言笑生芳风。","常恐秋露零，瑶草成衰蓬。","食桃坐翻覆，倩笑徒为工。","繁华岂不好，不知身所终。","吾闻济川楫，乃属植鳍翁。","悠悠万世下，德业光无穷。"]},{"t":"结袜子","f":"五言古诗","c":["昔有信陵君，乃在大梁城。","亲为贵介弟，位冠诸侯卿。","倾家待国士，倒屣延豪英。","诣门谒朱玄，虚左上侯嬴。","袖椎夺兵符，救赵蜚英声。","河外走蒙骜，宗社赖扶倾。","于今不可见，寂寞伤人情。"]},{"t":"拔蒲三首 其一","f":"五言绝句","c":["拔蒲清川渚，水浅蒲不长。","自非排风羽，莫羡凌云翔。"]},{"t":"拔蒲三首 其二","f":"五言绝句","c":["拔蒲江水湄，终日不盈把。","嫌杀紫鸳鸯，双戏蒲叶下。"]},{"t":"拔蒲三首 其三","f":"五言绝句","c":["拔蒲复拔蒲，织作波纹簟。","无处寄相思，秋风露莲淡。"]},{"t":"公无渡河","f":"古风","c":["丈夫不爱死，成仁心所安。","殒身苟无故，哀哉徒自残。","水能杀人人共知，公独茫然狂以痴。","黄河渺渺无津涯，乃欲绝流而渡之。","公也溺死人谁悲，世路如何，险恶实多？","平地倏忽，滔天风波。","利淫欲饵，孰知其佗？","不见不闻，纵横网罗。","固不必如公之痴，可揕以鱼中之铍，亦不必如公之狂，可禽以伏甲之觞。","眼前言笑百媚出，宁知兵刃罗心肠。","公无渡河河无津，箜篌一曲愁杀人。"]},{"t":"步虚词 其一","f":"五言古诗","c":["太微启灵宇，紫殿含祥风。","圆光昭无外，梵气来冲融。","仙人鱼鳞次，羽葆朝当中。","离罗郁萧台，缥缈浮太蒙。","泰阶平六符，文昌位三公。","北斗运元化，轩辕成岁功。","稽首玉陛下，逍遥乐无穷。"]},{"t":"步虚词 其二","f":"五言古诗","c":["郁华开赤殿，结邻炫黄文。","葳蕤烂霄汉，照曜下土坟。","东华跸严驾，西崦泮昏氛。","神行肃亹亹，象化陶醺醺。","景风调坱圠，玉烛焕烟煴。","冥茫密勿间，歘忽幽朗分。","万灵仰无私，九真告成勋。"]},{"t":"步虚词 其三","f":"五言古诗","c":["重阳峨宝阙，众星拱高垣。","寥寥太虚庭，巍巍无极尊。","白虎伏右騑，青龙承左辕。","玄武后躨跜，长离前腾骞。","黄灵正常居，万有归一元。","希微眇稊粟，浩荡灸乾坤。","高卑各奠位，神化无穷源。"]},{"t":"步虚词 其四","f":"五言古诗","c":["步虚归太一，精心觐枢庭。","浮浮回极运，湛湛规中清。","五神谨诃卫，六位肃敉宁。","东溟升阳曜，西海生阴露。","炎光熺玄室，涌醴液朱陵。","骎骎粗秽除，绵绵淳粹凝。","妙用无边方，摄身游帝青。"]},{"t":"步虚词 其五","f":"五言古诗","c":["焚香礼玄梵，肃驾朝紫宸。","游云结华盖，鲜飙翼飞轮。","披烟上阁道，佩月攀钩陈。","服食丹霞浆，嗽咽甘露津。","琅琅歌洞章，寂感虚皇嚬。","飘飖广莫风，舒啸青林春。","沆瀁六合外，永与无始邻。"]},{"t":"神弦曲","f":"七言古诗","c":["紫桂飘香九万里，三山地色如凝水。","水妃骨冷不能眠，金簪素指敲冰弦。","泠泠玉泉滴贝阙，闺壑嫠鲛泣幽碧。","青瞳小髻歌繁霜，霜飞风起江低昂。","曈昽紫燄出海树，天清月落空相望。"]},{"t":"长歌行","f":"七言古诗","c":["秋夜夜长月照轩，梦见天神与我言。","眶灵循环周四垣，四时迭代成寒温。","枯荣生杀相为根，我于万物何怨恩。","生丁其时命所存，六淫汹涌无键阍。","由其弗约离其魂，春葩敷披夏实繁。","外美中瘁谁能扪，风霜涸寒肃不骞。","纳华状真归本元，扫涤浮秽夫何冤。","我今语女开女昏，生生杀杀无穷源。","敛女旨蓄守女门，扶桑赫赫升朝暾。"]},{"t":"江南弄七首 其一","f":"古风","c":["江南细水缃绮波，江南綵女雏凤歌，凝嚬引睇纡青蛾。","纡青蛾，舒窈窕，网轩绣户锁娇春，不放杜鹃来木杪。"]},{"t":"江南弄七首 其二","f":"古风","c":["雄龙呼雌江底鸣，山摇谷殷江波惊，馀音不断随风征。","随风征，入湘竹，截玉钻星吹向天，楚江六月无炎燠。"]},{"t":"江南弄七首 其三","f":"古风","c":["湖波澄明日色鲜，画鹢相随出采莲，娇红曼绿斗春妍。","斗春妍，倚徘徊，今朝花尽且归去，明日更有新花开。"]},{"t":"江南弄七首 其四","f":"古风","c":["河曲悬匏渭滨竹，碧鲜削出蓝田玉，轻翎参差飞羽谡。","飞羽谡，幽簧含，丹樱瑶笋调清吹，月明紫凤来??。"]},{"t":"江南弄七首 其五","f":"古风","c":["采菱女子木兰船，翠裙红袖青玉钿，摇光荡影惜婵娟。","惜婵娟，愁夕晖，拔蒲歌断鲤鱼入，归去芰荷香满衣。"]},{"t":"江南弄七首 其六","f":"古风","c":["江草萋萋春渺渺，江皋出游多窈窕，轻霞衣裳碧云袅。","碧云袅，红日斜，鸳鸯飞过绿渚去，东风吹落菖蒲花。"]},{"t":"江南弄七首 其七","f":"古风","c":["巫山岧峣巫峡长，瑶姬出舞朝云翔，翠葩婹袅金支光。","金支光，丹叶赩，宝鸡为使凤为骖，去雨来风乐无极。"]},{"t":"步出夏门行","f":"古风","c":["步出夏门，遥望沧海。","九河茫茫，碣石安在？","鱼龙瀺灂，日月晻蔼。","三山何所，弱水浼浼。","羲和曷往，鳌极孰宰。","发鸠之羽，其心不改。","安期不死，桃实可待。","悠哉沛乎，歌以未慨。"]},{"t":"丹霞蔽日行","f":"五言古诗","c":["彤霞何煌煌，蔽此白日色。","炎埃被九野，照灼后土赤。","朱陵开火府，熺烂相荡射。","山蒸绛红气，川泻丹砂液。","穹玄变光曜，众草相烜赫。","迥迷河林茜，高夺昆仑碧。","郁华不能神，玄乌巳化魄。","女娲在青天，岁莫还鍊石。"]},{"t":"乌生八九子","f":"古风","c":["树上乌，一生八九子，相呼哑哑聒人耳。","何不学衔泥燕，和鸣集桃李。","又不学鹰与隼，奋翅高飞碧云里。","胡为巢此庭树间，啄腐吞腥饕吻觜。","少年挟弹如流星，祸机潜发不见形。","翅翎槯析身首磔，蝼蚁伤残谁女惜。"]},{"t":"猛虎行","f":"古风","c":["君不见昔者牛哀病，七日化作猛虎形。","躨跜衣裳佩带换毛尾，弃置衽席眠茅茨。","怒牙出吻目闪电，顷刻不识妻与儿。","昨日灯前相笑语，岂意今朝化为虎。","呜呼，世上茫茫化虎人，秪应化心不化身。"]},{"t":"行路难 其一","f":"古风","c":["君不见水上澌，往来倏忽随波移。","又不见花上蜂，东枝飘落寻西枝。","世人食葵不食檗，莫倚结交心匪石。","君不见避席武安人，即是当年窦家客。"]},{"t":"行路难 其二","f":"古风","c":["君不见白日光，不照幽草心。","又不见石上云，肤寸遂成阴。","世间会合良难得，况有巧言能烁金。","伏波槁葬魏碑仆，当时岂是非知音？","智谋启疑忠逆耳，平地反掌生崎嵚。","行路难，愁最深。"]},{"t":"野田黄雀行","f":"古风","c":["野田雀，觜啄啄，朝食山下禾，暮食山上粟。","千百为群丛薄里，忽然惊飞若蜂起。","飞飞却落稻田中，众口齐啄稻为空。","农夫力田望秋至，沐雨梳风尽劳瘁。","王租未了私债多，况复尔辈频经过。","野田雀鹰隼，高翔不汝击，农夫田父愁何极！"]},{"t":"何当行","f":"古风","c":["念离莫悲歌，悲歌惨于哭。","思乡莫望远，望远伤心目。","九疑迢迢隔湘川，空山落日啼杜鹃。","梧桐摧折凤凰去，蛟蜃出没波滔天。","令我四顾心茫然，泪如悬崖泻流泉。","樊桐有路到玄圃，何当飞堕王母前。"]},{"t":"射虎词","f":"七言古诗","c":["长戈如林夹弓弩，言向深山射猛虎。","獠儿蒙鹖走如风，所过犬羊皆为空。","纷纷散入人家宿，丁男上山妇女哭。","前行闻虎心先畏，一虎当头万夫弃。","折弓坠刃委如土，却向人前作威武。"]},{"t":"长相思","f":"古风","c":["长相思，妾在天南君在北，红颜未必无人知。","葑菲不羡君王食，相思迢迢隔天河，长夜不眠愁柰何。","欲凭魂梦到君所，君门九重虎豹多。","长相思，向谁道？","凉风日夕吹桂枝，可惜馨香暗中老。"]}]};